import type { BankQuestion } from "@/lib/bank";

/** Simple Interest (Quantitative Aptitude): 208 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-simple-interest-1","question":"At what rate of simple interest will a sum double itself in 10 years?","options":["5%","8%","10%","12%"],"answer":2,"explanation":"Doubling means SI = P, so R × 10/100 = 1 and R = 100/10 = 10%. 5% would only take the sum to 1.5 times in 10 years, a common halving slip.","difficulty":"moderate","questionHi":"साधारण ब्याज की किस दर से कोई धनराशि 10 वर्ष में स्वयं की दोगुनी हो जाएगी?","optionsHi":["5%","8%","10%","12%"],"explanationHi":"दोगुना होने का अर्थ है SI = P, इसलिए R × 10/100 = 1 और R = 100/10 = 10%। 5% पर 10 वर्ष में राशि केवल 1.5 गुना होती, जो आधा कर देने की आम भूल है।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-2","question":"Amount at simple interest equals:","options":["Principal × Rate","Principal + Simple Interest","Principal − Simple Interest","Rate × Time"],"answer":1,"explanation":"Amount = Principal + Simple Interest, the total repaid at the end. Principal − SI has the sign the wrong way, and Principal × Rate or Rate × Time are only parts of the SI formula PRT/100.","difficulty":"easy","questionHi":"साधारण ब्याज पर मिश्रधन बराबर होता है:","optionsHi":["मूलधन × दर","मूलधन + साधारण ब्याज","मूलधन − साधारण ब्याज","दर × समय"],"explanationHi":"मिश्रधन = मूलधन + साधारण ब्याज, यानी अंत में चुकाई जाने वाली कुल राशि। मूलधन − SI में चिह्न गलत है, और मूलधन × दर या दर × समय SI के सूत्र PRT/100 के केवल अंश हैं।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-3","question":"The simple interest on ₹1,000 at 5% per annum for 2 years is:","options":["₹50","₹100","₹150","₹200"],"answer":1,"explanation":"SI = PRT/100 = 1,000 × 5 × 2/100 = ₹100. ₹50 is one year's interest only, and ₹200 doubles the rate.","difficulty":"easy","questionHi":"₹1,000 पर 5% वार्षिक दर से 2 वर्ष का साधारण ब्याज है:","optionsHi":["₹50","₹100","₹150","₹200"],"explanationHi":"SI = PRT/100 = 1,000 × 5 × 2/100 = ₹100। ₹50 केवल एक वर्ष का ब्याज है, और ₹200 में दर को दोगुना कर दिया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-4","question":"A sum becomes ₹1,200 in 2 years and ₹1,500 in 5 years at simple interest. The rate of interest is:","options":["5%","8%","10%","12%"],"answer":2,"explanation":"Interest for 3 years = 1,500 − 1,200 = ₹300, so ₹100 per year. Principal = 1,200 − 2 × 100 = ₹1,000; rate = 100 ÷ 1,000 × 100 = 10%.","difficulty":"hard","questionHi":"साधारण ब्याज पर कोई धनराशि 2 वर्ष में ₹1,200 और 5 वर्ष में ₹1,500 हो जाती है। ब्याज की दर है:","optionsHi":["5%","8%","10%","12%"],"explanationHi":"3 वर्ष का ब्याज = 1,500 − 1,200 = ₹300, अतः प्रति वर्ष ₹100। मूलधन = 1,200 − 2 × 100 = ₹1,000; दर = 100 ÷ 1,000 × 100 = 10%।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-5","question":"Simple interest on ₹5,000 at 8% per annum for 3 years is:","options":["₹1,000","₹1,200","₹1,500","₹2,400"],"answer":1,"explanation":"SI = 5,000 × 8 × 3/100 = ₹1,200 (₹400 a year for 3 years). ₹2,400 doubles the answer, and ₹1,500 uses 10% instead of 8%.","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"₹5,000 पर 8% वार्षिक दर से 3 वर्ष का साधारण ब्याज है:","optionsHi":["₹1,000","₹1,200","₹1,500","₹2,400"],"explanationHi":"SI = 5,000 × 8 × 3/100 = ₹1,200 (3 वर्ष तक प्रति वर्ष ₹400)। ₹2,400 में उत्तर को दोगुना कर दिया गया है, और ₹1,500 में 8% की जगह 10% लिया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-6","question":"At what rate of simple interest per annum will a sum become 1.6 times itself in 5 years?","options":["6%","12%","20%","32%"],"answer":1,"explanation":"The interest is 0.6 of the principal in 5 years, so R = 60/5 = 12%. 32% treats the whole 1.6 times (160%) as interest, 20% is the rate that doubles a sum in 5 years, and 6% is half the correct rate.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"साधारण ब्याज की किस वार्षिक दर से कोई धनराशि 5 वर्ष में स्वयं की 1.6 गुना हो जाएगी?","optionsHi":["6%","12%","20%","32%"],"explanationHi":"5 वर्ष में ब्याज मूलधन का 0.6 है, अतः R = 60/5 = 12%। 32% में पूरे 1.6 गुना (160%) को ब्याज मान लिया गया है, 20% वह दर है जिस पर राशि 5 वर्ष में दोगुनी होती है, और 6% सही दर का आधा है।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-7","question":"At simple interest a sum amounts to ₹6,500 in 3 years and ₹7,500 in 5 years. The sum is:","options":["₹4,500","₹5,000","₹5,500","₹6,000"],"answer":1,"explanation":"Two years’ interest = 1,000 ⇒ ₹500 per year ⇒ P = 6,500 − 1,500 = ₹5,000.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"साधारण ब्याज पर कोई धनराशि 3 वर्ष में ₹6,500 और 5 वर्ष में ₹7,500 हो जाती है। धनराशि है:","optionsHi":["₹4,500","₹5,000","₹5,500","₹6,000"],"explanationHi":"दो वर्ष का ब्याज = 1,000 ⇒ प्रति वर्ष ₹500 ⇒ P = 6,500 − 1,500 = ₹5,000।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-8","question":"A sum at simple interest becomes 3 times itself in 20 years. In how many years will it become 5 times?","options":["30","35","40","50"],"answer":2,"explanation":"Interest of 2P in 20 years ⇒ P per 10 years; 4P needs 40 years.","difficulty":"very-hard","source":"SSC CGL · SBI Clerk","questionHi":"साधारण ब्याज पर कोई धनराशि 20 वर्ष में स्वयं की 3 गुनी हो जाती है। वह कितने वर्ष में 5 गुनी हो जाएगी?","optionsHi":["30","35","40","50"],"explanationHi":"20 वर्ष में 2P का ब्याज ⇒ प्रति 10 वर्ष में P; 4P के लिए 40 वर्ष चाहिए।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-9","question":"The simple interest on ₹7,200 at 7.5% per annum for 8 months is:","options":["₹400","₹450","₹540","₹360"],"answer":3,"explanation":"8 months = 2/3 year. SI = 7,200 × 7.5/100 × 2/3 = ₹360. ₹540 is the interest for a full year.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"₹7,200 पर 7.5% वार्षिक दर से 8 महीने का साधारण ब्याज है:","optionsHi":["₹400","₹450","₹540","₹360"],"explanationHi":"8 महीने = 2/3 वर्ष। SI = 7,200 × 7.5/100 × 2/3 = ₹360। ₹540 पूरे एक वर्ष का ब्याज है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-10","question":"What sum yields ₹600 as simple interest in 4 years at 5% per annum?","options":["₹3,000","₹2,500","₹2,400","₹3,600"],"answer":0,"explanation":"SI = P × 5 × 4/100 = 0.2P = 600, so P = ₹3,000. ₹3,600 adds the interest to the principal, and ₹2,400 multiplies 600 by 4 instead of dividing by 0.2.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"कौन-सी धनराशि 5% वार्षिक दर से 4 वर्ष में ₹600 साधारण ब्याज देती है?","optionsHi":["₹3,000","₹2,500","₹2,400","₹3,600"],"explanationHi":"SI = P × 5 × 4/100 = 0.2P = 600, अतः P = ₹3,000। ₹3,600 में ब्याज को मूलधन में जोड़ दिया गया है, और ₹2,400 में 0.2 से भाग देने की जगह 600 को 4 से गुणा किया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-11","question":"At what rate per annum will the simple interest on a sum for 5 years be 2/5 of the principal?","options":["8%","5%","12.5%","10%"],"answer":0,"explanation":"SI/P = RT/100, so 2/5 = 5R/100 and R = 40/5 = 8%. 12.5% inverts the fraction to 5/2 before multiplying by 5, and 10% divides 40 by 4 instead of 5 years.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"किस वार्षिक दर से किसी धनराशि पर 5 वर्ष का साधारण ब्याज मूलधन का 2/5 होगा?","optionsHi":["8%","5%","12.5%","10%"],"explanationHi":"SI/P = RT/100, अतः 2/5 = 5R/100 और R = 40/5 = 8%। 12.5% में 5 से गुणा करने से पहले भिन्न को उलटकर 5/2 कर दिया गया है, और 10% में 40 को 5 वर्ष की जगह 4 से भाग दिया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-12","question":"₹9,200 is divided into two parts such that the simple interest on the first at 4% for 2 years equals the simple interest on the second at 5% for 3 years. The smaller part is:","options":["₹3,200","₹4,600","₹4,000","₹6,000"],"answer":0,"explanation":"8% of x = 15% of y, so x : y = 15 : 8. Total 23 units = 9,200, one unit = 400; the parts are ₹6,000 and ₹3,200. Smaller part = ₹3,200.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"₹9,200 को दो भागों में इस प्रकार बाँटा गया कि पहले भाग पर 4% से 2 वर्ष का साधारण ब्याज, दूसरे भाग पर 5% से 3 वर्ष के साधारण ब्याज के बराबर है। छोटा भाग है:","optionsHi":["₹3,200","₹4,600","₹4,000","₹6,000"],"explanationHi":"x का 8% = y का 15%, अतः x : y = 15 : 8। कुल 23 इकाई = 9,200, एक इकाई = 400; भाग ₹6,000 और ₹3,200 हैं। छोटा भाग = ₹3,200।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-13","question":"The simple interest on a sum for 3 years at 5% per annum is ₹120 less than the simple interest on the same sum for 5 years at 4% per annum. The sum is:","options":["₹1,200","₹3,000","₹2,400","₹2,000"],"answer":2,"explanation":"Interest percentages are 15% and 20% of the sum; the difference 5% = ₹120, so the sum = ₹2,400.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर 5% वार्षिक दर से 3 वर्ष का साधारण ब्याज, उसी धनराशि पर 4% वार्षिक दर से 5 वर्ष के साधारण ब्याज से ₹120 कम है। धनराशि है:","optionsHi":["₹1,200","₹3,000","₹2,400","₹2,000"],"explanationHi":"ब्याज धनराशि का क्रमशः 15% और 20% है; अंतर 5% = ₹120, अतः धनराशि = ₹2,400।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-14","question":"A sum of ₹1,120 amounts to ₹1,344 in 4 years at simple interest. At the same rate it will amount to how much in 6 years?","options":["₹1,400","₹1,456","₹1,512","₹1,344"],"answer":1,"explanation":"SI for 4 years = 224, i.e. ₹56 a year. In 6 years SI = ₹336 and the amount = 1,120 + 336 = ₹1,456.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"साधारण ब्याज पर ₹1,120 की धनराशि 4 वर्ष में ₹1,344 हो जाती है। उसी दर से वह 6 वर्ष में कितनी हो जाएगी?","optionsHi":["₹1,400","₹1,456","₹1,512","₹1,344"],"explanationHi":"4 वर्ष का SI = 224, यानी प्रति वर्ष ₹56। 6 वर्ष में SI = ₹336 और मिश्रधन = 1,120 + 336 = ₹1,456।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-15","question":"A sum is lent at simple interest at 5% per annum for the first 2 years, 8% per annum for the next 3 years and 10% per annum beyond 5 years. If the interest for 8 years is ₹1,280, the sum is:","options":["₹2,500","₹2,000","₹1,800","₹1,600"],"answer":1,"explanation":"Total interest = (2 × 5 + 3 × 8 + 3 × 10)% = 64% of the sum = ₹1,280, so the sum = ₹2,000.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक धनराशि साधारण ब्याज पर पहले 2 वर्ष के लिए 5% वार्षिक, अगले 3 वर्ष के लिए 8% वार्षिक और 5 वर्ष के बाद 10% वार्षिक दर से उधार दी गई है। यदि 8 वर्ष का ब्याज ₹1,280 है, तो धनराशि है:","optionsHi":["₹2,500","₹2,000","₹1,800","₹1,600"],"explanationHi":"कुल ब्याज = (2 × 5 + 3 × 8 + 3 × 10)% = धनराशि का 64% = ₹1,280, अतः धनराशि = ₹2,000।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-16","question":"A lends ₹5,000 to B at 8% per annum simple interest, and B lends the same sum to C at 12.5% per annum. B's gain over 3 years is:","options":["₹1,125","₹600","₹675","₹750"],"answer":2,"explanation":"B's net rate = 12.5 − 8 = 4.5% a year, so gain = 5,000 × 4.5 × 3/100 = ₹675. ₹1,125 is the interest B earns from C before paying A.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A, B को ₹5,000 साधारण ब्याज की 8% वार्षिक दर से उधार देता है, और B वही राशि C को 12.5% वार्षिक दर से उधार दे देता है। 3 वर्ष में B का लाभ है:","optionsHi":["₹1,125","₹600","₹675","₹750"],"explanationHi":"B की शुद्ध दर = 12.5 − 8 = 4.5% प्रति वर्ष, अतः लाभ = 5,000 × 4.5 × 3/100 = ₹675। ₹1,125 वह ब्याज है जो B को C से मिलता है, A को चुकाने से पहले।","subtopic":"lending-borrowing"},
  {"id":"quant-simple-interest-17","question":"At simple interest a sum becomes 1.16 times itself in as many years as the rate percent per annum. The rate is:","options":["2%","4%","16%","8%"],"answer":1,"explanation":"SI = 16% of P with r = t: r × r/100 = 0.16, r² = 16, r = 4% for 4 years.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"साधारण ब्याज पर कोई धनराशि उतने ही वर्षों में स्वयं की 1.16 गुनी हो जाती है जितना वार्षिक दर प्रतिशत है। दर है:","optionsHi":["2%","4%","16%","8%"],"explanationHi":"SI = P का 16%, जहाँ r = t: r × r/100 = 0.16, r² = 16, r = 4% और समय 4 वर्ष।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-18","question":"What annual instalment will discharge a debt of ₹630 due in 3 years at 5% per annum simple interest?","options":["₹210","₹240","₹230","₹220"],"answer":2,"explanation":"The debt grows to 630 × 1.15 = ₹724.5 in 3 years. Instalment x paid at the end of years 1, 2, 3 earns SI for 2, 1, 0 years: x(1.10 + 1.05 + 1) = 3.15x = 724.5, so x = ₹230. ₹210 (630/3) ignores interest.","difficulty":"hard","source":"SSC CGL · CDS","questionHi":"5% वार्षिक साधारण ब्याज की दर से 3 वर्ष बाद देय ₹630 के ऋण को चुकाने के लिए कितनी वार्षिक किस्त चाहिए?","optionsHi":["₹210","₹240","₹230","₹220"],"explanationHi":"3 वर्ष में ऋण बढ़कर 630 × 1.15 = ₹724.5 हो जाता है। वर्ष 1, 2, 3 के अंत में दी गई किस्त x पर क्रमशः 2, 1, 0 वर्ष का SI लगता है: x(1.10 + 1.05 + 1) = 3.15x = 724.5, अतः x = ₹230। ₹210 (630/3) में ब्याज को नज़रअंदाज़ किया गया है।","subtopic":"instalments"},
  {"id":"quant-simple-interest-19","question":"A sum is lent at 6% per annum simple interest for 5 years, and the whole amount is then lent at 8% simple interest for 2 more years, finally amounting to ₹7,540. The original sum was:","options":["₹5,000","₹5,800","₹4,500","₹6,500"],"answer":0,"explanation":"After 5 years the amount is 1.30P; after 2 more years it is 1.30P × 1.16 = 1.508P = 7,540, so P = ₹5,000.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक धनराशि 6% वार्षिक साधारण ब्याज पर 5 वर्ष के लिए उधार दी जाती है, और फिर पूरा मिश्रधन 8% साधारण ब्याज पर 2 वर्ष और उधार दिया जाता है, जो अंत में ₹7,540 हो जाता है। मूल धनराशि थी:","optionsHi":["₹5,000","₹5,800","₹4,500","₹6,500"],"explanationHi":"5 वर्ष बाद मिश्रधन 1.30P है; 2 वर्ष और बाद यह 1.30P × 1.16 = 1.508P = 7,540 है, अतः P = ₹5,000।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-20","question":"A man invests 1/3 of his capital at 3%, 1/4 at 4% and the rest at 6% simple interest. If his annual income from interest is ₹270, his capital is:","options":["₹6,000","₹6,500","₹7,200","₹5,400"],"answer":0,"explanation":"The rest = 1 − 1/3 − 1/4 = 5/12. Overall rate = 3/3 + 4/4 + 6 × 5/12 = 1 + 1 + 2.5 = 4.5%. Capital = 270/0.045 = ₹6,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक व्यक्ति अपनी पूँजी का 1/3 भाग 3% पर, 1/4 भाग 4% पर और शेष 6% साधारण ब्याज पर लगाता है। यदि ब्याज से उसकी वार्षिक आय ₹270 है, तो उसकी पूँजी है:","optionsHi":["₹6,000","₹6,500","₹7,200","₹5,400"],"explanationHi":"शेष = 1 − 1/3 − 1/4 = 5/12। कुल दर = 3/3 + 4/4 + 6 × 5/12 = 1 + 1 + 2.5 = 4.5%। पूँजी = 270/0.045 = ₹6,000।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-21","question":"₹12,000 is lent partly at 5% and partly at 8% per annum simple interest. If the total interest after 2 years is ₹1,500, the part lent at 8% is:","options":["₹6,000","₹4,000","₹7,000","₹5,000"],"answer":3,"explanation":"Let x be at 8%: 0.16x + 0.10(12,000 − x) = 1,500, so 0.06x = 300 and x = ₹5,000. Check: 800 + 700 = 1,500.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"₹12,000 को आंशिक रूप से 5% और आंशिक रूप से 8% वार्षिक साधारण ब्याज पर उधार दिया गया है। यदि 2 वर्ष बाद कुल ब्याज ₹1,500 है, तो 8% पर उधार दिया गया भाग है:","optionsHi":["₹6,000","₹4,000","₹7,000","₹5,000"],"explanationHi":"माना x पर 8% है: 0.16x + 0.10(12,000 − x) = 1,500, अतः 0.06x = 300 और x = ₹5,000। जाँच: 800 + 700 = 1,500।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-22","question":"How many of the following statements about simple interest are correct?\n1. The interest earned in each year is the same.\n2. A sum doubles itself in 8 years at 12.5% per annum.\n3. If both the rate and the time are halved, the interest becomes half.\n4. The simple interest on ₹1,000 at 10% per annum for 6 months is ₹100.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"1 is true. 2 is true (12.5 × 8 = 100%). 3 is false: halving both makes the interest one-quarter. 4 is false: 6 months gives ₹50. Two statements are correct.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"साधारण ब्याज के बारे में निम्नलिखित में से कितने कथन सही हैं?\n1. प्रत्येक वर्ष में अर्जित ब्याज समान होता है।\n2. कोई धनराशि 12.5% वार्षिक दर से 8 वर्ष में दोगुनी हो जाती है।\n3. यदि दर और समय दोनों आधे कर दिए जाएँ, तो ब्याज आधा हो जाता है।\n4. ₹1,000 पर 10% वार्षिक दर से 6 महीने का साधारण ब्याज ₹100 है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"1 सही है। 2 सही है (12.5 × 8 = 100%)। 3 गलत है: दोनों को आधा करने पर ब्याज एक-चौथाई हो जाता है। 4 गलत है: 6 महीने का ब्याज ₹50 होता है। दो कथन सही हैं।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-23","question":"A sum amounts to ₹2,300 in 3 years at a certain rate of simple interest. Had the rate been 2 percentage points higher, it would have amounted to ₹2,420 in the same time. The sum is:","options":["₹2,200","₹2,100","₹1,800","₹2,000"],"answer":3,"explanation":"The extra interest = 2% × 3 years = 6% of the sum = 2,420 − 2,300 = ₹120, so the sum = ₹2,000 (and the original rate is 5%).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"किसी साधारण ब्याज दर से एक धनराशि 3 वर्ष में ₹2,300 हो जाती है। यदि दर 2 प्रतिशत अंक अधिक होती, तो वह उतने ही समय में ₹2,420 हो जाती। धनराशि है:","optionsHi":["₹2,200","₹2,100","₹1,800","₹2,000"],"explanationHi":"अतिरिक्त ब्याज = 2% × 3 वर्ष = धनराशि का 6% = 2,420 − 2,300 = ₹120, अतः धनराशि = ₹2,000 (और मूल दर 5% है)।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-24","question":"A debt of ₹848 due in 4 years at 4% per annum simple interest is to be discharged by 4 equal annual instalments. Each instalment is:","options":["₹240","₹250","₹212","₹232"],"answer":3,"explanation":"The debt becomes 848 × 1.16 = ₹983.68 after 4 years. Instalments earn interest for 3, 2, 1 and 0 years: x(1.12 + 1.08 + 1.04 + 1) = 4.24x = 983.68, so x = ₹232. ₹212 is just 848/4.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"4% वार्षिक साधारण ब्याज की दर से 4 वर्ष बाद देय ₹848 के ऋण को 4 समान वार्षिक किस्तों में चुकाना है। प्रत्येक किस्त है:","optionsHi":["₹240","₹250","₹212","₹232"],"explanationHi":"4 वर्ष बाद ऋण 848 × 1.16 = ₹983.68 हो जाता है। किस्तों पर क्रमशः 3, 2, 1 और 0 वर्ष का ब्याज लगता है: x(1.12 + 1.08 + 1.04 + 1) = 4.24x = 983.68, अतः x = ₹232। ₹212 केवल 848/4 है।","subtopic":"instalments"},
  {"id":"quant-simple-interest-25","question":"The simple interest on a sum is 1/9 of the principal and the number of years equals the rate percent per annum. The rate is:","options":["9%","3%","3⅓%","2⅓%"],"answer":2,"explanation":"r × r/100 = 1/9, so r² = 100/9 and r = 10/3 = 3⅓% per annum (for 3⅓ years).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर साधारण ब्याज मूलधन का 1/9 है और वर्षों की संख्या वार्षिक दर प्रतिशत के बराबर है। दर है:","optionsHi":["9%","3%","3⅓%","2⅓%"],"explanationHi":"r × r/100 = 1/9, अतः r² = 100/9 और r = 10/3 = 3⅓% वार्षिक (3⅓ वर्ष के लिए)।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-26","question":"A sum lent at 6% per annum simple interest for a certain number of years earns ₹1,440. Had it been lent at 8% per annum for 2 years longer, it would have earned ₹2,560. The sum is:","options":["₹4,800","₹5,000","₹3,600","₹4,000"],"answer":3,"explanation":"6Pt/100 = 1,440 and 8P(t + 2)/100 = 2,560. Dividing: 8(t + 2)/(6t) = 16/9, so 72(t + 2) = 96t, t = 6 years, and P = 1,440 × 100/36 = ₹4,000.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"6% वार्षिक साधारण ब्याज पर कुछ वर्षों के लिए उधार दी गई धनराशि ₹1,440 अर्जित करती है। यदि इसे 8% वार्षिक दर पर 2 वर्ष अधिक के लिए उधार दिया जाता, तो वह ₹2,560 अर्जित करती। धनराशि है:","optionsHi":["₹4,800","₹5,000","₹3,600","₹4,000"],"explanationHi":"6Pt/100 = 1,440 और 8P(t + 2)/100 = 2,560। भाग देने पर: 8(t + 2)/(6t) = 16/9, अतः 72(t + 2) = 96t, t = 6 वर्ष, और P = 1,440 × 100/36 = ₹4,000।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-27","question":"Two sums in the ratio 3 : 5 are lent at 8% and 6% per annum simple interest respectively. If the total interest after 4 years is ₹1,296, the larger sum is:","options":["₹4,800","₹3,000","₹2,400","₹1,800"],"answer":1,"explanation":"Let the sums be 3x and 5x. Interest = 3x × 0.32 + 5x × 0.24 = 0.96x + 1.20x = 2.16x = 1,296, so x = 600 and the larger sum = ₹3,000.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"3 : 5 के अनुपात वाली दो धनराशियाँ क्रमशः 8% और 6% वार्षिक साधारण ब्याज पर उधार दी गई हैं। यदि 4 वर्ष बाद कुल ब्याज ₹1,296 है, तो बड़ी धनराशि है:","optionsHi":["₹4,800","₹3,000","₹2,400","₹1,800"],"explanationHi":"धनराशियाँ 3x और 5x मानें। ब्याज = 3x × 0.32 + 5x × 0.24 = 0.96x + 1.20x = 2.16x = 1,296, अतः x = 600 और बड़ी धनराशि = ₹3,000।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-28","question":"The simple interest on ₹6,000 at 10% per annum from 4 February 2024 to 17 April 2024 (counting 1 year as 365 days and excluding the starting day) is:","options":["₹100","₹150","₹120","₹125"],"answer":2,"explanation":"Days: 25 in February (2024 is a leap year, 29 − 4), 31 in March and 17 in April = 73 days = 1/5 year. SI = 6,000 × 0.10 × 1/5 = ₹120.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"₹6,000 पर 10% वार्षिक दर से 4 फरवरी 2024 से 17 अप्रैल 2024 तक का साधारण ब्याज (1 वर्ष = 365 दिन मानें और आरंभ का दिन छोड़ दें) है:","optionsHi":["₹100","₹150","₹120","₹125"],"explanationHi":"दिन: फरवरी में 25 (2024 अधिवर्ष है, 29 − 4), मार्च में 31 और अप्रैल में 17 = 73 दिन = 1/5 वर्ष। SI = 6,000 × 0.10 × 1/5 = ₹120।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-29","question":"What is the simple interest on ₹2,500 at 6% per annum for 3 years?","options":["₹150","₹450","₹500","₹375"],"answer":1,"explanation":"SI = P × R × T / 100 = 2,500 × 6 × 3 / 100 = ₹450. ₹150 is only one year's interest.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"₹2,500 पर 6% वार्षिक दर से 3 वर्ष का साधारण ब्याज क्या है?","optionsHi":["₹150","₹450","₹500","₹375"],"explanationHi":"SI = P × R × T / 100 = 2,500 × 6 × 3 / 100 = ₹450। ₹150 केवल एक वर्ष का ब्याज है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-30","question":"In how many years will ₹4,000 amount to ₹5,200 at 7.5% per annum simple interest?","options":["4 years","3 years","5 years","6 years"],"answer":0,"explanation":"Interest needed = 1,200. One year's interest = 4,000 × 7.5% = 300. Time = 1,200 ÷ 300 = 4 years.","difficulty":"moderate","source":"SSC CGL","questionHi":"7.5% वार्षिक साधारण ब्याज की दर से ₹4,000 कितने वर्षों में ₹5,200 हो जाएँगे?","optionsHi":["4 वर्ष","3 वर्ष","5 वर्ष","6 वर्ष"],"explanationHi":"आवश्यक ब्याज = 1,200। एक वर्ष का ब्याज = 4,000 × 7.5% = 300। समय = 1,200 ÷ 300 = 4 वर्ष।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-31","question":"A sum becomes three times itself in 25 years at simple interest. What is the rate per annum?","options":["12%","4%","10%","8%"],"answer":3,"explanation":"Tripling means interest = 2P (200% of P) in 25 years, so rate = 200/25 = 8%. 12% wrongly takes 300%.","difficulty":"moderate","source":"SSC CGL","questionHi":"साधारण ब्याज पर कोई धनराशि 25 वर्ष में स्वयं की तीन गुनी हो जाती है। वार्षिक दर क्या है?","optionsHi":["12%","4%","10%","8%"],"explanationHi":"तीन गुना होने का अर्थ है 25 वर्ष में ब्याज = 2P (P का 200%), इसलिए दर = 200/25 = 8%। 12% में गलती से 300% ले लिया गया है।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-32","question":"₹15,000 is lent partly at 8% and the rest at 12% per annum simple interest. The total interest after 3 years is ₹4,560. How much was lent at 12%?","options":["₹7,000","₹7,500","₹8,000","₹9,000"],"answer":2,"explanation":"Yearly interest = 4,560 ÷ 3 = 1,520. 0.08x + 0.12(15,000 − x) = 1,520 → 1,800 − 0.04x = 1,520 → x = 7,000 at 8%, so ₹8,000 at 12%. ₹7,000 is the part at 8%.","difficulty":"hard","source":"SSC CGL Tier-2","questionHi":"₹15,000 का कुछ भाग 8% और शेष 12% वार्षिक साधारण ब्याज पर उधार दिया गया है। 3 वर्ष बाद कुल ब्याज ₹4,560 है। 12% पर कितना उधार दिया गया था?","optionsHi":["₹7,000","₹7,500","₹8,000","₹9,000"],"explanationHi":"वार्षिक ब्याज = 4,560 ÷ 3 = 1,520। 0.08x + 0.12(15,000 − x) = 1,520 → 1,800 − 0.04x = 1,520 → 8% पर x = 7,000, अतः 12% पर ₹8,000। ₹7,000 वह भाग है जो 8% पर है।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-33","question":"The simple interest on a sum for 4 years is ₹1,600. At a rate 2 percentage points higher, the interest on the same sum for 3 years is ₹1,500. What is the sum?","options":["₹4,000","₹5,000","₹6,000","₹2,500"],"answer":1,"explanation":"4PR/100 = 1,600 → PR = 40,000. 3P(R + 2)/100 = 1,500 → PR + 2P = 50,000 → 2P = 10,000 → P = ₹5,000 (and R = 8%).","difficulty":"hard","source":"SSC CGL Tier-2","questionHi":"किसी धनराशि पर 4 वर्ष का साधारण ब्याज ₹1,600 है। 2 प्रतिशत अंक अधिक दर पर उसी धनराशि पर 3 वर्ष का ब्याज ₹1,500 है। धनराशि क्या है?","optionsHi":["₹4,000","₹5,000","₹6,000","₹2,500"],"explanationHi":"4PR/100 = 1,600 → PR = 40,000। 3P(R + 2)/100 = 1,500 → PR + 2P = 50,000 → 2P = 10,000 → P = ₹5,000 (और R = 8%)।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-34","question":"The simple interest on a sum for 3 years equals 3/8 of the amount at the end of those 3 years. What is the rate of interest per annum?","options":["20%","12.5%","15%","25%"],"answer":0,"explanation":"SI = (3/8)(P + SI) → (5/8)SI = (3/8)P → SI = 0.6P in 3 years. Rate = 60/3 = 20%. 12.5% treats 3/8 as a fraction of the principal.","difficulty":"hard","source":"SSC CGL Tier-2","questionHi":"किसी धनराशि पर 3 वर्ष का साधारण ब्याज, उन 3 वर्षों के अंत में मिश्रधन का 3/8 है। वार्षिक ब्याज दर क्या है?","optionsHi":["20%","12.5%","15%","25%"],"explanationHi":"SI = (3/8)(P + SI) → (5/8)SI = (3/8)P → 3 वर्ष में SI = 0.6P। दर = 60/3 = 20%। 12.5% में 3/8 को मूलधन का भिन्न मान लिया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-35","question":"A borrows ₹8,000 from B at 10% per annum simple interest. He lends half of it to C at 12% and the other half to D at 15% per annum simple interest. What is A's net gain after 2 years?","options":["₹2,160","₹280","₹720","₹560"],"answer":3,"explanation":"A pays 8,000 × 10% × 2 = 1,600. He earns 4,000 × 12% × 2 = 960 and 4,000 × 15% × 2 = 1,200, total 2,160. Net gain = 2,160 − 1,600 = ₹560. ₹2,160 forgets the interest A pays.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"A, B से ₹8,000 साधारण ब्याज की 10% वार्षिक दर पर उधार लेता है। वह उसका आधा C को 12% पर और बाकी आधा D को 15% वार्षिक साधारण ब्याज पर उधार दे देता है। 2 वर्ष बाद A का शुद्ध लाभ क्या है?","optionsHi":["₹2,160","₹280","₹720","₹560"],"explanationHi":"A चुकाता है 8,000 × 10% × 2 = 1,600। वह कमाता है 4,000 × 12% × 2 = 960 और 4,000 × 15% × 2 = 1,200, कुल 2,160। शुद्ध लाभ = 2,160 − 1,600 = ₹560। ₹2,160 में A द्वारा चुकाया गया ब्याज भूल गए हैं।","subtopic":"lending-borrowing"},
  {"id":"quant-simple-interest-36","question":"₹14,000 is divided into two parts. One is lent at 10% for 3 years and the other at 8% for 5 years, both at simple interest, and the two interests are equal. What is the total interest received?","options":["₹2,400","₹4,200","₹4,800","₹5,600"],"answer":2,"explanation":"x × 10 × 3 = y × 8 × 5 → 30x = 40y → x : y = 4 : 3, so x = 8,000 and y = 6,000. Each interest = 8,000 × 30% = 2,400; total ₹4,800. ₹2,400 is just one of them.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"₹14,000 को दो भागों में बाँटा गया। एक भाग 10% पर 3 वर्ष के लिए और दूसरा 8% पर 5 वर्ष के लिए, दोनों साधारण ब्याज पर, उधार दिए गए और दोनों ब्याज बराबर हैं। प्राप्त कुल ब्याज क्या है?","optionsHi":["₹2,400","₹4,200","₹4,800","₹5,600"],"explanationHi":"x × 10 × 3 = y × 8 × 5 → 30x = 40y → x : y = 4 : 3, अतः x = 8,000 और y = 6,000। प्रत्येक ब्याज = 8,000 × 30% = 2,400; कुल ₹4,800। ₹2,400 उनमें से केवल एक का ब्याज है।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-37","question":"A sum doubles itself in 12 years at simple interest. In how many years will it become 2.5 times itself at a rate 25% higher than the original rate?","options":["18 years","14.4 years","15 years","12 years"],"answer":1,"explanation":"Doubling in 12 years → rate = 100/12 = 8⅓%. The new rate = 1.25 × 8⅓ = 10.4167% (= 125/12 %). To gain 150% of P: time = 150 ÷ (125/12) = 14.4 years. 18 years keeps the old rate.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"साधारण ब्याज पर कोई धनराशि 12 वर्ष में स्वयं की दोगुनी हो जाती है। मूल दर से 25% अधिक दर पर वह कितने वर्ष में स्वयं की 2.5 गुनी हो जाएगी?","optionsHi":["18 वर्ष","14.4 वर्ष","15 वर्ष","12 वर्ष"],"explanationHi":"12 वर्ष में दोगुना → दर = 100/12 = 8⅓%। नई दर = 1.25 × 8⅓ = 10.4167% (= 125/12 %)। P का 150% ब्याज पाने के लिए: समय = 150 ÷ (125/12) = 14.4 वर्ष। 18 वर्ष में पुरानी दर ही रखी गई है।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-38","question":"How many of the following statements about simple interest are correct? 1. At 8% per annum a sum doubles in 12 years. 2. SI on ₹x for 2 years at r% equals SI on ₹x for r years at 2%. 3. If both principal and rate are doubled, the SI for the same time becomes 4 times. 4. The amount grows by the same sum every year.","options":["Only three","Only two","All four","Only one"],"answer":0,"explanation":"1: doubling at 8% needs 100/8 = 12.5 years ✗. 2: x·2·r/100 = x·r·2/100 ✓. 3: SI ∝ P × R, so 2 × 2 = 4 times ✓. 4: SI is constant each year ✓. Three are correct.","difficulty":"very-hard","source":"SSC CGL","questionHi":"साधारण ब्याज के बारे में निम्नलिखित में से कितने कथन सही हैं? 1. 8% वार्षिक दर पर कोई धनराशि 12 वर्ष में दोगुनी हो जाती है। 2. ₹x पर r% से 2 वर्ष का SI, ₹x पर 2% से r वर्ष के SI के बराबर होता है। 3. यदि मूलधन और दर दोनों को दोगुना कर दिया जाए, तो उसी समय का SI 4 गुना हो जाता है। 4. मिश्रधन हर वर्ष समान राशि से बढ़ता है।","optionsHi":["केवल तीन","केवल दो","चारों","केवल एक"],"explanationHi":"1: 8% पर दोगुना होने में 100/8 = 12.5 वर्ष लगते हैं ✗। 2: x·2·r/100 = x·r·2/100 ✓। 3: SI ∝ P × R, इसलिए 2 × 2 = 4 गुना ✓। 4: SI हर वर्ष स्थिर रहता है ✓। तीन कथन सही हैं।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-39","question":"What is the simple interest on ₹4,800 at 6.25% per annum for 2 years?","options":["₹625","₹600","₹560","₹480"],"answer":1,"explanation":"SI = 4,800 × 6.25 × 2/100 = ₹600; note 6.25% = 1/16, so one year's interest is 4,800/16 = ₹300. ₹625 mistakes 6.25% for a flat ₹625, and ₹480 uses 5%.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"₹4,800 पर 6.25% वार्षिक दर से 2 वर्ष का साधारण ब्याज क्या है?","optionsHi":["₹625","₹600","₹560","₹480"],"explanationHi":"SI = 4,800 × 6.25 × 2/100 = ₹600; ध्यान दें 6.25% = 1/16, इसलिए एक वर्ष का ब्याज 4,800/16 = ₹300 है। ₹625 में 6.25% को ₹625 की एक निश्चित राशि समझ लिया गया है, और ₹480 में 5% लिया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-40","question":"At what rate of simple interest per annum does ₹2,000 earn ₹480 in 3 years?","options":["7.5%","8%","6%","9%"],"answer":1,"explanation":"R = SI × 100/(P × T) = 480 × 100/(2,000 × 3) = 8%. 6% divides by 4 years instead of 3, and 7.5% or 9% come from slips in the division.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"साधारण ब्याज की किस वार्षिक दर से ₹2,000, 3 वर्ष में ₹480 अर्जित करते हैं?","optionsHi":["7.5%","8%","6%","9%"],"explanationHi":"R = SI × 100/(P × T) = 480 × 100/(2,000 × 3) = 8%। 6% में 3 वर्ष की जगह 4 वर्ष से भाग दिया गया है, और 7.5% या 9% भाग देने की चूक से आते हैं।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-41","question":"What is the simple interest on ₹10,000 at 1% per month for 1 year?","options":["₹120","₹1,000","₹1,200","₹100"],"answer":2,"explanation":"1% per month is 12% per annum, so SI = 10,000 × 12/100 = ₹1,200. ₹100 is the interest for one month only.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"₹10,000 पर 1% प्रति माह की दर से 1 वर्ष का साधारण ब्याज क्या है?","optionsHi":["₹120","₹1,000","₹1,200","₹100"],"explanationHi":"1% प्रति माह का अर्थ 12% वार्षिक है, अतः SI = 10,000 × 12/100 = ₹1,200। ₹100 केवल एक माह का ब्याज है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-42","question":"In how many years will the simple interest on a sum be 3/5 of the sum at 12% per annum?","options":["4 years","5 years","6 years","7.2 years"],"answer":1,"explanation":"SI/P = RT/100, so 3/5 = 12T/100 and T = 60/12 = 5 years. 7.2 years multiplies 3/5 by 12 instead of dividing, and 4 or 6 come from rounding the fraction wrongly.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"12% वार्षिक दर पर कितने वर्षों में किसी धनराशि का साधारण ब्याज उस धनराशि का 3/5 होगा?","optionsHi":["4 वर्ष","5 वर्ष","6 वर्ष","7.2 वर्ष"],"explanationHi":"SI/P = RT/100, अतः 3/5 = 12T/100 और T = 60/12 = 5 वर्ष। 7.2 वर्ष में 3/5 को 12 से भाग देने की जगह गुणा किया गया है, और 4 या 6 भिन्न को गलत पूर्णांकित करने से आते हैं।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-43","question":"What is the ratio of the simple interest on a sum at 4% per annum for 6 years to that on the same sum at 6% per annum for 5 years?","options":["5 : 4","2 : 3","3 : 4","4 : 5"],"answer":3,"explanation":"SI ∝ R × T: 4 × 6 = 24 and 6 × 5 = 30, so the ratio is 24 : 30 = 4 : 5.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर 4% वार्षिक दर से 6 वर्ष के साधारण ब्याज और उसी धनराशि पर 6% वार्षिक दर से 5 वर्ष के साधारण ब्याज का अनुपात क्या है?","optionsHi":["5 : 4","2 : 3","3 : 4","4 : 5"],"explanationHi":"SI ∝ R × T: 4 × 6 = 24 और 6 × 5 = 30, इसलिए अनुपात 24 : 30 = 4 : 5।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-44","question":"The simple interest on a sum for 5 years at 8% per annum is ₹2,400 less than the sum itself. What is the sum?","options":["₹6,000","₹3,000","₹4,000","₹5,000"],"answer":2,"explanation":"SI = 40% of P, so P − 0.4P = 0.6P = 2,400 and P = ₹4,000. ₹6,000 sets the SI itself equal to ₹2,400.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर 8% वार्षिक दर से 5 वर्ष का साधारण ब्याज, उस धनराशि से ₹2,400 कम है। धनराशि क्या है?","optionsHi":["₹6,000","₹3,000","₹4,000","₹5,000"],"explanationHi":"SI = P का 40%, इसलिए P − 0.4P = 0.6P = 2,400 और P = ₹4,000। ₹6,000 में SI को ही ₹2,400 के बराबर मान लिया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-45","question":"What is the simple interest on ₹7,200 at 6 2/3% per annum for 9 months?","options":["₹480","₹360","₹324","₹400"],"answer":1,"explanation":"SI = 7,200 × (20/3)/100 × 9/12 = 7,200 × 1/15 × 3/4 = ₹360. ₹480 uses a full year.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"₹7,200 पर 6 2/3% वार्षिक दर से 9 महीने का साधारण ब्याज क्या है?","optionsHi":["₹480","₹360","₹324","₹400"],"explanationHi":"SI = 7,200 × (20/3)/100 × 9/12 = 7,200 × 1/15 × 3/4 = ₹360। ₹480 में पूरा एक वर्ष लिया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-46","question":"The simple interest on ₹1,600 at r% per annum for 4 years equals the simple interest on ₹2,400 at (r − 2)% per annum for 3 years. What is r?","options":["12","16","18","20"],"answer":2,"explanation":"1,600 × r × 4 = 2,400 × (r − 2) × 3 gives 6,400r = 7,200r − 14,400, so r = 18. Check: both interests are ₹1,152.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"₹1,600 पर r% वार्षिक दर से 4 वर्ष का साधारण ब्याज, ₹2,400 पर (r − 2)% वार्षिक दर से 3 वर्ष के साधारण ब्याज के बराबर है। r क्या है?","optionsHi":["12","16","18","20"],"explanationHi":"1,600 × r × 4 = 2,400 × (r − 2) × 3 से 6,400r = 7,200r − 14,400, अतः r = 18। जाँच: दोनों ब्याज ₹1,152 हैं।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-47","question":"A sum doubles itself in 6 years at simple interest. At the same rate, what will ₹2,500 amount to in 9 years?","options":["₹7,500","₹3,750","₹5,000","₹6,250"],"answer":3,"explanation":"Doubling in 6 years means 100% interest in 6 years, so 9 years give 150%: SI = ₹3,750 and amount = ₹6,250. ₹3,750 is only the interest.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"साधारण ब्याज पर कोई धनराशि 6 वर्ष में स्वयं की दोगुनी हो जाती है। उसी दर से ₹2,500 का 9 वर्ष में मिश्रधन क्या होगा?","optionsHi":["₹7,500","₹3,750","₹5,000","₹6,250"],"explanationHi":"6 वर्ष में दोगुना होने का अर्थ है 6 वर्ष में 100% ब्याज, अतः 9 वर्ष में 150%: SI = ₹3,750 और मिश्रधन = ₹6,250। ₹3,750 केवल ब्याज है।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-48","question":"A person deposits ₹500 at the beginning of every month for 12 months in a recurring deposit paying 6% per annum simple interest. How much interest does he earn at the end of the year?","options":["₹180","₹195","₹165","₹360"],"answer":1,"explanation":"The deposits earn interest for 12, 11, …, 1 months: 78 month-units in all. Interest = 500 × 78 × 6/(100 × 12) = ₹195. ₹360 wrongly gives all ₹6,000 a full year; ₹165 assumes end-of-month deposits.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक व्यक्ति 6% वार्षिक साधारण ब्याज देने वाली आवर्ती जमा (recurring deposit) में 12 महीने तक हर महीने की शुरुआत में ₹500 जमा करता है। वर्ष के अंत में उसे कितना ब्याज मिलेगा?","optionsHi":["₹180","₹195","₹165","₹360"],"explanationHi":"जमाओं पर क्रमशः 12, 11, …, 1 महीने का ब्याज मिलता है: कुल 78 माह-इकाइयाँ। ब्याज = 500 × 78 × 6/(100 × 12) = ₹195। ₹360 में गलती से पूरे ₹6,000 पर पूरे वर्ष का ब्याज लिया गया है; ₹165 में माना गया है कि जमा महीने के अंत में होती है।","subtopic":"instalments"},
  {"id":"quant-simple-interest-49","question":"A bank lends ₹50,000 at 10% per annum simple interest for 2 years but deducts a 4% processing fee from the loan when it is paid out. What is the effective annual rate of interest for the borrower?","options":["12%","10.4%","12.5%","14%"],"answer":2,"explanation":"The borrower receives ₹48,000 but pays interest of ₹10,000 plus the ₹2,000 fee, a cost of ₹12,000 over 2 years. Effective rate = 12,000 × 100/(48,000 × 2) = 12.5%. 12% divides by ₹50,000.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक बैंक ₹50,000 का ऋण 10% वार्षिक साधारण ब्याज पर 2 वर्ष के लिए देता है, लेकिन ऋण देते समय उसमें से 4% प्रोसेसिंग शुल्क काट लेता है। उधार लेने वाले के लिए प्रभावी वार्षिक ब्याज दर क्या है?","optionsHi":["12%","10.4%","12.5%","14%"],"explanationHi":"उधार लेने वाले को ₹48,000 मिलते हैं लेकिन वह ₹10,000 ब्याज और ₹2,000 शुल्क देता है, यानी 2 वर्ष में ₹12,000 की लागत। प्रभावी दर = 12,000 × 100/(48,000 × 2) = 12.5%। 12% में ₹50,000 से भाग दिया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-50","question":"A sum amounts to ₹2,240 in 2 years at 6% per annum simple interest. In how many years will it amount to ₹2,600 at the same rate?","options":["5 years","6 years","4.5 years","5.5 years"],"answer":0,"explanation":"P × 1.12 = 2,240 gives P = ₹2,000 and yearly interest ₹120. To earn ₹600 takes 600/120 = 5 years.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"6% वार्षिक साधारण ब्याज पर कोई धनराशि 2 वर्ष में ₹2,240 हो जाती है। उसी दर से वह कितने वर्षों में ₹2,600 हो जाएगी?","optionsHi":["5 वर्ष","6 वर्ष","4.5 वर्ष","5.5 वर्ष"],"explanationHi":"P × 1.12 = 2,240 से P = ₹2,000 और वार्षिक ब्याज ₹120। ₹600 कमाने में 600/120 = 5 वर्ष लगेंगे।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-51","question":"At simple interest a sum becomes 7/5 of itself in 5 years. In how many years will it double at the same rate?","options":["12.5 years","12 years","15 years","10 years"],"answer":0,"explanation":"Interest of 2/5 in 5 years means R = 40/5 = 8% per annum; doubling needs 100% interest, i.e. 100/8 = 12.5 years.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"साधारण ब्याज पर कोई धनराशि 5 वर्ष में स्वयं की 7/5 हो जाती है। उसी दर से वह कितने वर्ष में दोगुनी हो जाएगी?","optionsHi":["12.5 वर्ष","12 वर्ष","15 वर्ष","10 वर्ष"],"explanationHi":"5 वर्ष में 2/5 का ब्याज होने का अर्थ है R = 40/5 = 8% वार्षिक; दोगुना होने के लिए 100% ब्याज चाहिए, यानी 100/8 = 12.5 वर्ष।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-52","question":"At simple interest, the amounts of a sum after 3 years and after 5 years are in the ratio 13 : 15. What is the rate of interest per annum?","options":["8%","12.5%","12%","10%"],"answer":3,"explanation":"(100 + 3R)/(100 + 5R) = 13/15 gives 1,500 + 45R = 1,300 + 65R, so R = 10%. Check: 130 : 150 = 13 : 15.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"साधारण ब्याज पर किसी धनराशि का 3 वर्ष और 5 वर्ष बाद का मिश्रधन 13 : 15 के अनुपात में है। वार्षिक ब्याज दर क्या है?","optionsHi":["8%","12.5%","12%","10%"],"explanationHi":"(100 + 3R)/(100 + 5R) = 13/15 से 1,500 + 45R = 1,300 + 65R, अतः R = 10%। जाँच: 130 : 150 = 13 : 15।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-53","question":"₹x lent at 8% per annum simple interest for 5 years amounts to the same as ₹y lent at 10% per annum for 3 years. What is x : y?","options":["3 : 4","4 : 3","14 : 13","13 : 14"],"answer":3,"explanation":"1.4x = 1.3y, so x : y = 1.3 : 1.4 = 13 : 14. Equating only the interests (0.4x = 0.3y) gives 3 : 4.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"8% वार्षिक साधारण ब्याज पर 5 वर्ष के लिए उधार दिए गए ₹x का मिश्रधन, 10% वार्षिक दर पर 3 वर्ष के लिए उधार दिए गए ₹y के मिश्रधन के बराबर है। x : y क्या है?","optionsHi":["3 : 4","4 : 3","14 : 13","13 : 14"],"explanationHi":"1.4x = 1.3y, अतः x : y = 1.3 : 1.4 = 13 : 14। केवल ब्याजों को बराबर करने (0.4x = 0.3y) पर 3 : 4 आता है।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-54","question":"₹3,900 is divided into two parts so that the amount of the first part after 2 years equals the amount of the second part after 4 years, both at 10% per annum simple interest. What is the second part?","options":["₹1,700","₹1,800","₹1,950","₹2,100"],"answer":1,"explanation":"1.2A = 1.4B, so A : B = 7 : 6 and B = 6/13 × 3,900 = ₹1,800. Check: 2,100 × 1.2 = 1,800 × 1.4 = ₹2,520.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"₹3,900 को दो भागों में इस प्रकार बाँटा गया कि पहले भाग का 2 वर्ष बाद का मिश्रधन, दूसरे भाग के 4 वर्ष बाद के मिश्रधन के बराबर है, दोनों 10% वार्षिक साधारण ब्याज पर। दूसरा भाग क्या है?","optionsHi":["₹1,700","₹1,800","₹1,950","₹2,100"],"explanationHi":"1.2A = 1.4B, अतः A : B = 7 : 6 और B = 6/13 × 3,900 = ₹1,800। जाँच: 2,100 × 1.2 = 1,800 × 1.4 = ₹2,520।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-55","question":"A car loan of ₹1,44,000 is given at a flat 10% per annum simple interest for 2 years, repaid in 24 equal monthly instalments. What is each instalment?","options":["₹6,000","₹7,200","₹6,600","₹7,440"],"answer":1,"explanation":"Interest = 1,44,000 × 10% × 2 = ₹28,800, so the total repayable is ₹1,72,800 and each instalment is 1,72,800 ÷ 24 = ₹7,200. ₹6,000 repays only the principal.","difficulty":"hard","source":"RRB NTPC · SSC CGL","questionHi":"₹1,44,000 का कार ऋण 2 वर्ष के लिए 10% वार्षिक फ्लैट साधारण ब्याज पर दिया गया है, जिसे 24 समान मासिक किस्तों में चुकाना है। प्रत्येक किस्त क्या है?","optionsHi":["₹6,000","₹7,200","₹6,600","₹7,440"],"explanationHi":"ब्याज = 1,44,000 × 10% × 2 = ₹28,800, अतः कुल चुकाने योग्य राशि ₹1,72,800 है और प्रत्येक किस्त 1,72,800 ÷ 24 = ₹7,200। ₹6,000 में केवल मूलधन चुकाया गया है।","subtopic":"instalments"},
  {"id":"quant-simple-interest-56","question":"A bank pays 8% per annum simple interest on a 3-year deposit but deducts 10% tax at source on the interest. What does a depositor of ₹50,000 receive at maturity?","options":["₹60,800","₹62,000","₹61,000","₹60,000"],"answer":0,"explanation":"Interest = 50,000 × 0.08 × 3 = ₹12,000; tax = ₹1,200, so he receives 50,000 + 10,800 = ₹60,800. ₹62,000 ignores the tax.","difficulty":"hard","source":"RRB NTPC · SSC CGL","questionHi":"एक बैंक 3 वर्ष की जमा पर 8% वार्षिक साधारण ब्याज देता है लेकिन ब्याज पर 10% कर स्रोत पर काट लेता है। ₹50,000 जमा करने वाले को परिपक्वता पर कितना मिलेगा?","optionsHi":["₹60,800","₹62,000","₹61,000","₹60,000"],"explanationHi":"ब्याज = 50,000 × 0.08 × 3 = ₹12,000; कर = ₹1,200, अतः उसे 50,000 + 10,800 = ₹60,800 मिलेंगे। ₹62,000 में कर को नज़रअंदाज़ किया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-57","question":"How many of the following statements about simple interest are correct?\n1. If the rate is halved and the time doubled, the interest is unchanged.\n2. At r% per annum a sum doubles in 100/r years.\n3. The SI on ₹P for 2 years at 5% equals the SI on ₹2P for 1 year at 5%.\n4. If a sum triples in 10 years, it becomes 9 times itself in 40 years.","options":["Only one","All four","Only three","Only two"],"answer":1,"explanation":"All four are true. SI ∝ P × R × T covers 1 and 3, and 2 follows from 100% interest at r%. 4: tripling in 10 years means 200% in 10 years (20% a year), so 9 times (800% interest) takes 40 years.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"साधारण ब्याज के बारे में निम्नलिखित में से कितने कथन सही हैं?\n1. यदि दर आधी और समय दोगुना कर दिया जाए, तो ब्याज अपरिवर्तित रहता है।\n2. r% वार्षिक दर पर कोई धनराशि 100/r वर्ष में दोगुनी हो जाती है।\n3. ₹P पर 5% से 2 वर्ष का SI, ₹2P पर 5% से 1 वर्ष के SI के बराबर होता है।\n4. यदि कोई धनराशि 10 वर्ष में तीन गुनी हो जाती है, तो वह 40 वर्ष में 9 गुनी हो जाती है।","optionsHi":["केवल एक","चारों","केवल तीन","केवल दो"],"explanationHi":"चारों कथन सही हैं। SI ∝ P × R × T से 1 और 3 सिद्ध होते हैं, और 2 r% पर 100% ब्याज से निकलता है। 4: 10 वर्ष में तीन गुना होने का अर्थ है 10 वर्ष में 200% (प्रति वर्ष 20%), इसलिए 9 गुना होने (800% ब्याज) में 40 वर्ष लगते हैं।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-58","question":"A man invests ₹40,000, partly in a bank at 8% and the rest in bonds at 12%, both at simple interest. After 3 years his total amount is ₹52,600. He then reinvests only the bond money (with its interest) at 10% simple interest for 2 more years. What does that reinvestment amount to?","options":["₹40,800","₹41,600","₹30,000","₹39,600"],"answer":0,"explanation":"0.24a + 0.36(40,000 − a) = 12,600 gives 0.12a = 1,800, so a = ₹15,000 and bonds = ₹25,000. Bonds amount to 25,000 × 1.36 = ₹34,000 after 3 years, and 34,000 × 1.2 = ₹40,800 after 2 more.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक व्यक्ति ₹40,000 निवेश करता है, कुछ भाग बैंक में 8% पर और शेष बॉन्ड में 12% पर, दोनों साधारण ब्याज पर। 3 वर्ष बाद उसका कुल मिश्रधन ₹52,600 है। फिर वह केवल बॉन्ड वाली राशि (ब्याज सहित) को 10% साधारण ब्याज पर 2 वर्ष और निवेश करता है। यह पुनर्निवेश कितना हो जाता है?","optionsHi":["₹40,800","₹41,600","₹30,000","₹39,600"],"explanationHi":"0.24a + 0.36(40,000 − a) = 12,600 से 0.12a = 1,800, अतः a = ₹15,000 और बॉन्ड = ₹25,000। 3 वर्ष बाद बॉन्ड का मिश्रधन 25,000 × 1.36 = ₹34,000 है, और 2 वर्ष और बाद 34,000 × 1.2 = ₹40,800।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-59","question":"The simple interest on a sum for 5 years is ₹1,500 more than that for 3 years, and the amount after 8 years is ₹16,000. What is the rate of interest per annum?","options":["7%","6%","7.5%","8%"],"answer":2,"explanation":"Two years' interest = ₹1,500, so one year's = ₹750. P = 16,000 − 8 × 750 = ₹10,000 and R = 750/10,000 × 100 = 7.5%.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"किसी धनराशि पर 5 वर्ष का साधारण ब्याज, 3 वर्ष के ब्याज से ₹1,500 अधिक है, और 8 वर्ष बाद मिश्रधन ₹16,000 है। वार्षिक ब्याज दर क्या है?","optionsHi":["7%","6%","7.5%","8%"],"explanationHi":"दो वर्ष का ब्याज = ₹1,500, अतः एक वर्ष का = ₹750। P = 16,000 − 8 × 750 = ₹10,000 और R = 750/10,000 × 100 = 7.5%।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-60","question":"A loan of ₹1,260 is to be repaid in 3 equal annual instalments at 5% per annum simple interest, the first due one year from now. What is each instalment?","options":["₹420","₹483","₹441","₹460"],"answer":3,"explanation":"Value everything at the end of year 3: 1,260 × 1.15 = ₹1,449 must equal x(1.10) + x(1.05) + x = 3.15x, so x = ₹460. ₹483 just divides ₹1,449 by 3, ignoring that early instalments also earn interest.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"₹1,260 के ऋण को 5% वार्षिक साधारण ब्याज पर 3 समान वार्षिक किस्तों में चुकाना है, पहली किस्त अब से एक वर्ष बाद देय है। प्रत्येक किस्त क्या है?","optionsHi":["₹420","₹483","₹441","₹460"],"explanationHi":"सबको तीसरे वर्ष के अंत पर आँकें: 1,260 × 1.15 = ₹1,449, जो x(1.10) + x(1.05) + x = 3.15x के बराबर होना चाहिए, अतः x = ₹460। ₹483 केवल ₹1,449 को 3 से भाग देता है, यह भूलकर कि पहले दी गई किस्तों पर भी ब्याज लगता है।","subtopic":"instalments"},
  {"id":"quant-simple-interest-61","question":"₹2,600 is divided into three parts A, B and C such that, at the same rate of simple interest, the interest on A for 2 years, on B for 3 years and on C for 4 years are all equal. What is C?","options":["₹1,200","₹400","₹800","₹600"],"answer":3,"explanation":"2A = 3B = 4C gives A : B : C = 1/2 : 1/3 : 1/4 = 6 : 4 : 3, so C = 3/13 × 2,600 = ₹600. ₹1,200 is A.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"₹2,600 को तीन भागों A, B और C में इस प्रकार बाँटा गया कि समान साधारण ब्याज दर पर A का 2 वर्ष का, B का 3 वर्ष का और C का 4 वर्ष का ब्याज बराबर है। C क्या है?","optionsHi":["₹1,200","₹400","₹800","₹600"],"explanationHi":"2A = 3B = 4C से A : B : C = 1/2 : 1/3 : 1/4 = 6 : 4 : 3, अतः C = 3/13 × 2,600 = ₹600। ₹1,200 A है।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-62","question":"A man lends ₹10,000, part at 5% and the rest at 7% per annum simple interest. Had he interchanged the two rates, he would have earned ₹80 more every year. How much did he lend at 5%?","options":["₹6,000","₹4,000","₹7,000","₹3,000"],"answer":2,"explanation":"Interchanging changes the yearly interest by 0.02(a − b) = 80, where a is the part at 5%, so a − b = 4,000 and a + b = 10,000, giving a = ₹7,000. Gaining by the swap means the larger part was at the lower rate.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक व्यक्ति ₹10,000 का एक भाग 5% पर और शेष 7% वार्षिक साधारण ब्याज पर उधार देता है। यदि वह दोनों दरें आपस में बदल देता, तो उसे हर वर्ष ₹80 अधिक मिलते। उसने 5% पर कितना उधार दिया?","optionsHi":["₹6,000","₹4,000","₹7,000","₹3,000"],"explanationHi":"दरें बदलने से वार्षिक ब्याज में 0.02(a − b) = 80 का अंतर आता है, जहाँ a 5% वाला भाग है, इसलिए a − b = 4,000 और a + b = 10,000, जिससे a = ₹7,000। अदला-बदली से लाभ होने का अर्थ है कि बड़ा भाग कम दर पर था।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-63","question":"Ram lends ₹6,000 at 5% per annum and Shyam lends ₹4,500 at 10% per annum, both at simple interest, on the same day. After how many years will their amounts be equal?","options":["15 years","12 years","8 years","10 years"],"answer":3,"explanation":"Ram's amount grows by ₹300 a year and Shyam's by ₹450. 6,000 + 300t = 4,500 + 450t gives 150t = 1,500, so t = 10 years.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"राम ₹6,000 को 5% वार्षिक दर पर और श्याम ₹4,500 को 10% वार्षिक दर पर, दोनों साधारण ब्याज पर, एक ही दिन उधार देते हैं। कितने वर्ष बाद उनके मिश्रधन बराबर होंगे?","optionsHi":["15 वर्ष","12 वर्ष","8 वर्ष","10 वर्ष"],"explanationHi":"राम का मिश्रधन प्रति वर्ष ₹300 और श्याम का ₹450 बढ़ता है। 6,000 + 300t = 4,500 + 450t से 150t = 1,500, अतः t = 10 वर्ष।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-64","question":"Assertion (A): On ₹1,000 at 10% per annum simple interest, the interest earned in the 5th year alone is ₹100.\nReason (R): Under simple interest, interest is always calculated on the original principal.","options":["A is false but R is true","Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false"],"answer":1,"explanation":"Since interest is always on the original ₹1,000 (R), each year's interest, including the 5th, is ₹100 (A). Under compound interest the 5th-year interest would be higher.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"अभिकथन (A): 10% वार्षिक साधारण ब्याज पर ₹1,000 पर केवल 5वें वर्ष में अर्जित ब्याज ₹100 है।\nकारण (R): साधारण ब्याज में ब्याज की गणना हमेशा मूल मूलधन पर की जाती है।","optionsHi":["A गलत है लेकिन R सही है","A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है लेकिन R गलत है"],"explanationHi":"चूँकि ब्याज हमेशा मूल ₹1,000 पर लगता है (R), इसलिए प्रत्येक वर्ष का ब्याज, 5वें वर्ष सहित, ₹100 है (A)। चक्रवृद्धि ब्याज में 5वें वर्ष का ब्याज अधिक होता।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-65","question":"The simple interest on a sum for 6 years is ₹2,000 less than the sum, and the simple interest for 12 years is ₹1,000 more than the sum. What is the sum?","options":["₹5,000","₹5,500","₹6,000","₹4,500"],"answer":0,"explanation":"SI(12) − SI(6) = 6 years' interest = (P + 1,000) − (P − 2,000) = ₹3,000. So SI(6) = ₹3,000 and P = 3,000 + 2,000 = ₹5,000 (rate 10%).","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"किसी धनराशि पर 6 वर्ष का साधारण ब्याज, धनराशि से ₹2,000 कम है, और 12 वर्ष का साधारण ब्याज धनराशि से ₹1,000 अधिक है। धनराशि क्या है?","optionsHi":["₹5,000","₹5,500","₹6,000","₹4,500"],"explanationHi":"SI(12) − SI(6) = 6 वर्ष का ब्याज = (P + 1,000) − (P − 2,000) = ₹3,000। अतः SI(6) = ₹3,000 और P = 3,000 + 2,000 = ₹5,000 (दर 10%)।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-66","question":"The simple interest on ₹x at r% per annum for t years is ₹576. The simple interest on ₹2x at (r/2)% per annum for (t + 4) years is ₹960. What is t?","options":["6 years","8 years","5 years","4 years"],"answer":0,"explanation":"2x × r/2 = xr, so the interests are in the ratio of the times: (t + 4)/t = 960/576 = 5/3, giving 3t + 12 = 5t and t = 6.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"₹x पर r% वार्षिक दर से t वर्ष का साधारण ब्याज ₹576 है। ₹2x पर (r/2)% वार्षिक दर से (t + 4) वर्ष का साधारण ब्याज ₹960 है। t क्या है?","optionsHi":["6 वर्ष","8 वर्ष","5 वर्ष","4 वर्ष"],"explanationHi":"2x × r/2 = xr, इसलिए ब्याजों का अनुपात समय के अनुपात के बराबर है: (t + 4)/t = 960/576 = 5/3, जिससे 3t + 12 = 5t और t = 6।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-67","question":"A phone costs ₹30,000 in cash, or ₹6,000 down plus 12 monthly instalments of ₹2,200. What flat rate of simple interest per annum is charged under the instalment plan?","options":["10%","8%","9.09%","12%"],"answer":0,"explanation":"Amount financed = ₹24,000; total repaid = 12 × 2,200 = ₹26,400, so interest = ₹2,400 for 1 year: flat rate = 2,400/24,000 = 10%. 9.09% divides by ₹26,400 instead of the amount financed.","difficulty":"very-hard","source":"RRB NTPC · SSC CGL","questionHi":"एक फोन नकद ₹30,000 का है, या ₹6,000 अग्रिम और ₹2,200 की 12 मासिक किस्तों में। किस्त योजना में कितनी वार्षिक फ्लैट साधारण ब्याज दर लगाई जा रही है?","optionsHi":["10%","8%","9.09%","12%"],"explanationHi":"वित्तपोषित राशि = ₹24,000; कुल चुकाई गई राशि = 12 × 2,200 = ₹26,400, अतः 1 वर्ष का ब्याज ₹2,400: फ्लैट दर = 2,400/24,000 = 10%। 9.09% में वित्तपोषित राशि की जगह ₹26,400 से भाग दिया गया है।","subtopic":"instalments"},
  {"id":"quant-simple-interest-68","question":"₹25,300 is divided among A, B and C so that their amounts after 2, 3 and 4 years respectively, at 10% per annum simple interest, are equal. What is C's share?","options":["₹7,800","₹7,200","₹9,100","₹8,400"],"answer":0,"explanation":"1.2A = 1.3B = 1.4C, so A : B : C = 1/12 : 1/13 : 1/14 = 91 : 84 : 78 (sum 253). C = 78/253 × 25,300 = ₹7,800. Check: 9,100 × 1.2 = 8,400 × 1.3 = 7,800 × 1.4 = ₹10,920.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"₹25,300 को A, B और C में इस प्रकार बाँटा गया कि 10% वार्षिक साधारण ब्याज पर क्रमशः 2, 3 और 4 वर्ष बाद उनके मिश्रधन बराबर हैं। C का हिस्सा क्या है?","optionsHi":["₹7,800","₹7,200","₹9,100","₹8,400"],"explanationHi":"1.2A = 1.3B = 1.4C, अतः A : B : C = 1/12 : 1/13 : 1/14 = 91 : 84 : 78 (योग 253)। C = 78/253 × 25,300 = ₹7,800। जाँच: 9,100 × 1.2 = 8,400 × 1.3 = 7,800 × 1.4 = ₹10,920।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-69","question":"What is the simple interest on ₹18,000 at 9% per annum for 2½ years?","options":["₹3,240","₹4,050","₹4,500","₹4,860"],"answer":1,"explanation":"SI = 18,000 × 9 × 2.5/100 = ₹4,050. Using 2 years instead of 2.5 gives ₹3,240.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"₹18,000 पर 9% वार्षिक दर से 2½ वर्ष का साधारण ब्याज क्या है?","optionsHi":["₹3,240","₹4,050","₹4,500","₹4,860"],"explanationHi":"SI = 18,000 × 9 × 2.5/100 = ₹4,050। 2.5 की जगह 2 वर्ष लेने पर ₹3,240 आता है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-70","question":"What principal will earn ₹1,350 as simple interest in 5 years at 4.5% per annum?","options":["₹6,000","₹6,750","₹5,400","₹3,000"],"answer":0,"explanation":"P = SI × 100/(R × T) = 1,350 × 100/22.5 = ₹6,000. ₹6,750 multiplies 1,350 by 5 (forgetting the rate), and ₹3,000 uses the rate as 9%.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"कौन-सा मूलधन 4.5% वार्षिक दर से 5 वर्ष में ₹1,350 साधारण ब्याज अर्जित करेगा?","optionsHi":["₹6,000","₹6,750","₹5,400","₹3,000"],"explanationHi":"P = SI × 100/(R × T) = 1,350 × 100/22.5 = ₹6,000। ₹6,750 में 1,350 को 5 से गुणा किया गया है (दर को भूलकर), और ₹3,000 में दर 9% ली गई है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-71","question":"₹6,400 earns ₹1,152 as simple interest in 3 years. What is the rate per annum?","options":["18%","5.5%","6.5%","6%"],"answer":3,"explanation":"R = 1,152 × 100/(6,400 × 3) = 6%. 18% is the total interest for all three years.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"₹6,400 पर 3 वर्ष में ₹1,152 साधारण ब्याज मिलता है। वार्षिक दर क्या है?","optionsHi":["18%","5.5%","6.5%","6%"],"explanationHi":"R = 1,152 × 100/(6,400 × 3) = 6%। 18% तीनों वर्षों का कुल ब्याज प्रतिशत है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-72","question":"In how many years will ₹12,500 earn ₹3,750 as simple interest at 6% per annum?","options":["4 years","6 years","5 years","3 years"],"answer":2,"explanation":"T = 3,750 × 100/(12,500 × 6) = 5 years. Interest is 30% of the principal, and 30 ÷ 6 = 5.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"6% वार्षिक दर पर ₹12,500 कितने वर्षों में ₹3,750 साधारण ब्याज अर्जित करेंगे?","optionsHi":["4 वर्ष","6 वर्ष","5 वर्ष","3 वर्ष"],"explanationHi":"T = 3,750 × 100/(12,500 × 6) = 5 वर्ष। ब्याज मूलधन का 30% है, और 30 ÷ 6 = 5।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-73","question":"A fixed deposit of ₹3 lakh earns 7.25% simple interest per annum. How much interest does it earn in one year?","options":["₹2,175","₹21,500","₹21,750","₹22,500"],"answer":2,"explanation":"7.25% of ₹3,00,000 = 3 × 7,250 = ₹21,750. ₹2,175 slips a zero by treating ₹3 lakh as ₹30,000, and ₹22,500 rounds the rate to 7.5%.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk","questionHi":"₹3 लाख की सावधि जमा (FD) पर 7.25% वार्षिक साधारण ब्याज मिलता है। एक वर्ष में कितना ब्याज मिलेगा?","optionsHi":["₹2,175","₹21,500","₹21,750","₹22,500"],"explanationHi":"₹3,00,000 का 7.25% = 3 × 7,250 = ₹21,750। ₹2,175 में ₹3 लाख को ₹30,000 मान लेने से एक शून्य छूट गया है, और ₹22,500 में दर को 7.5% पूर्णांकित कर दिया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-74","question":"A village moneylender charges interest at 'one paisa per rupee per month'. What is the annual rate of simple interest?","options":["1%","12%","10%","6%"],"answer":1,"explanation":"1 paisa per rupee = 1% per month, so the annual rate is 12%.","difficulty":"easy","source":"SSC CHSL · State PSC","questionHi":"गाँव का एक साहूकार 'एक रुपये पर एक पैसा प्रति माह' की दर से ब्याज लेता है। वार्षिक साधारण ब्याज दर क्या है?","optionsHi":["1%","12%","10%","6%"],"explanationHi":"एक रुपये पर 1 पैसा = 1% प्रति माह, इसलिए वार्षिक दर 12% है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-75","question":"A loan carries interest of ₹1.50 per hundred rupees per month. What is the annual rate of simple interest?","options":["18%","15%","1.5%","12%"],"answer":0,"explanation":"₹1.50 per ₹100 per month is 1.5% a month, so 1.5 × 12 = 18% a year. 1.5% forgets to annualise, and 15% multiplies by 10 instead of 12.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"एक ऋण पर ब्याज ₹1.50 प्रति सैकड़ा रुपये प्रति माह है। वार्षिक साधारण ब्याज दर क्या है?","optionsHi":["18%","15%","1.5%","12%"],"explanationHi":"₹100 पर ₹1.50 प्रति माह का अर्थ 1.5% प्रति माह है, इसलिए 1.5 × 12 = 18% प्रति वर्ष। 1.5% में वार्षिक नहीं किया गया है, और 15% में 12 की जगह 10 से गुणा किया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-76","question":"What is the simple interest on ₹73,000 at 10% per annum for 146 days (take 365 days in a year)?","options":["₹2,880","₹3,650","₹2,190","₹2,920"],"answer":3,"explanation":"146/365 = 0.4 year, so SI = 73,000 × 10% × 0.4 = ₹2,920. ₹2,880 uses 144 days, and ₹3,650 or ₹2,190 use half or 0.3 of a year.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"₹73,000 पर 10% वार्षिक दर से 146 दिन का साधारण ब्याज क्या है (एक वर्ष में 365 दिन मानें)?","optionsHi":["₹2,880","₹3,650","₹2,190","₹2,920"],"explanationHi":"146/365 = 0.4 वर्ष, अतः SI = 73,000 × 10% × 0.4 = ₹2,920। ₹2,880 में 144 दिन लिए गए हैं, और ₹3,650 या ₹2,190 में वर्ष का आधा या 0.3 भाग लिया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-77","question":"When the rate of interest falls from 9% to 7.5% per annum, a man's yearly simple interest income falls by ₹540. What is his capital?","options":["₹6,000","₹7,200","₹40,000","₹36,000"],"answer":3,"explanation":"A fall of 1.5% of the capital = ₹540, so the capital = 540 × 100/1.5 = ₹36,000.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"जब ब्याज दर 9% से घटकर 7.5% वार्षिक हो जाती है, तो एक व्यक्ति की वार्षिक साधारण ब्याज आय ₹540 घट जाती है। उसकी पूँजी क्या है?","optionsHi":["₹6,000","₹7,200","₹40,000","₹36,000"],"explanationHi":"पूँजी के 1.5% की कमी = ₹540, अतः पूँजी = 540 × 100/1.5 = ₹36,000।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-78","question":"The ratio of a principal to the simple interest on it for 8 years is 5 : 2. What is the rate per annum?","options":["2.5%","4%","5%","8%"],"answer":2,"explanation":"SI is 2/5 = 40% of the principal over 8 years, so R = 40/8 = 5%.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"किसी मूलधन और उस पर 8 वर्ष के साधारण ब्याज का अनुपात 5 : 2 है। वार्षिक दर क्या है?","optionsHi":["2.5%","4%","5%","8%"],"explanationHi":"8 वर्ष में SI मूलधन का 2/5 = 40% है, इसलिए R = 40/8 = 5%।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-79","question":"A bank pays 7% per annum simple interest on 3-year deposits and 0.5 percentage points extra to senior citizens. How much more does a senior citizen earn than others on ₹2,40,000 over 3 years?","options":["₹1,200","₹3,600","₹7,200","₹3,000"],"answer":1,"explanation":"Extra = 0.5% × 2,40,000 × 3 = ₹3,600. ₹1,200 is the extra for one year only.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk","questionHi":"एक बैंक 3 वर्ष की जमा पर 7% वार्षिक साधारण ब्याज देता है और वरिष्ठ नागरिकों को 0.5 प्रतिशत अंक अतिरिक्त देता है। ₹2,40,000 पर 3 वर्ष में एक वरिष्ठ नागरिक दूसरों से कितना अधिक कमाता है?","optionsHi":["₹1,200","₹3,600","₹7,200","₹3,000"],"explanationHi":"अतिरिक्त = 0.5% × 2,40,000 × 3 = ₹3,600। ₹1,200 केवल एक वर्ष का अतिरिक्त ब्याज है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-80","question":"What is the simple interest on ₹40,000 at 1.5% per month for 7 months?","options":["₹4,200","₹3,500","₹6,000","₹4,500"],"answer":0,"explanation":"Monthly interest = 1.5% of 40,000 = ₹600. For 7 months: ₹4,200.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk","questionHi":"₹40,000 पर 1.5% प्रति माह की दर से 7 महीने का साधारण ब्याज क्या है?","optionsHi":["₹4,200","₹3,500","₹6,000","₹4,500"],"explanationHi":"मासिक ब्याज = 40,000 का 1.5% = ₹600। 7 महीने के लिए: ₹4,200।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-81","question":"The simple interest on a sum for 2 years at 8% per annum is ₹1,920. What is the simple interest on the same sum for 3 years at 10% per annum?","options":["₹3,600","₹2,880","₹3,000","₹4,000"],"answer":0,"explanation":"2 × 8 = 16% of the sum is ₹1,920, so 1% = ₹120. 3 × 10 = 30% gives ₹3,600.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर 8% वार्षिक दर से 2 वर्ष का साधारण ब्याज ₹1,920 है। उसी धनराशि पर 10% वार्षिक दर से 3 वर्ष का साधारण ब्याज क्या है?","optionsHi":["₹3,600","₹2,880","₹3,000","₹4,000"],"explanationHi":"2 × 8 = धनराशि का 16% = ₹1,920, अतः 1% = ₹120। 3 × 10 = 30% से ₹3,600।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-82","question":"A gold loan of ₹1,20,000 is taken at 1% per month simple interest and repaid with interest after 10 months. How much is repaid?","options":["₹1,21,200","₹1,34,400","₹1,30,000","₹1,32,000"],"answer":3,"explanation":"Interest = 1% × 10 months = 10% of the loan = ₹12,000. Repayment = ₹1,32,000.","difficulty":"moderate","source":"IBPS Clerk · RRB Clerk","questionHi":"₹1,20,000 का स्वर्ण ऋण 1% प्रति माह साधारण ब्याज पर लिया गया और 10 महीने बाद ब्याज सहित चुकाया गया। कितनी राशि चुकाई गई?","optionsHi":["₹1,21,200","₹1,34,400","₹1,30,000","₹1,32,000"],"explanationHi":"ब्याज = 1% × 10 महीने = ऋण का 10% = ₹12,000। चुकाई गई राशि = ₹1,32,000।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-83","question":"A farmer borrows ₹3 lakh on a crop loan at 7% simple interest. For prompt repayment he gets an interest subvention of 3 percentage points. If he repays promptly after one year, how much interest does he save?","options":["₹12,000","₹21,000","₹9,000","₹6,300"],"answer":2,"explanation":"The subvention cuts the rate from 7% to 4%. Saving = 3% of 3,00,000 = ₹9,000; he pays ₹12,000 instead of ₹21,000.","difficulty":"moderate","source":"IBPS RRB · NABARD","questionHi":"एक किसान 7% साधारण ब्याज पर ₹3 लाख का फसल ऋण लेता है। समय पर चुकाने पर उसे 3 प्रतिशत अंक की ब्याज छूट मिलती है। यदि वह एक वर्ष बाद समय पर चुका देता है, तो वह कितना ब्याज बचाता है?","optionsHi":["₹12,000","₹21,000","₹9,000","₹6,300"],"explanationHi":"छूट से दर 7% से घटकर 4% हो जाती है। बचत = 3,00,000 का 3% = ₹9,000; वह ₹21,000 की जगह ₹12,000 चुकाता है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-84","question":"The simple interest on ₹2,000 rises by ₹40 when the period is extended by 4 months. What is the rate per annum?","options":["2%","6%","8%","5%"],"answer":1,"explanation":"₹40 is the interest for 4 months = 1/3 year: R = 40 × 100/(2,000 × 1/3) = 6%.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"जब अवधि 4 महीने बढ़ा दी जाती है, तो ₹2,000 पर साधारण ब्याज ₹40 बढ़ जाता है। वार्षिक दर क्या है?","optionsHi":["2%","6%","8%","5%"],"explanationHi":"₹40, 4 महीने = 1/3 वर्ष का ब्याज है: R = 40 × 100/(2,000 × 1/3) = 6%।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-85","question":"A deposit pays simple interest of 9% per annum, credited every quarter. If the quarterly interest is ₹1,800, how much is deposited?","options":["₹20,000","₹80,000","₹60,000","₹72,000"],"answer":1,"explanation":"Yearly interest = 4 × 1,800 = ₹7,200 = 9% of the deposit. Deposit = ₹80,000.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk","questionHi":"एक जमा पर 9% वार्षिक साधारण ब्याज मिलता है, जो हर तिमाही जमा होता है। यदि तिमाही ब्याज ₹1,800 है, तो कितनी राशि जमा की गई है?","optionsHi":["₹20,000","₹80,000","₹60,000","₹72,000"],"explanationHi":"वार्षिक ब्याज = 4 × 1,800 = ₹7,200 = जमा का 9%। जमा राशि = ₹80,000।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-86","question":"A post office monthly income scheme pays 7.4% per annum simple interest, paid out every month. What is the monthly income on a deposit of ₹9 lakh?","options":["₹5,550","₹6,660","₹5,400","₹66,600"],"answer":0,"explanation":"Yearly interest = 7.4% of 9,00,000 = ₹66,600. Monthly = 66,600 ÷ 12 = ₹5,550.","difficulty":"moderate","source":"IBPS Clerk · RRB NTPC","questionHi":"डाकघर की एक मासिक आय योजना 7.4% वार्षिक साधारण ब्याज देती है, जो हर महीने दिया जाता है। ₹9 लाख की जमा पर मासिक आय क्या है?","optionsHi":["₹5,550","₹6,660","₹5,400","₹66,600"],"explanationHi":"वार्षिक ब्याज = 9,00,000 का 7.4% = ₹66,600। मासिक = 66,600 ÷ 12 = ₹5,550।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-87","question":"What is the present worth of ₹11,520 due 2 years hence at 10% per annum simple interest?","options":["₹9,216","₹10,080","₹9,520","₹9,600"],"answer":3,"explanation":"Present worth P grows to P × 1.2 in 2 years, so P = 11,520 ÷ 1.2 = ₹9,600. Subtracting 20% of 11,520 (₹9,216) is the trap.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"10% वार्षिक साधारण ब्याज की दर से 2 वर्ष बाद देय ₹11,520 का वर्तमान मूल्य (present worth) क्या है?","optionsHi":["₹9,216","₹10,080","₹9,520","₹9,600"],"explanationHi":"वर्तमान मूल्य P, 2 वर्ष में P × 1.2 हो जाता है, अतः P = 11,520 ÷ 1.2 = ₹9,600। 11,520 का 20% घटाना (₹9,216) ही जाल है।","subtopic":"present-worth-discount"},
  {"id":"quant-simple-interest-88","question":"₹400 amounts to ₹480 in 4 years at simple interest. What will ₹600 amount to in 5 years at a rate 1 percentage point higher?","options":["₹750","₹720","₹780","₹810"],"answer":2,"explanation":"Rate = 80 × 100/(400 × 4) = 5%, so the new rate is 6%. ₹600 for 5 years at 6% earns 30%, giving ₹780.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"साधारण ब्याज पर ₹400, 4 वर्ष में ₹480 हो जाते हैं। 1 प्रतिशत अंक अधिक दर पर ₹600 का 5 वर्ष में मिश्रधन क्या होगा?","optionsHi":["₹750","₹720","₹780","₹810"],"explanationHi":"दर = 80 × 100/(400 × 4) = 5%, अतः नई दर 6% है। ₹600 पर 6% से 5 वर्ष में 30% ब्याज मिलता है, जिससे मिश्रधन ₹780 होता है।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-89","question":"In how many years will the simple interest on ₹3,600 at 7% per annum equal the simple interest on ₹4,200 at 9% per annum for 4 years?","options":["5 years","7 years","6 years","4.5 years"],"answer":2,"explanation":"Target = 4,200 × 9% × 4 = ₹1,512. Yearly interest on 3,600 at 7% = ₹252. Time = 1,512 ÷ 252 = 6 years.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"₹3,600 पर 7% वार्षिक दर का साधारण ब्याज, ₹4,200 पर 9% वार्षिक दर से 4 वर्ष के साधारण ब्याज के बराबर कितने वर्षों में होगा?","optionsHi":["5 वर्ष","7 वर्ष","6 वर्ष","4.5 वर्ष"],"explanationHi":"लक्ष्य = 4,200 × 9% × 4 = ₹1,512। 3,600 पर 7% का वार्षिक ब्याज = ₹252। समय = 1,512 ÷ 252 = 6 वर्ष।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-90","question":"A trader borrows ₹1 lakh at '2 paise per rupee per month' simple interest. How much interest does he owe after 18 months?","options":["₹3,600","₹36,000","₹24,000","₹18,000"],"answer":1,"explanation":"2 paise per rupee per month = 2% per month. For 18 months: 36% of 1,00,000 = ₹36,000.","difficulty":"moderate","source":"SSC CHSL · State PSC","questionHi":"एक व्यापारी '2 पैसे प्रति रुपया प्रति माह' साधारण ब्याज पर ₹1 लाख उधार लेता है। 18 महीने बाद उस पर कितना ब्याज बनता है?","optionsHi":["₹3,600","₹36,000","₹24,000","₹18,000"],"explanationHi":"2 पैसे प्रति रुपया प्रति माह = 2% प्रति माह। 18 महीनों के लिए: 1,00,000 का 36% = ₹36,000।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-91","question":"Repaying a loan with 9% simple interest after 4 years costs ₹1,620 more than repaying it after 2 years. What is the loan amount?","options":["₹9,000","₹4,500","₹18,000","₹13,500"],"answer":0,"explanation":"The extra cost is 2 years' interest = 18% of the loan = ₹1,620. Loan = ₹9,000.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"9% साधारण ब्याज वाले ऋण को 4 वर्ष बाद चुकाने में 2 वर्ष बाद चुकाने की तुलना में ₹1,620 अधिक लगते हैं। ऋण की राशि क्या है?","optionsHi":["₹9,000","₹4,500","₹18,000","₹13,500"],"explanationHi":"अतिरिक्त लागत 2 वर्ष का ब्याज = ऋण का 18% = ₹1,620। ऋण = ₹9,000।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-92","question":"₹20,000 is lent at r% per annum simple interest for the first 3 years and at (r + 2)% for the next 2 years. If the total interest is ₹9,800, what is r?","options":["9.8","8.6","9.4","9"],"answer":3,"explanation":"Interest = 20,000 × [3r + 2(r + 2)]/100 = 200(5r + 4) = 9,800, so 5r + 4 = 49 and r = 9. 9.8 ignores the extra 2%, 9.4 adds it for only one year, and 8.6 applies (r + 2)% to the first 3 years instead of the last 2.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"₹20,000 को पहले 3 वर्ष के लिए r% वार्षिक साधारण ब्याज पर और अगले 2 वर्ष के लिए (r + 2)% पर उधार दिया गया है। यदि कुल ब्याज ₹9,800 है, तो r क्या है?","optionsHi":["9.8","8.6","9.4","9"],"explanationHi":"ब्याज = 20,000 × [3r + 2(r + 2)]/100 = 200(5r + 4) = 9,800, अतः 5r + 4 = 49 और r = 9। 9.8 में अतिरिक्त 2% को नज़रअंदाज़ किया गया है, 9.4 में उसे केवल एक वर्ष के लिए जोड़ा गया है, और 8.6 में (r + 2)% को अंतिम 2 वर्ष की जगह पहले 3 वर्ष पर लगाया गया है।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-93","question":"Two equal sums are lent at 8% and 6% per annum simple interest. The second is lent for 3 years longer than the first, and both earn the same interest. For how many years is the second sum lent?","options":["9","15","10","12"],"answer":3,"explanation":"8t = 6(t + 3) gives 2t = 18, so t = 9 and the second sum is lent for 12 years.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"दो बराबर धनराशियाँ 8% और 6% वार्षिक साधारण ब्याज पर उधार दी गई हैं। दूसरी धनराशि पहली से 3 वर्ष अधिक के लिए उधार दी गई है, और दोनों समान ब्याज अर्जित करती हैं। दूसरी धनराशि कितने वर्षों के लिए उधार दी गई है?","optionsHi":["9","15","10","12"],"explanationHi":"8t = 6(t + 3) से 2t = 18, अतः t = 9 और दूसरी धनराशि 12 वर्ष के लिए उधार दी गई है।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-94","question":"The simple interest on a sum for 3 years at r% is ₹4,500, and for 4 years at (r + 3)% it is ₹8,400. What is the sum?","options":["₹15,000","₹25,000","₹20,000","₹18,000"],"answer":2,"explanation":"P × r = 1,50,000 and P × (r + 3) = 2,10,000. Subtracting, 3P = 60,000, so P = ₹20,000 (and r = 7.5).","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"किसी धनराशि पर r% से 3 वर्ष का साधारण ब्याज ₹4,500 है, और (r + 3)% से 4 वर्ष का ब्याज ₹8,400 है। धनराशि क्या है?","optionsHi":["₹15,000","₹25,000","₹20,000","₹18,000"],"explanationHi":"P × r = 1,50,000 और P × (r + 3) = 2,10,000। घटाने पर 3P = 60,000, अतः P = ₹20,000 (और r = 7.5)।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-95","question":"Mohan deposits ₹1,000 at the start of each year for 4 years in a scheme paying 10% simple interest. How much does he get at the end of the fourth year?","options":["₹4,400","₹5,000","₹4,600","₹5,400"],"answer":1,"explanation":"The deposits earn interest for 4, 3, 2 and 1 years: 1,400 + 1,300 + 1,200 + 1,100 = ₹5,000.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk","questionHi":"मोहन 10% साधारण ब्याज देने वाली एक योजना में 4 वर्ष तक हर वर्ष की शुरुआत में ₹1,000 जमा करता है। चौथे वर्ष के अंत में उसे कितना मिलेगा?","optionsHi":["₹4,400","₹5,000","₹4,600","₹5,400"],"explanationHi":"जमाओं पर क्रमशः 4, 3, 2 और 1 वर्ष का ब्याज मिलता है: 1,400 + 1,300 + 1,200 + 1,100 = ₹5,000।","subtopic":"instalments"},
  {"id":"quant-simple-interest-96","question":"A man borrows ₹5,000 at 10% simple interest, charged only on the principal outstanding. At the end of the first year he pays that year's interest plus ₹2,000 of principal. How much must he pay at the end of the second year to clear the loan?","options":["₹3,300","₹3,850","₹3,500","₹3,000"],"answer":0,"explanation":"After year 1 the outstanding principal is ₹3,000. Year 2 interest = ₹300, so he pays ₹3,300.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"एक व्यक्ति ₹5,000 का ऋण 10% साधारण ब्याज पर लेता है, जो केवल बकाया मूलधन पर लगता है। पहले वर्ष के अंत में वह उस वर्ष का ब्याज और ₹2,000 मूलधन चुकाता है। ऋण चुकता करने के लिए उसे दूसरे वर्ष के अंत में कितना देना होगा?","optionsHi":["₹3,300","₹3,850","₹3,500","₹3,000"],"explanationHi":"पहले वर्ष के बाद बकाया मूलधन ₹3,000 है। दूसरे वर्ष का ब्याज = ₹300, इसलिए उसे ₹3,300 देने होंगे।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-97","question":"A sum amounts to ₹13,800 in 4 years at r% simple interest and to ₹16,200 in 4 years at (r + 5)%. What is r?","options":["3.75","5","4.5","3.5"],"answer":0,"explanation":"5% extra for 4 years = 20% of P = ₹2,400, so P = ₹12,000. Interest at r% = ₹1,800, giving r = 1,800 × 100/(12,000 × 4) = 3.75.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"कोई धनराशि r% साधारण ब्याज पर 4 वर्ष में ₹13,800 हो जाती है और (r + 5)% पर 4 वर्ष में ₹16,200 हो जाती है। r क्या है?","optionsHi":["3.75","5","4.5","3.5"],"explanationHi":"4 वर्ष के लिए अतिरिक्त 5% = P का 20% = ₹2,400, अतः P = ₹12,000। r% पर ब्याज = ₹1,800, जिससे r = 1,800 × 100/(12,000 × 4) = 3.75।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-98","question":"Bank A pays 8.5% simple interest on a 3-year deposit. Bank B pays 8% but adds a ₹600 bonus at maturity. For what deposit do the two banks pay the same?","options":["₹20,000","₹1,20,000","₹60,000","₹40,000"],"answer":3,"explanation":"Bank A's extra = 0.5% × 3 years = 1.5% of the deposit. 1.5% = ₹600 gives ₹40,000. Below this, Bank B is better.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"बैंक A 3 वर्ष की जमा पर 8.5% साधारण ब्याज देता है। बैंक B 8% देता है लेकिन परिपक्वता पर ₹600 का बोनस जोड़ता है। किस जमा राशि पर दोनों बैंक समान देते हैं?","optionsHi":["₹20,000","₹1,20,000","₹60,000","₹40,000"],"explanationHi":"बैंक A का अतिरिक्त = 0.5% × 3 वर्ष = जमा का 1.5%। 1.5% = ₹600 से ₹40,000 आता है। इससे कम जमा पर बैंक B बेहतर है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-99","question":"A sum earns simple interest at r% in the first year, 2r% in the second year and 3r% in the third year. If the total interest is 24% of the sum, what is r?","options":["8","6","4","3"],"answer":2,"explanation":"The yearly rates add under simple interest: r + 2r + 3r = 6r = 24, so r = 4. 8 divides 24 by 3 years, ignoring the rising rates, and 6 divides by 4.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"एक धनराशि पर साधारण ब्याज पहले वर्ष में r%, दूसरे वर्ष में 2r% और तीसरे वर्ष में 3r% की दर से मिलता है। यदि कुल ब्याज धनराशि का 24% है, तो r क्या है?","optionsHi":["8","6","4","3"],"explanationHi":"साधारण ब्याज में वार्षिक दरें जुड़ती हैं: r + 2r + 3r = 6r = 24, अतः r = 4। 8 में 24 को 3 वर्ष से भाग दिया गया है, बढ़ती दरों को नज़रअंदाज़ करके, और 6 में 4 से भाग दिया गया है।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-100","question":"A man lends ₹x to A at 10% for 3 years and ₹(x + 5,000) to B at 8% for 2 years, both at simple interest. If his total interest is ₹4,480, what is x?","options":["₹9,000","₹8,000","₹7,500","₹6,000"],"answer":1,"explanation":"0.3x + 0.16(x + 5,000) = 4,480 gives 0.46x + 800 = 4,480, so x = ₹8,000.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक व्यक्ति ₹x, A को 10% पर 3 वर्ष के लिए और ₹(x + 5,000), B को 8% पर 2 वर्ष के लिए उधार देता है, दोनों साधारण ब्याज पर। यदि उसका कुल ब्याज ₹4,480 है, तो x क्या है?","optionsHi":["₹9,000","₹8,000","₹7,500","₹6,000"],"explanationHi":"0.3x + 0.16(x + 5,000) = 4,480 से 0.46x + 800 = 4,480, अतः x = ₹8,000।","subtopic":"lending-borrowing"},
  {"id":"quant-simple-interest-101","question":"₹6,000 is lent at 12% and ₹7,500 at 8% per annum simple interest, starting on the same day. After how many years will the two amounts be equal?","options":["10 years","12.5 years","15 years","12 years"],"answer":1,"explanation":"The first grows by ₹720 a year and the second by ₹600, so the gap of ₹1,500 closes at ₹120 a year: 1,500 ÷ 120 = 12.5 years.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"₹6,000 को 12% पर और ₹7,500 को 8% वार्षिक साधारण ब्याज पर एक ही दिन से उधार दिया गया है। कितने वर्ष बाद दोनों मिश्रधन बराबर होंगे?","optionsHi":["10 वर्ष","12.5 वर्ष","15 वर्ष","12 वर्ष"],"explanationHi":"पहला प्रति वर्ष ₹720 और दूसरा ₹600 बढ़ता है, इसलिए ₹1,500 का अंतर ₹120 प्रति वर्ष की दर से कम होता है: 1,500 ÷ 120 = 12.5 वर्ष।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-102","question":"A sum earns a certain simple interest in t years at 10% per annum. At 8% per annum it takes one year more to earn the same interest. What is t?","options":["4","5","3","8"],"answer":0,"explanation":"Same interest means the same rate × time: 10t = 8(t + 1), so t = 4.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"कोई धनराशि 10% वार्षिक दर पर t वर्ष में एक निश्चित साधारण ब्याज अर्जित करती है। 8% वार्षिक दर पर उतना ही ब्याज अर्जित करने में एक वर्ष अधिक लगता है। t क्या है?","optionsHi":["4","5","3","8"],"explanationHi":"समान ब्याज का अर्थ है दर × समय समान: 10t = 8(t + 1), अतः t = 4।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-103","question":"A two-wheeler costs ₹20,000 in cash, or ₹5,000 down and ₹15,900 after 6 months. What annual rate of simple interest is being charged?","options":["6%","9%","10.6%","12%"],"answer":3,"explanation":"The amount financed is ₹15,000 and the interest is ₹900 for half a year. Rate = 900 × 100/(15,000 × 0.5) = 12%.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक दोपहिया वाहन नकद ₹20,000 का है, या ₹5,000 अग्रिम और 6 महीने बाद ₹15,900 देकर। साधारण ब्याज की कितनी वार्षिक दर ली जा रही है?","optionsHi":["6%","9%","10.6%","12%"],"explanationHi":"वित्तपोषित राशि ₹15,000 है और आधे वर्ष का ब्याज ₹900 है। दर = 900 × 100/(15,000 × 0.5) = 12%।","subtopic":"instalments"},
  {"id":"quant-simple-interest-104","question":"What is the true discount on ₹5,300 due 9 months hence at 8% per annum simple interest?","options":["₹318","₹280","₹300","₹312"],"answer":2,"explanation":"Interest for 9 months at 8% = 6%, so the present worth = 5,300 ÷ 1.06 = ₹5,000 and the true discount = ₹300. 6% of 5,300 (₹318) is the trap.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"8% वार्षिक साधारण ब्याज की दर से 9 महीने बाद देय ₹5,300 पर सही छूट (true discount) क्या है?","optionsHi":["₹318","₹280","₹300","₹312"],"explanationHi":"8% पर 9 महीने का ब्याज = 6%, अतः वर्तमान मूल्य = 5,300 ÷ 1.06 = ₹5,000 और सही छूट = ₹300। 5,300 का 6% (₹318) लेना जाल है।","subtopic":"present-worth-discount"},
  {"id":"quant-simple-interest-105","question":"A cooperative bank pays 8% simple interest on the first ₹1 lakh of a deposit and 9% on the amount above ₹1 lakh. A 2-year deposit earns ₹25,000 in interest. How much was deposited?","options":["₹1,38,889","₹1,40,000","₹1,50,000","₹1,56,250"],"answer":2,"explanation":"The first lakh earns 16% over 2 years = ₹16,000. The remaining ₹9,000 is 18% of the excess, so the excess = ₹50,000 and the deposit = ₹1,50,000.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"एक सहकारी बैंक जमा की पहली ₹1 लाख पर 8% साधारण ब्याज और ₹1 लाख से ऊपर की राशि पर 9% देता है। 2 वर्ष की एक जमा पर ₹25,000 ब्याज मिलता है। कितनी राशि जमा की गई थी?","optionsHi":["₹1,38,889","₹1,40,000","₹1,50,000","₹1,56,250"],"explanationHi":"पहले एक लाख पर 2 वर्ष में 16% = ₹16,000 मिलता है। शेष ₹9,000 अधिक राशि का 18% है, इसलिए अधिक राशि = ₹50,000 और जमा = ₹1,50,000।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-106","question":"A scheme pays 4% simple interest in the first year, and the rate goes up by 1 percentage point every year after that. After how many years will the total interest equal 49% of the principal?","options":["6","7","12.25","10"],"answer":1,"explanation":"Add the yearly rates: 4 + 5 + 6 + 7 + 8 + 9 + 10 = 49 after 7 years. 6 counts the six increases instead of the years, 12.25 ignores the increases (49/4), and 10 is the rate in the final year, not the number of years.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक योजना पहले वर्ष में 4% साधारण ब्याज देती है, और उसके बाद हर वर्ष दर में 1 प्रतिशत अंक की वृद्धि होती है। कितने वर्षों बाद कुल ब्याज मूलधन के 49% के बराबर होगा?","optionsHi":["6","7","12.25","10"],"explanationHi":"वार्षिक दरें जोड़ें: 4 + 5 + 6 + 7 + 8 + 9 + 10 = 49, 7 वर्ष बाद। 6 में वर्षों की जगह वृद्धियों की गिनती की गई है, 12.25 में वृद्धि को नज़रअंदाज़ किया गया है (49/4), और 10 अंतिम वर्ष की दर है, वर्षों की संख्या नहीं।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-107","question":"If both the rate and the time of a simple-interest loan are increased by 20%, the interest goes up by ₹1,320. What was the original interest?","options":["₹3,000","₹3,300","₹6,600","₹2,750"],"answer":0,"explanation":"SI ∝ rate × time, so it becomes 1.2 × 1.2 = 1.44 times, a 44% rise. 44% = ₹1,320 gives ₹3,000. A 40% rise would give ₹3,300.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि किसी साधारण ब्याज वाले ऋण की दर और समय दोनों में 20% की वृद्धि कर दी जाए, तो ब्याज ₹1,320 बढ़ जाता है। मूल ब्याज क्या था?","optionsHi":["₹3,000","₹3,300","₹6,600","₹2,750"],"explanationHi":"SI ∝ दर × समय, इसलिए वह 1.2 × 1.2 = 1.44 गुना हो जाता है, यानी 44% की वृद्धि। 44% = ₹1,320 से ₹3,000 आता है। 40% वृद्धि मानने पर ₹3,300 आता।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-108","question":"The principal of a loan is increased by 25%, the rate of simple interest is cut by 20% and the time is extended by 10%. By what percent does the interest change?","options":["15% increase","No change","5% increase","10% increase"],"answer":3,"explanation":"SI ∝ P × R × T: 1.25 × 0.8 × 1.1 = 1.1, a 10% increase. Note 1.25 × 0.8 = 1 exactly.","difficulty":"hard","source":"SSC CGL · SSC CPO","questionHi":"किसी ऋण का मूलधन 25% बढ़ा दिया जाता है, साधारण ब्याज की दर 20% घटा दी जाती है और समय 10% बढ़ा दिया जाता है। ब्याज में कितने प्रतिशत परिवर्तन होता है?","optionsHi":["15% वृद्धि","कोई परिवर्तन नहीं","5% वृद्धि","10% वृद्धि"],"explanationHi":"SI ∝ P × R × T: 1.25 × 0.8 × 1.1 = 1.1, यानी 10% की वृद्धि। ध्यान दें 1.25 × 0.8 = 1 ठीक-ठीक होता है।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-109","question":"A credit card company charges 18% per annum simple interest on unpaid dues. What is the interest on ₹24,000 left unpaid for 73 days (365-day year)?","options":["₹4,320","₹720","₹1,080","₹864"],"answer":3,"explanation":"73 days = 73/365 = 1/5 year. Interest = 24,000 × 18% × 1/5 = ₹864.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk","questionHi":"एक क्रेडिट कार्ड कंपनी बकाया राशि पर 18% वार्षिक साधारण ब्याज लेती है। ₹24,000 को 73 दिन तक बिना चुकाए रखने पर ब्याज क्या होगा (वर्ष में 365 दिन)?","optionsHi":["₹4,320","₹720","₹1,080","₹864"],"explanationHi":"73 दिन = 73/365 = 1/5 वर्ष। ब्याज = 24,000 × 18% × 1/5 = ₹864।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-110","question":"A tax of ₹50,000 is paid 7 months late. The law charges simple interest at 1% per month on the tax plus a flat penalty of ₹5,000. How much is paid in all?","options":["₹55,000","₹59,200","₹58,500","₹53,500"],"answer":2,"explanation":"Interest = 1% × 7 months = 7% of 50,000 = ₹3,500. Total = 50,000 + 3,500 + 5,000 = ₹58,500.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"₹50,000 का कर 7 महीने देर से चुकाया जाता है। कानून कर पर 1% प्रति माह साधारण ब्याज और ₹5,000 का एकमुश्त जुर्माना लगाता है। कुल कितना चुकाना होगा?","optionsHi":["₹55,000","₹59,200","₹58,500","₹53,500"],"explanationHi":"ब्याज = 1% × 7 महीने = 50,000 का 7% = ₹3,500। कुल = 50,000 + 3,500 + 5,000 = ₹58,500।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-111","question":"The simple interest on a sum at 8% per annum for 5 years exceeds the simple interest on it at 6% per annum for 6 years by ₹240. What is the sum?","options":["₹4,000","₹6,000","₹12,000","₹2,400"],"answer":1,"explanation":"8 × 5 = 40% and 6 × 6 = 36%. The 4% difference = ₹240, so the sum = ₹6,000.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"किसी धनराशि पर 8% वार्षिक दर से 5 वर्ष का साधारण ब्याज, उसी पर 6% वार्षिक दर से 6 वर्ष के साधारण ब्याज से ₹240 अधिक है। धनराशि क्या है?","optionsHi":["₹4,000","₹6,000","₹12,000","₹2,400"],"explanationHi":"8 × 5 = 40% और 6 × 6 = 36%। 4% का अंतर = ₹240, अतः धनराशि = ₹6,000।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-112","question":"Of ₹50,000, ₹20,000 is invested at 6%, ₹18,000 at 8% and the rest at 10% simple interest. What is the average rate of interest earned?","options":["7.68%","8%","7.6%","7.84%"],"answer":0,"explanation":"Yearly interest = 1,200 + 1,440 + 1,200 = ₹3,840. Average rate = 3,840/50,000 = 7.68%. The plain average of the rates (8%) ignores the amounts.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"₹50,000 में से ₹20,000 को 6% पर, ₹18,000 को 8% पर और शेष को 10% साधारण ब्याज पर निवेश किया गया है। अर्जित औसत ब्याज दर क्या है?","optionsHi":["7.68%","8%","7.6%","7.84%"],"explanationHi":"वार्षिक ब्याज = 1,200 + 1,440 + 1,200 = ₹3,840। औसत दर = 3,840/50,000 = 7.68%। दरों का साधारण औसत (8%) राशियों को नज़रअंदाज़ करता है।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-113","question":"A sum is lent at r% simple interest for 4 years and then at (r + 2)% for 3 more years. If the total interest is 41% of the sum, what is r?","options":["5","6","4","5.5"],"answer":0,"explanation":"Total rate = 4r + 3(r + 2) = 41, so 7r = 35 and r = 5. Check the near guesses: r = 4 gives 34 and r = 6 gives 48; 5.5 comes from dropping the +2% and rounding 41/7.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"एक धनराशि पहले 4 वर्ष के लिए r% साधारण ब्याज पर और फिर 3 वर्ष और (r + 2)% पर उधार दी जाती है। यदि कुल ब्याज धनराशि का 41% है, तो r क्या है?","optionsHi":["5","6","4","5.5"],"explanationHi":"कुल दर = 4r + 3(r + 2) = 41, अतः 7r = 35 और r = 5। पास के अनुमानों की जाँच: r = 4 से 34 और r = 6 से 48 आता है; 5.5 +2% को छोड़कर 41/7 को पूर्णांकित करने से आता है।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-114","question":"A bank deducts 10% tax at source only when a depositor's interest in a year exceeds ₹40,000. Asha's deposit of ₹5 lakh earns 7% simple interest a year. How much interest does she receive each year?","options":["₹31,500","₹34,500","₹32,000","₹35,000"],"answer":3,"explanation":"Yearly interest = 7% of 5,00,000 = ₹35,000, which is below the ₹40,000 limit, so no tax is deducted. She receives the full ₹35,000.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk","questionHi":"एक बैंक किसी जमाकर्ता का एक वर्ष का ब्याज ₹40,000 से अधिक होने पर ही स्रोत पर 10% कर काटता है। आशा की ₹5 लाख की जमा पर 7% वार्षिक साधारण ब्याज मिलता है। उसे प्रति वर्ष कितना ब्याज मिलता है?","optionsHi":["₹31,500","₹34,500","₹32,000","₹35,000"],"explanationHi":"वार्षिक ब्याज = 5,00,000 का 7% = ₹35,000, जो ₹40,000 की सीमा से कम है, इसलिए कोई कर नहीं कटता। उसे पूरे ₹35,000 मिलते हैं।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-115","question":"A lender gives a one-year loan at 12% simple interest but deducts the interest in advance from the amount paid out. What is the effective annual rate for the borrower?","options":["12%","13%","13.64%","10.71%"],"answer":2,"explanation":"On ₹100 of loan the borrower gets only ₹88 but repays ₹100. Effective rate = 12/88 = 13.64%.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"एक ऋणदाता 12% साधारण ब्याज पर एक वर्ष का ऋण देता है, लेकिन ब्याज को पहले ही दी जाने वाली राशि में से काट लेता है। उधार लेने वाले के लिए प्रभावी वार्षिक दर क्या है?","optionsHi":["12%","13%","13.64%","10.71%"],"explanationHi":"₹100 के ऋण पर उधार लेने वाले को केवल ₹88 मिलते हैं लेकिन वह ₹100 चुकाता है। प्रभावी दर = 12/88 = 13.64%।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-116","question":"The simple interest on a sum is 24% of the sum. If the rate were 2 percentage points lower and the time 2 years longer, the interest would be the same. What is the rate?","options":["4%","6%","8%","3%"],"answer":1,"explanation":"rt = 24 and (r − 2)(t + 2) = 24 give 2r − 2t = 4, so r = t + 2. Then r(r − 2) = 24, so r = 6 (t = 4).","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"किसी धनराशि पर साधारण ब्याज उस धनराशि का 24% है। यदि दर 2 प्रतिशत अंक कम और समय 2 वर्ष अधिक होता, तो ब्याज वही रहता। दर क्या है?","optionsHi":["4%","6%","8%","3%"],"explanationHi":"rt = 24 और (r − 2)(t + 2) = 24 से 2r − 2t = 4, अतः r = t + 2। तब r(r − 2) = 24, इसलिए r = 6 (t = 4)।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-117","question":"Three sums A, B and C are lent at simple interest: A for 2 years at 6%, B for 3 years at 5% and C for 4 years at 4.5%. If all three earn equal interest, what is A : B : C?","options":["10 : 12 : 15","15 : 12 : 10","12 : 15 : 18","6 : 5 : 4"],"answer":1,"explanation":"Interest rates for the periods are 12%, 15% and 18%. Equal interest means 12A = 15B = 18C, so A : B : C = 1/12 : 1/15 : 1/18 = 15 : 12 : 10.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"तीन धनराशियाँ A, B और C साधारण ब्याज पर उधार दी गई हैं: A 2 वर्ष के लिए 6% पर, B 3 वर्ष के लिए 5% पर और C 4 वर्ष के लिए 4.5% पर। यदि तीनों समान ब्याज अर्जित करती हैं, तो A : B : C क्या है?","optionsHi":["10 : 12 : 15","15 : 12 : 10","12 : 15 : 18","6 : 5 : 4"],"explanationHi":"अवधियों के लिए ब्याज प्रतिशत 12%, 15% और 18% हैं। समान ब्याज का अर्थ है 12A = 15B = 18C, अतः A : B : C = 1/12 : 1/15 : 1/18 = 15 : 12 : 10।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-118","question":"A loan is taken at 12% simple interest. After 2 years, half the amount then due is paid. The rest is treated as a fresh loan at 12% simple interest and cleared a year later with a payment of ₹34,720. What was the original loan?","options":["₹50,000","₹56,000","₹48,000","₹62,000"],"answer":0,"explanation":"After 2 years the due is 1.24P; half of it, 0.62P, is carried forward and becomes 0.62P × 1.12 = 0.6944P. So P = 34,720 ÷ 0.6944 = ₹50,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"12% साधारण ब्याज पर एक ऋण लिया गया। 2 वर्ष बाद उस समय देय राशि का आधा चुका दिया जाता है। शेष को 12% साधारण ब्याज पर नया ऋण माना जाता है और एक वर्ष बाद ₹34,720 के भुगतान से चुकता कर दिया जाता है। मूल ऋण क्या था?","optionsHi":["₹50,000","₹56,000","₹48,000","₹62,000"],"explanationHi":"2 वर्ष बाद देय राशि 1.24P है; उसका आधा, 0.62P, आगे बढ़ता है और 0.62P × 1.12 = 0.6944P हो जाता है। अतः P = 34,720 ÷ 0.6944 = ₹50,000।","subtopic":"instalments"},
  {"id":"quant-simple-interest-119","question":"At simple interest a sum doubles in n years and triples in (n + 10) years. What is n?","options":["20","5","15","10"],"answer":3,"explanation":"Doubling means interest = P in n years; tripling means interest = 2P in n + 10 years. So n + 10 = 2n and n = 10.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"साधारण ब्याज पर कोई धनराशि n वर्ष में दोगुनी और (n + 10) वर्ष में तीन गुनी हो जाती है। n क्या है?","optionsHi":["20","5","15","10"],"explanationHi":"दोगुना होने का अर्थ है n वर्ष में ब्याज = P; तीन गुना होने का अर्थ है n + 10 वर्ष में ब्याज = 2P। अतः n + 10 = 2n और n = 10।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-120","question":"A student takes an education loan of ₹5 lakh at 9% simple interest. Interest accrues during the 4-year course; then the loan plus accrued interest becomes a fresh principal repaid with 9% simple interest over 5 years. What is the total interest paid?","options":["₹4,05,000","₹3,06,000","₹4,86,000","₹4,50,000"],"answer":2,"explanation":"Accrued interest = 5,00,000 × 36% = ₹1,80,000. New principal ₹6,80,000 earns 45% = ₹3,06,000. Total interest = 1,80,000 + 3,06,000 = ₹4,86,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"एक विद्यार्थी 9% साधारण ब्याज पर ₹5 लाख का शिक्षा ऋण लेता है। 4 वर्ष के पाठ्यक्रम के दौरान ब्याज जुड़ता रहता है; फिर ऋण और संचित ब्याज मिलकर नया मूलधन बन जाता है, जिसे 9% साधारण ब्याज पर 5 वर्ष में चुकाया जाता है। चुकाया गया कुल ब्याज क्या है?","optionsHi":["₹4,05,000","₹3,06,000","₹4,86,000","₹4,50,000"],"explanationHi":"संचित ब्याज = 5,00,000 × 36% = ₹1,80,000। नया मूलधन ₹6,80,000 पर 45% = ₹3,06,000 ब्याज देता है। कुल ब्याज = 1,80,000 + 3,06,000 = ₹4,86,000।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-121","question":"A finance company lends ₹1,20,000 for one year at a 'flat' 10% interest, repaid in 12 equal monthly instalments. Taking interest on the average principal actually outstanding during the year, the true rate is approximately:","options":["10%","20%","18.5%","12%"],"answer":2,"explanation":"Principal outstanding falls from 1,20,000 to 10,000 in steps of 10,000, averaging ₹65,000. Interest ₹12,000 on ₹65,000 ≈ 18.5%, nearly double the flat rate.","difficulty":"very-hard","source":"IBPS PO Mains · RBI Grade B","questionHi":"एक वित्त कंपनी ₹1,20,000 एक वर्ष के लिए 'फ्लैट' 10% ब्याज पर उधार देती है, जिसे 12 समान मासिक किस्तों में चुकाया जाता है। वर्ष के दौरान वास्तव में बकाया औसत मूलधन पर ब्याज लेने पर, वास्तविक दर लगभग है:","optionsHi":["10%","20%","18.5%","12%"],"explanationHi":"बकाया मूलधन ₹10,000 के चरणों में 1,20,000 से घटकर 10,000 तक आता है, जिसका औसत ₹65,000 है। ₹65,000 पर ₹12,000 ब्याज ≈ 18.5%, जो फ्लैट दर से लगभग दोगुना है।","subtopic":"instalments"},
  {"id":"quant-simple-interest-122","question":"Ram invests ₹P for 2 years at r% simple interest. Shyam invests ₹2P for 3 years at (r − 2)%. Shyam's interest is 1.5 times Ram's. What is r?","options":["6","4","8","3"],"answer":1,"explanation":"Shyam: 2P × 3 × (r − 2) = 6P(r − 2); Ram: 2Pr. So 6(r − 2) = 1.5 × 2r = 3r, giving r = 4.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"राम ₹P को 2 वर्ष के लिए r% साधारण ब्याज पर निवेश करता है। श्याम ₹2P को 3 वर्ष के लिए (r − 2)% पर निवेश करता है। श्याम का ब्याज राम के ब्याज का 1.5 गुना है। r क्या है?","optionsHi":["6","4","8","3"],"explanationHi":"श्याम: 2P × 3 × (r − 2) = 6P(r − 2); राम: 2Pr। अतः 6(r − 2) = 1.5 × 2r = 3r, जिससे r = 4।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-123","question":"₹20,000 is borrowed at 10% simple interest. ₹8,000 is repaid at the end of 2 years, and that payment is credited with simple interest at the same rate till settlement. How much must be paid at the end of 4 years to clear the loan?","options":["₹18,400","₹20,000","₹17,600","₹19,200"],"answer":0,"explanation":"The loan grows to 20,000 × 1.4 = ₹28,000. The payment grows to 8,000 × 1.2 = ₹9,600 by then. Balance = ₹18,400.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"₹20,000 को 10% साधारण ब्याज पर उधार लिया गया। 2 वर्ष के अंत में ₹8,000 चुकाए जाते हैं, और उस भुगतान पर निपटारे तक उसी दर से साधारण ब्याज जमा किया जाता है। ऋण चुकता करने के लिए 4 वर्ष के अंत में कितना देना होगा?","optionsHi":["₹18,400","₹20,000","₹17,600","₹19,200"],"explanationHi":"ऋण बढ़कर 20,000 × 1.4 = ₹28,000 हो जाता है। भुगतान तब तक 8,000 × 1.2 = ₹9,600 हो जाता है। शेष = ₹18,400।","subtopic":"instalments"},
  {"id":"quant-simple-interest-124","question":"₹P is lent at 5% and ₹(P + 1,000) at 4% simple interest, both for the same period. If both earn the same interest, what is P?","options":["₹5,000","₹3,000","₹4,500","₹4,000"],"answer":3,"explanation":"5P × t = 4(P + 1,000) × t; the time cancels, so P = 4,000 for any period.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"₹P को 5% पर और ₹(P + 1,000) को 4% साधारण ब्याज पर, दोनों को समान अवधि के लिए उधार दिया गया है। यदि दोनों समान ब्याज अर्जित करते हैं, तो P क्या है?","optionsHi":["₹5,000","₹3,000","₹4,500","₹4,000"],"explanationHi":"5P × t = 4(P + 1,000) × t; समय कट जाता है, इसलिए किसी भी अवधि के लिए P = 4,000।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-125","question":"The simple interest on ₹P at r% for t years is ₹1,800. What is the simple interest on ₹1.5P at (r/3)% for 2t years?","options":["₹2,700","₹1,200","₹3,600","₹1,800"],"answer":3,"explanation":"SI scales as P × R × T: 1.5 × 1/3 × 2 = 1. The interest is unchanged at ₹1,800.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"₹P पर r% से t वर्ष का साधारण ब्याज ₹1,800 है। ₹1.5P पर (r/3)% से 2t वर्ष का साधारण ब्याज क्या है?","optionsHi":["₹2,700","₹1,200","₹3,600","₹1,800"],"explanationHi":"SI, P × R × T के अनुसार बदलता है: 1.5 × 1/3 × 2 = 1। ब्याज ₹1,800 ही रहता है।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-126","question":"The simple interest on ₹6,000 at x% per annum for x months is ₹320. What is x?","options":["6","12","8","10"],"answer":2,"explanation":"SI = 6,000 × x/100 × x/12 = 5x². So 5x² = 320, x² = 64 and x = 8.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"₹6,000 पर x% वार्षिक दर से x महीने का साधारण ब्याज ₹320 है। x क्या है?","optionsHi":["6","12","8","10"],"explanationHi":"SI = 6,000 × x/100 × x/12 = 5x²। अतः 5x² = 320, x² = 64 और x = 8।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-127","question":"A sum triples in 15 years at simple interest. After 10 years, what percentage of the amount is interest?","options":["66.67%","57.14%","133.33%","42.86%"],"answer":1,"explanation":"Interest of 200% in 15 years means 13⅓% a year, so in 10 years it is 133⅓% of P. Amount = 233⅓%. Share = 133⅓/233⅓ = 4/7 ≈ 57.14%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"साधारण ब्याज पर कोई धनराशि 15 वर्ष में तीन गुनी हो जाती है। 10 वर्ष बाद मिश्रधन का कितना प्रतिशत ब्याज है?","optionsHi":["66.67%","57.14%","133.33%","42.86%"],"explanationHi":"15 वर्ष में 200% ब्याज का अर्थ है प्रति वर्ष 13⅓%, इसलिए 10 वर्ष में यह P का 133⅓% है। मिश्रधन = 233⅓%। हिस्सा = 133⅓/233⅓ = 4/7 ≈ 57.14%।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-128","question":"The simple interest on a sum for the 4th year alone is ₹480, and the amount after 6 years is ₹8,880. What is the rate per annum?","options":["8%","5.4%","10%","6%"],"answer":0,"explanation":"Simple interest is the same every year, so 6 years' interest = ₹2,880 and P = 8,880 − 2,880 = ₹6,000. Rate = 480/6,000 = 8%.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"किसी धनराशि पर केवल चौथे वर्ष का साधारण ब्याज ₹480 है, और 6 वर्ष बाद मिश्रधन ₹8,880 है। वार्षिक दर क्या है?","optionsHi":["8%","5.4%","10%","6%"],"explanationHi":"साधारण ब्याज हर वर्ष समान होता है, इसलिए 6 वर्ष का ब्याज = ₹2,880 और P = 8,880 − 2,880 = ₹6,000। दर = 480/6,000 = 8%।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-129","question":"A deposit scheme pays 9% simple interest in the first year, and the rate falls by 0.5 percentage points each year after that. Over 4 years the interest is ₹9,900. What was the deposit?","options":["₹30,000","₹27,500","₹33,000","₹36,000"],"answer":0,"explanation":"Total rate = 9 + 8.5 + 8 + 7.5 = 33%. Deposit = 9,900 ÷ 0.33 = ₹30,000.","difficulty":"very-hard","source":"IBPS Clerk · SBI PO","questionHi":"एक जमा योजना पहले वर्ष में 9% साधारण ब्याज देती है, और उसके बाद हर वर्ष दर 0.5 प्रतिशत अंक घटती है। 4 वर्ष में ब्याज ₹9,900 है। जमा राशि क्या थी?","optionsHi":["₹30,000","₹27,500","₹33,000","₹36,000"],"explanationHi":"कुल दर = 9 + 8.5 + 8 + 7.5 = 33%। जमा राशि = 9,900 ÷ 0.33 = ₹30,000।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-130","question":"Bank A pays 7% simple interest a year. Bank B pays 7.5% but charges a fee of ₹250 a year. Bank B gives more net interest only for deposits above:","options":["₹25,000","₹35,714","₹5,00,000","₹50,000"],"answer":3,"explanation":"Bank B's extra 0.5% must beat ₹250: 0.005 × P > 250 means P > ₹50,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"बैंक A प्रति वर्ष 7% साधारण ब्याज देता है। बैंक B 7.5% देता है लेकिन प्रति वर्ष ₹250 शुल्क लेता है। बैंक B शुद्ध ब्याज अधिक तभी देता है जब जमा राशि इससे अधिक हो:","optionsHi":["₹25,000","₹35,714","₹5,00,000","₹50,000"],"explanationHi":"बैंक B के अतिरिक्त 0.5% को ₹250 से अधिक होना चाहिए: 0.005 × P > 250 का अर्थ है P > ₹50,000।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-131","question":"A sum grows to 1.32 times itself in 4 years at simple interest. The rate is then raised by 2 percentage points. How many more years will it take for the amount to reach 1.8 times the original sum?","options":["6 years","4 years","4.8 years","5 years"],"answer":2,"explanation":"The rate is 32/4 = 8%, now 10%. The remaining 48% of P needs 48/10 = 4.8 years.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"साधारण ब्याज पर कोई धनराशि 4 वर्ष में स्वयं की 1.32 गुनी हो जाती है। फिर दर 2 प्रतिशत अंक बढ़ा दी जाती है। मिश्रधन को मूल धनराशि का 1.8 गुना होने में कितने वर्ष और लगेंगे?","optionsHi":["6 वर्ष","4 वर्ष","4.8 वर्ष","5 वर्ष"],"explanationHi":"दर 32/4 = 8% है, जो अब 10% है। शेष P का 48% पाने में 48/10 = 4.8 वर्ष लगेंगे।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-132","question":"₹8,000 is lent at 5% simple interest for 3 years, and the whole amount is then lent at 10% simple interest for 2 more years. What is the final amount?","options":["₹11,040","₹10,800","₹11,200","₹10,400"],"answer":0,"explanation":"After 3 years: 8,000 × 1.15 = ₹9,200. Then 20% more: 9,200 × 1.2 = ₹11,040.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"₹8,000 को 3 वर्ष के लिए 5% साधारण ब्याज पर उधार दिया जाता है, और फिर पूरा मिश्रधन 2 वर्ष और 10% साधारण ब्याज पर उधार दिया जाता है। अंतिम मिश्रधन क्या है?","optionsHi":["₹11,040","₹10,800","₹11,200","₹10,400"],"explanationHi":"3 वर्ष बाद: 8,000 × 1.15 = ₹9,200। फिर 20% और: 9,200 × 1.2 = ₹11,040।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-133","question":"What is the simple interest on ₹4,500 for 146 days at 10% per annum (365-day year)?","options":["₹146","₹450","₹200","₹180"],"answer":3,"explanation":"146/365 = 2/5 year, so SI = 4,500 × 10% × 2/5 = ₹180. ₹450 is a full year's interest, and ₹146 just copies the number of days.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk","questionHi":"₹4,500 पर 10% वार्षिक दर से 146 दिन का साधारण ब्याज क्या है (वर्ष में 365 दिन)?","optionsHi":["₹146","₹450","₹200","₹180"],"explanationHi":"146/365 = 2/5 वर्ष, अतः SI = 4,500 × 10% × 2/5 = ₹180। ₹450 पूरे वर्ष का ब्याज है, और ₹146 में बस दिनों की संख्या ही उतार दी गई है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-134","question":"A sum doubles in 8 years at simple interest. After 6 years, what percentage of the amount is interest?","options":["75%","37.5%","42.86%","50%"],"answer":2,"explanation":"The rate is 12.5%, so 6 years give 75% of the sum. Amount = 175%, and 75/175 ≈ 42.86%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"साधारण ब्याज पर कोई धनराशि 8 वर्ष में दोगुनी हो जाती है। 6 वर्ष बाद मिश्रधन का कितना प्रतिशत ब्याज है?","optionsHi":["75%","37.5%","42.86%","50%"],"explanationHi":"दर 12.5% है, इसलिए 6 वर्ष में धनराशि का 75% ब्याज मिलता है। मिश्रधन = 175%, और 75/175 ≈ 42.86%।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-135","question":"The simple interest on ₹x for 9 months at 8% equals the simple interest on ₹(x + 1,000) for 6 months at 10%. What is x?","options":["₹4,000","₹5,000","₹6,000","₹2,500"],"answer":1,"explanation":"9 months at 8% = 6%; 6 months at 10% = 5%. 6x = 5(x + 1,000) gives x = ₹5,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"₹x पर 8% से 9 महीने का साधारण ब्याज, ₹(x + 1,000) पर 10% से 6 महीने के साधारण ब्याज के बराबर है। x क्या है?","optionsHi":["₹4,000","₹5,000","₹6,000","₹2,500"],"explanationHi":"8% पर 9 महीने = 6%; 10% पर 6 महीने = 5%। 6x = 5(x + 1,000) से x = ₹5,000।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-136","question":"A sum is lent at simple interest for 4 years. If the period were 6 months longer and the rate 1 percentage point lower, the interest would be the same. What is the rate?","options":["8%","9%","10%","4.5%"],"answer":1,"explanation":"Equal interest means 4r = 4.5(r − 1), so 0.5r = 4.5 and r = 9%. 4.5% confuses the new period with the rate, and 8% fails the check (32 vs 31.5).","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"कोई धनराशि साधारण ब्याज पर 4 वर्ष के लिए उधार दी गई है। यदि अवधि 6 महीने अधिक और दर 1 प्रतिशत अंक कम होती, तो ब्याज वही रहता। दर क्या है?","optionsHi":["8%","9%","10%","4.5%"],"explanationHi":"समान ब्याज का अर्थ है 4r = 4.5(r − 1), अतः 0.5r = 4.5 और r = 9%। 4.5% में नई अवधि को दर समझ लिया गया है, और 8% जाँच में विफल होता है (32 बनाम 31.5)।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-137","question":"A invests ₹x at 9% and B invests ₹x at 6% simple interest. After 5 years A has earned ₹1,800 more than B. What is x?","options":["₹12,000","₹6,000","₹36,000","₹8,000"],"answer":0,"explanation":"The extra 3% a year for 5 years = 15% of x = ₹1,800, so x = ₹12,000.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk","questionHi":"A ₹x को 9% पर और B ₹x को 6% साधारण ब्याज पर निवेश करता है। 5 वर्ष बाद A ने B से ₹1,800 अधिक कमाए हैं। x क्या है?","optionsHi":["₹12,000","₹6,000","₹36,000","₹8,000"],"explanationHi":"5 वर्ष के लिए प्रति वर्ष अतिरिक्त 3% = x का 15% = ₹1,800, अतः x = ₹12,000।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-138","question":"The simple interest on ₹3,000 at r% for 4 years plus the simple interest on ₹2,000 at (r + 2)% for 3 years is ₹1,560. What is r?","options":["8.67","7.33","8.24","8"],"answer":3,"explanation":"120r + 60(r + 2) = 1,560 gives 180r = 1,440, so r = 8. 8.67 forgets the +2%, 7.33 attaches the +2% to the ₹3,000 loan, and 8.24 swaps the periods of the two loans.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"₹3,000 पर r% से 4 वर्ष का साधारण ब्याज और ₹2,000 पर (r + 2)% से 3 वर्ष का साधारण ब्याज मिलाकर ₹1,560 है। r क्या है?","optionsHi":["8.67","7.33","8.24","8"],"explanationHi":"120r + 60(r + 2) = 1,560 से 180r = 1,440, अतः r = 8। 8.67 में +2% भूल गए हैं, 7.33 में +2% ₹3,000 वाले ऋण पर लगा दिया गया है, और 8.24 में दोनों ऋणों की अवधियाँ आपस में बदल दी गई हैं।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-139","question":"₹1 lakh earns 8% simple interest a year. Each year-end interest is moved at once to a second scheme paying 10% simple interest. What is the total value of both schemes at the end of 3 years?","options":["₹1,24,000","₹1,27,200","₹1,26,400","₹1,25,600"],"answer":2,"explanation":"The three ₹8,000 instalments earn 10% for 2, 1 and 0 years: 9,600 + 8,800 + 8,000 = ₹26,400. Add the ₹1,00,000 principal.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"₹1 लाख पर प्रति वर्ष 8% साधारण ब्याज मिलता है। हर वर्ष के अंत में मिला ब्याज तुरंत 10% साधारण ब्याज देने वाली दूसरी योजना में डाल दिया जाता है। 3 वर्ष के अंत में दोनों योजनाओं का कुल मूल्य क्या है?","optionsHi":["₹1,24,000","₹1,27,200","₹1,26,400","₹1,25,600"],"explanationHi":"₹8,000 की तीनों किस्तें क्रमशः 2, 1 और 0 वर्ष तक 10% अर्जित करती हैं: 9,600 + 8,800 + 8,000 = ₹26,400। इसमें ₹1,00,000 मूलधन जोड़ें।","subtopic":"instalments"},
  {"id":"quant-simple-interest-140","question":"₹2,500 earns ₹75 simple interest in 3 months. What is the annual rate?","options":["3%","9%","12%","10%"],"answer":2,"explanation":"3 months is a quarter of a year, so yearly interest = 75 × 4 = ₹300, which is 300/2,500 = 12%. 3% is the rate for the quarter only, and 9% multiplies by 3 months instead of annualising.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"₹2,500 पर 3 महीने में ₹75 साधारण ब्याज मिलता है। वार्षिक दर क्या है?","optionsHi":["3%","9%","12%","10%"],"explanationHi":"3 महीने एक वर्ष का चौथाई भाग है, इसलिए वार्षिक ब्याज = 75 × 4 = ₹300, जो 300/2,500 = 12% है। 3% केवल तिमाही की दर है, और 9% में वार्षिक करने की जगह 3 महीने से गुणा कर दिया गया है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-141","question":"What is the simple interest on ₹25,000 at 6% per annum for 1 year 3 months?","options":["₹1,500","₹1,875","₹1,950","₹2,250"],"answer":1,"explanation":"1 year 3 months = 1.25 years. SI = 25,000 × 6% × 1.25 = ₹1,875.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk","questionHi":"₹25,000 पर 6% वार्षिक दर से 1 वर्ष 3 महीने का साधारण ब्याज क्या है?","optionsHi":["₹1,500","₹1,875","₹1,950","₹2,250"],"explanationHi":"1 वर्ष 3 महीने = 1.25 वर्ष। SI = 25,000 × 6% × 1.25 = ₹1,875।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-142","question":"The simple interest on a sum is one-fourth of the sum, and the rate per annum is four times the number of years. What is the rate?","options":["10%","5%","8%","12.5%"],"answer":0,"explanation":"r × t = 25 and r = 4t, so 4t² = 25, t = 2.5 years and r = 10%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"किसी धनराशि पर साधारण ब्याज उस धनराशि का एक-चौथाई है, और वार्षिक दर वर्षों की संख्या की चार गुनी है। दर क्या है?","optionsHi":["10%","5%","8%","12.5%"],"explanationHi":"r × t = 25 और r = 4t, अतः 4t² = 25, t = 2.5 वर्ष और r = 10%।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-143","question":"A moneylender charges 15% simple interest a year but counts any part of a month as a full month. How much interest does he charge on ₹10,000 borrowed for 2 months and 10 days?","options":["₹292","₹250","₹300","₹375"],"answer":3,"explanation":"2 months 10 days is charged as 3 months = 1/4 year. Interest = 10,000 × 15% × 1/4 = ₹375.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"एक साहूकार 15% वार्षिक साधारण ब्याज लेता है लेकिन महीने के किसी भी हिस्से को पूरा महीना गिनता है। ₹10,000 को 2 महीने 10 दिन के लिए उधार लेने पर वह कितना ब्याज लेगा?","optionsHi":["₹292","₹250","₹300","₹375"],"explanationHi":"2 महीने 10 दिन को 3 महीने = 1/4 वर्ष गिना जाता है। ब्याज = 10,000 × 15% × 1/4 = ₹375।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-144","question":"A sum doubles itself in 8 years at simple interest. In how many years will it become 3½ times itself?","options":["28 years","20 years","24 years","12 years"],"answer":1,"explanation":"Doubling means 100% interest in 8 years, so 12.5% a year. 3½ times needs 250% interest: 250/12.5 = 20 years. Scaling 8 years by 3.5 (28) forgets that only the interest part grows.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"साधारण ब्याज पर कोई धनराशि 8 वर्ष में स्वयं की दोगुनी हो जाती है। वह कितने वर्षों में स्वयं की 3½ गुनी हो जाएगी?","optionsHi":["28 वर्ष","20 वर्ष","24 वर्ष","12 वर्ष"],"explanationHi":"दोगुना होने का अर्थ है 8 वर्ष में 100% ब्याज, यानी 12.5% प्रति वर्ष। 3½ गुना होने के लिए 250% ब्याज चाहिए: 250/12.5 = 20 वर्ष। 8 वर्ष को 3.5 से गुणा करने (28) में यह भूल गए हैं कि केवल ब्याज वाला भाग बढ़ता है।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-145","question":"A debt of ₹6,450 due at the end of 4 years is to be paid in 4 equal annual instalments, the first one year from now, with simple interest at 5% per annum. What is each instalment?","options":["₹1,612.50","₹1,433.33","₹1,535.71","₹1,500"],"answer":3,"explanation":"Each instalment earns SI until the due date: x(1.15 + 1.10 + 1.05 + 1) = 4.3x = 6,450, so x = ₹1,500. Dividing 6,450 by 4 ignores the interest the early payments earn.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"4 वर्ष के अंत में देय ₹6,450 के ऋण को 5% वार्षिक साधारण ब्याज के साथ 4 समान वार्षिक किस्तों में चुकाना है, पहली किस्त अब से एक वर्ष बाद। प्रत्येक किस्त क्या है?","optionsHi":["₹1,612.50","₹1,433.33","₹1,535.71","₹1,500"],"explanationHi":"प्रत्येक किस्त पर देय तिथि तक SI लगता है: x(1.15 + 1.10 + 1.05 + 1) = 4.3x = 6,450, अतः x = ₹1,500। 6,450 को 4 से भाग देने में पहले दी गई किस्तों पर लगने वाला ब्याज छूट गया है।","subtopic":"instalments"},
  {"id":"quant-simple-interest-146","question":"₹32,500 is split into three parts lent at 4%, 6% and 8% simple interest so that each part earns the same yearly interest. How much is lent at 4%?","options":["₹7,500","₹15,000","₹10,833.33","₹10,000"],"answer":1,"explanation":"Equal interest means parts ∝ 1/4 : 1/6 : 1/8 = 6 : 4 : 3, so the 4% part is 32,500 × 6/13 = ₹15,000. Reversing the ratio to 3 : 4 : 6 wrongly gives the 4% part ₹7,500.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹32,500 को तीन भागों में बाँटकर 4%, 6% और 8% साधारण ब्याज पर उधार दिया गया है ताकि प्रत्येक भाग से वार्षिक ब्याज समान मिले। 4% पर कितना उधार दिया गया है?","optionsHi":["₹7,500","₹15,000","₹10,833.33","₹10,000"],"explanationHi":"समान ब्याज का अर्थ है भाग ∝ 1/4 : 1/6 : 1/8 = 6 : 4 : 3, इसलिए 4% वाला भाग 32,500 × 6/13 = ₹15,000 है। अनुपात उलटकर 3 : 4 : 6 लेने पर गलती से 4% वाला भाग ₹7,500 आता है।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-147","question":"Simple interest is charged at 6% p.a. for the first 2 years, 9% p.a. for the next 3 years and 14% p.a. after that. If the total interest at the end of 8 years is ₹12,150, what was the sum?","options":["₹12,789.47","₹15,000","₹15,711.21","₹16,875"],"answer":1,"explanation":"Rate-years: 6×2 + 9×3 + 14×3 = 81%, so P = 12,150/0.81 = ₹15,000. Giving the 14% rate 4 years (95%) gives ₹12,789.47; using the plain average rate for 8 years gives ₹15,711.21.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"साधारण ब्याज पहले 2 वर्ष के लिए 6% प्रति वर्ष, अगले 3 वर्ष के लिए 9% प्रति वर्ष और उसके बाद 14% प्रति वर्ष की दर से लगता है। यदि 8 वर्ष के अंत में कुल ब्याज ₹12,150 है, तो धनराशि क्या थी?","optionsHi":["₹12,789.47","₹15,000","₹15,711.21","₹16,875"],"explanationHi":"दर-वर्ष: 6×2 + 9×3 + 14×3 = 81%, अतः P = 12,150/0.81 = ₹15,000। 14% दर को 4 वर्ष देने (95%) पर ₹12,789.47 आता है; 8 वर्ष के लिए साधारण औसत दर लेने पर ₹15,711.21 आता है।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-148","question":"A man borrows ₹50,000 at 8% per annum simple interest and immediately lends it at 10% per annum compounded annually. What is his gain at the end of 2 years?","options":["₹2,000","₹500","₹10,500","₹2,500"],"answer":3,"explanation":"He earns 50,000 × 0.21 = ₹10,500 and pays 50,000 × 0.16 = ₹8,000, so he gains ₹2,500. ₹2,000 treats both sides as simple interest; ₹500 is only the compounding extra.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक व्यक्ति ₹50,000 को 8% वार्षिक साधारण ब्याज पर उधार लेता है और तुरंत उसे 10% वार्षिक चक्रवृद्धि ब्याज (वार्षिक संयोजन) पर उधार दे देता है। 2 वर्ष के अंत में उसका लाभ क्या है?","optionsHi":["₹2,000","₹500","₹10,500","₹2,500"],"explanationHi":"वह 50,000 × 0.21 = ₹10,500 कमाता है और 50,000 × 0.16 = ₹8,000 चुकाता है, इसलिए उसका लाभ ₹2,500 है। ₹2,000 में दोनों ओर साधारण ब्याज मान लिया गया है; ₹500 केवल चक्रवृद्धि का अतिरिक्त भाग है।","subtopic":"lending-borrowing"},
  {"id":"quant-simple-interest-149","question":"The simple interest on a sum for 5 years equals the interest on the same sum for 4 years at a rate 3% higher. What is the original rate?","options":["15%","12%","3%","9%"],"answer":1,"explanation":"5r = 4(r + 3) gives r = 12%. 15% is the higher rate; writing 5r = 4r + 3 (forgetting to multiply the 3 by 4) gives 3%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"किसी धनराशि पर 5 वर्ष का साधारण ब्याज, उसी धनराशि पर 3% अधिक दर से 4 वर्ष के ब्याज के बराबर है। मूल दर क्या है?","optionsHi":["15%","12%","3%","9%"],"explanationHi":"5r = 4(r + 3) से r = 12%। 15% ऊँची दर है; 5r = 4r + 3 लिखने (3 को 4 से गुणा करना भूलने) पर 3% आता है।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-150","question":"At simple interest a sum amounts to ₹10,400 in 3 years and to ₹13,600 in 7 years. What is the rate of interest?","options":["7.69%","5.88%","10%","40%"],"answer":2,"explanation":"Four years' interest = 3,200, so 800 a year and P = 10,400 − 2,400 = 8,000: rate = 800/8,000 = 10%. Dividing 800 by an amount (10,400 or 13,600) instead of the principal gives 7.69% or 5.88%.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"साधारण ब्याज पर कोई धनराशि 3 वर्ष में ₹10,400 और 7 वर्ष में ₹13,600 हो जाती है। ब्याज की दर क्या है?","optionsHi":["7.69%","5.88%","10%","40%"],"explanationHi":"चार वर्ष का ब्याज = 3,200, अतः प्रति वर्ष 800 और P = 10,400 − 2,400 = 8,000: दर = 800/8,000 = 10%। 800 को मूलधन की जगह किसी मिश्रधन (10,400 या 13,600) से भाग देने पर 7.69% या 5.88% आता है।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-151","question":"What is the simple interest on ₹7,300 at 10% per annum from 12 January to 26 March of a non-leap year? (Count the day of deposit out and the day of withdrawal in.)","options":["₹148","₹152.08","₹146","₹144"],"answer":2,"explanation":"Days: 19 (January) + 28 + 26 = 73, i.e. 1/5 of a year, so SI = 7,300 × 10% × 1/5 = ₹146. Counting both end days (74) gives ₹148; treating the period as 2½ months gives ₹152.08.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"गैर-अधिवर्ष में 12 जनवरी से 26 मार्च तक ₹7,300 पर 10% वार्षिक दर से साधारण ब्याज क्या है? (जमा के दिन को न गिनें और निकासी के दिन को गिनें।)","optionsHi":["₹148","₹152.08","₹146","₹144"],"explanationHi":"दिन: 19 (जनवरी) + 28 + 26 = 73, यानी वर्ष का 1/5, अतः SI = 7,300 × 10% × 1/5 = ₹146। दोनों सिरों के दिन गिनने (74) पर ₹148 आता है; अवधि को 2½ महीने मानने पर ₹152.08 आता है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-152","question":"₹15,000 is lent partly at 8% and partly at 12% simple interest. The total interest after 3 years is ₹4,860. In what ratio was the money divided between the 8% and 12% loans?","options":["3 : 7","7 : 3","1 : 1","2 : 3"],"answer":0,"explanation":"Average rate = 4,860/(15,000 × 3) = 10.8%. Alligation: 8% part : 12% part = (12 − 10.8) : (10.8 − 8) = 1.2 : 2.8 = 3 : 7. 7 : 3 reverses the alligation; 2 : 3 is just the ratio of the rates.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹15,000 को आंशिक रूप से 8% और आंशिक रूप से 12% साधारण ब्याज पर उधार दिया गया है। 3 वर्ष बाद कुल ब्याज ₹4,860 है। 8% और 12% वाले ऋणों में राशि किस अनुपात में बाँटी गई थी?","optionsHi":["3 : 7","7 : 3","1 : 1","2 : 3"],"explanationHi":"औसत दर = 4,860/(15,000 × 3) = 10.8%। एलिगेशन विधि से: 8% वाला भाग : 12% वाला भाग = (12 − 10.8) : (10.8 − 8) = 1.2 : 2.8 = 3 : 7। 7 : 3 में एलिगेशन उलट गया है; 2 : 3 केवल दरों का अनुपात है।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-153","question":"A man deposits ₹20,000 at simple interest. After 2 years he adds ₹10,000 more at the same rate. The total interest at the end of 5 years from the start is ₹10,400. What is the rate?","options":["6.93%","10.4%","8%","8.67%"],"answer":2,"explanation":"Interest = r(20,000×5 + 10,000×3)/100 = 1,300r = 10,400, so r = 8%. Treating all ₹30,000 as invested for 5 years gives 6.93%; ignoring the extra deposit gives 10.4%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक व्यक्ति साधारण ब्याज पर ₹20,000 जमा करता है। 2 वर्ष बाद वह उसी दर पर ₹10,000 और जमा करता है। शुरू से 5 वर्ष के अंत में कुल ब्याज ₹10,400 है। दर क्या है?","optionsHi":["6.93%","10.4%","8%","8.67%"],"explanationHi":"ब्याज = r(20,000×5 + 10,000×3)/100 = 1,300r = 10,400, अतः r = 8%। पूरे ₹30,000 को 5 वर्ष के लिए निवेशित मानने पर 6.93% आता है; अतिरिक्त जमा को नज़रअंदाज़ करने पर 10.4% आता है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-154","question":"Two equal sums are lent, one at 8% for 3 years and the other at 6% for 3½ years, both at simple interest. The first earns ₹270 more than the second. What is the total of the two sums?","options":["₹18,000","₹9,000","₹13,500","₹27,000"],"answer":0,"explanation":"Interest difference = P(24% − 21%) = 3% of P = 270, so P = 9,000 and the total is ₹18,000. ₹9,000 is only one sum; using only the rate gap (2%) gives ₹13,500.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"दो बराबर धनराशियाँ उधार दी गई हैं, एक 8% पर 3 वर्ष के लिए और दूसरी 6% पर 3½ वर्ष के लिए, दोनों साधारण ब्याज पर। पहली दूसरी से ₹270 अधिक अर्जित करती है। दोनों धनराशियों का कुल योग क्या है?","optionsHi":["₹18,000","₹9,000","₹13,500","₹27,000"],"explanationHi":"ब्याज का अंतर = P(24% − 21%) = P का 3% = 270, अतः P = 9,000 और कुल ₹18,000 है। ₹9,000 केवल एक धनराशि है; केवल दरों का अंतर (2%) लेने पर ₹13,500 आता है।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-155","question":"Divide ₹8,620 into three parts so that, lent at 10% simple interest, they amount to the same sum after 1, 2 and 3 years respectively. What is the first part?","options":["₹2,640","₹2,873.33","₹2,860","₹3,120"],"answer":3,"explanation":"Parts ∝ 1/1.1 : 1/1.2 : 1/1.3 = 1/11 : 1/12 : 1/13 = 156 : 143 : 132 (total 431), so the first part is 8,620 × 156/431 = ₹3,120. ₹2,640 is the part lent for 3 years.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"₹8,620 को तीन भागों में इस प्रकार बाँटिए कि 10% साधारण ब्याज पर उधार देने पर वे क्रमशः 1, 2 और 3 वर्ष बाद समान मिश्रधन बन जाएँ। पहला भाग क्या है?","optionsHi":["₹2,640","₹2,873.33","₹2,860","₹3,120"],"explanationHi":"भाग ∝ 1/1.1 : 1/1.2 : 1/1.3 = 1/11 : 1/12 : 1/13 = 156 : 143 : 132 (कुल 431), अतः पहला भाग = 8,620 × 156/431 = ₹3,120। ₹2,640 वह भाग है जो 3 वर्ष के लिए उधार दिया गया।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-156","question":"In how many years will ₹4,000 at 7.5% simple interest earn as much interest as ₹6,000 earns in 4 years at 6%?","options":["4.8 years","2.13 years","7.5 years","4 years"],"answer":0,"explanation":"₹6,000 earns 6,000 × 0.06 × 4 = ₹1,440; ₹4,000 at 7.5% earns ₹300 a year, so it takes 1,440/300 = 4.8 years. Swapping the two principals gives 2.13 years; swapping the rates gives 7.5.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"7.5% साधारण ब्याज पर ₹4,000 कितने वर्षों में उतना ब्याज अर्जित करेंगे जितना ₹6,000, 6% पर 4 वर्ष में अर्जित करते हैं?","optionsHi":["4.8 वर्ष","2.13 वर्ष","7.5 वर्ष","4 वर्ष"],"explanationHi":"₹6,000 अर्जित करते हैं 6,000 × 0.06 × 4 = ₹1,440; 7.5% पर ₹4,000 प्रति वर्ष ₹300 अर्जित करते हैं, इसलिए 1,440/300 = 4.8 वर्ष लगते हैं। दोनों मूलधन आपस में बदलने पर 2.13 वर्ष आता है; दरें आपस में बदलने पर 7.5 आता है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-157","question":"The simple interest on a sum is 9/16 of the sum, and the rate per cent per annum equals the number of years. What is the rate?","options":["7.5%","56.25%","0.75%","75%"],"answer":0,"explanation":"r × r/100 = 9/16 gives r² = 56.25, so r = 7.5% (for 7.5 years). 56.25% is r² itself; 0.75% comes from taking √(9/16) without the factor 100.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"किसी धनराशि पर साधारण ब्याज उस धनराशि का 9/16 है, और प्रतिशत वार्षिक दर वर्षों की संख्या के बराबर है। दर क्या है?","optionsHi":["7.5%","56.25%","0.75%","75%"],"explanationHi":"r × r/100 = 9/16 से r² = 56.25, अतः r = 7.5% (7.5 वर्ष के लिए)। 56.25% स्वयं r² है; 0.75% 100 के गुणक के बिना √(9/16) लेने से आता है।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-158","question":"₹10,000 is lent in two parts: one at 8% simple interest for 2 years and the other at 6% for 4 years. Both parts earn the same interest. How much is lent at 8%?","options":["₹4,000","₹4,285.71","₹6,000","₹5,714.29"],"answer":2,"explanation":"16% of x = 24% of (10,000 − x) gives 40x = 2,40,000, so x = ₹6,000. Equating yearly interest only (8x = 6(10,000 − x)) ignores the different periods and gives ₹4,285.71.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹10,000 को दो भागों में उधार दिया गया है: एक 8% साधारण ब्याज पर 2 वर्ष के लिए और दूसरा 6% पर 4 वर्ष के लिए। दोनों भाग समान ब्याज अर्जित करते हैं। 8% पर कितना उधार दिया गया है?","optionsHi":["₹4,000","₹4,285.71","₹6,000","₹5,714.29"],"explanationHi":"x का 16% = (10,000 − x) का 24% से 40x = 2,40,000, अतः x = ₹6,000। केवल वार्षिक ब्याज को बराबर करने (8x = 6(10,000 − x)) में अलग-अलग अवधियाँ नज़रअंदाज़ हो जाती हैं और ₹4,285.71 आता है।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-159","question":"The ratio of a principal to its amount after 1 year at simple interest is 8 : 9. What is the ratio of the principal to the amount after 4 years at the same rate?","options":["4096 : 6561","2 : 1","2 : 3","8 : 9"],"answer":2,"explanation":"Interest is 1/8 of P a year (12.5%), so after 4 years the amount is 8 + 4 = 12 parts: 8 : 12 = 2 : 3. 2 : 1 is principal to interest, not to amount; raising 8 : 9 to the fourth power (4096 : 6561) would be compound interest.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"साधारण ब्याज पर किसी मूलधन और 1 वर्ष बाद उसके मिश्रधन का अनुपात 8 : 9 है। उसी दर से 4 वर्ष बाद मूलधन और मिश्रधन का अनुपात क्या है?","optionsHi":["4096 : 6561","2 : 1","2 : 3","8 : 9"],"explanationHi":"ब्याज प्रति वर्ष P का 1/8 (12.5%) है, इसलिए 4 वर्ष बाद मिश्रधन 8 + 4 = 12 भाग है: 8 : 12 = 2 : 3। 2 : 1 मूलधन और ब्याज का अनुपात है, मिश्रधन का नहीं; 8 : 9 की चौथी घात (4096 : 6561) चक्रवृद्धि ब्याज होता।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-160","question":"Of ₹1,00,000, 30% is invested at 6%, 45% at 7% and the rest at r%, all at simple interest. The total interest in 2 years is ₹14,000. What is r?","options":["8%","16.4%","4.1%","8.2%"],"answer":3,"explanation":"Yearly interest = 7,000 = 1,800 + 3,150 + 250r, so r = 8.2%. 16.4% forgets that the ₹4,100 left for the r% part is two years' interest; 4.1% takes the remaining part as ₹50,000.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹1,00,000 में से 30% को 6% पर, 45% को 7% पर और शेष को r% पर निवेश किया गया है, सभी साधारण ब्याज पर। 2 वर्ष में कुल ब्याज ₹14,000 है। r क्या है?","optionsHi":["8%","16.4%","4.1%","8.2%"],"explanationHi":"वार्षिक ब्याज = 7,000 = 1,800 + 3,150 + 250r, अतः r = 8.2%। 16.4% में यह भूल गए हैं कि r% वाले भाग के लिए बचे ₹4,100 दो वर्ष का ब्याज हैं; 4.1% में शेष भाग को ₹50,000 मान लिया गया है।","subtopic":"divided-sums"},
  {"id":"quant-simple-interest-161","question":"Consider three statements about simple interest: I. The interest earned is the same every year. II. The amounts at the end of successive years form an arithmetic progression. III. If a sum doubles in 10 years, it triples in 15 years. Which are true?","options":["I, II and III","I and II only","I only","II and III only"],"answer":1,"explanation":"I and II hold because interest is a fixed amount each year. III is false: doubling in 10 years means 10% a year, so tripling (200% interest) takes 20 years.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"साधारण ब्याज के बारे में तीन कथनों पर विचार कीजिए: I. अर्जित ब्याज हर वर्ष समान होता है। II. क्रमिक वर्षों के अंत में मिश्रधन एक समांतर श्रेढ़ी बनाते हैं। III. यदि कोई धनराशि 10 वर्ष में दोगुनी हो जाती है, तो वह 15 वर्ष में तीन गुनी हो जाती है। कौन-से सही हैं?","optionsHi":["I, II और III","केवल I और II","केवल I","केवल II और III"],"explanationHi":"I और II सही हैं क्योंकि ब्याज हर वर्ष एक निश्चित राशि होता है। III गलत है: 10 वर्ष में दोगुना होने का अर्थ है 10% प्रति वर्ष, इसलिए तीन गुना होने (200% ब्याज) में 20 वर्ष लगते हैं।","subtopic":"basic-formula"},
  {"id":"quant-simple-interest-162","question":"A sum at simple interest amounts to ₹1,860 in 3 years. If the rate had been 50% higher, it would have amounted to ₹2,040 in the same time. What is the sum?","options":["₹1,500","₹1,320","₹1,680","₹1,140"],"answer":0,"explanation":"Raising the rate by half adds half the interest: I/2 = 2,040 − 1,860 = 180, so I = 360 and P = ₹1,500. Taking the extra ₹180 as the whole interest gives ₹1,680.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"साधारण ब्याज पर कोई धनराशि 3 वर्ष में ₹1,860 हो जाती है। यदि दर 50% अधिक होती, तो वह उतने ही समय में ₹2,040 हो जाती। धनराशि क्या है?","optionsHi":["₹1,500","₹1,320","₹1,680","₹1,140"],"explanationHi":"दर में आधे की वृद्धि से ब्याज में आधा और जुड़ता है: I/2 = 2,040 − 1,860 = 180, अतः I = 360 और P = ₹1,500। अतिरिक्त ₹180 को पूरा ब्याज मानने पर ₹1,680 आता है।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-163","question":"What sum will amount to ₹5,200 in 6 years at the same rate of simple interest at which ₹2,000 amounts to ₹2,500 in 2½ years?","options":["₹4,160","₹3,250","₹3,466.67","₹2,166.67"],"answer":1,"explanation":"Rate = 500/(2,000 × 2.5) = 10%, so 6 years give 60% and P = 5,200/1.6 = ₹3,250. Taking 20% off ₹5,200 gives ₹4,160, the wrong base.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"कौन-सी धनराशि उसी साधारण ब्याज दर पर 6 वर्ष में ₹5,200 हो जाएगी, जिस दर पर ₹2,000, 2½ वर्ष में ₹2,500 हो जाते हैं?","optionsHi":["₹4,160","₹3,250","₹3,466.67","₹2,166.67"],"explanationHi":"दर = 500/(2,000 × 2.5) = 10%, इसलिए 6 वर्ष में 60% ब्याज मिलता है और P = 5,200/1.6 = ₹3,250। ₹5,200 का 20% घटाने पर ₹4,160 आता है, जो गलत आधार है।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-164","question":"What is the present worth of ₹1,404 due 2 years hence, if money earns 4% per annum simple interest?","options":["₹1,300","₹1,291.68","₹1,298.08","₹1,348"],"answer":0,"explanation":"Present worth × 1.08 = 1,404, so PW = ₹1,300. Taking 8% off ₹1,404 gives ₹1,291.68 (the wrong base); discounting at compound interest gives ₹1,298.08.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि धन पर 4% वार्षिक साधारण ब्याज मिलता है, तो 2 वर्ष बाद देय ₹1,404 का वर्तमान मूल्य क्या है?","optionsHi":["₹1,300","₹1,291.68","₹1,298.08","₹1,348"],"explanationHi":"वर्तमान मूल्य × 1.08 = 1,404, अतः वर्तमान मूल्य = ₹1,300। ₹1,404 का 8% घटाने पर ₹1,291.68 आता है (गलत आधार); चक्रवृद्धि ब्याज से बट्टा लगाने पर ₹1,298.08 आता है।","subtopic":"present-worth-discount"},
  {"id":"quant-simple-interest-165","question":"A sum lent at 8% simple interest for 5 years earns ₹1,200 more than when it is lent at 5% for 6 years. What is the sum?","options":["₹40,000","₹24,000","₹12,000","₹8,000"],"answer":2,"explanation":"Interest: 40% of P versus 30% of P, so 10% of P = 1,200 and P = ₹12,000. Using only the 3% rate gap gives ₹40,000.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"8% साधारण ब्याज पर 5 वर्ष के लिए उधार दी गई धनराशि, 5% पर 6 वर्ष के लिए उधार देने की तुलना में ₹1,200 अधिक कमाती है। धनराशि क्या है?","optionsHi":["₹40,000","₹24,000","₹12,000","₹8,000"],"explanationHi":"ब्याज: P का 40% बनाम P का 30%, अतः P का 10% = 1,200 और P = ₹12,000। केवल 3% का दर-अंतर लेने पर ₹40,000 आता है।","subtopic":"changing-rates"},
  {"id":"quant-simple-interest-166","question":"At what rate of simple interest will a sum become 2.5 times itself in the same time in which it becomes 1.75 times itself at 6% per annum?","options":["8.57%","15%","9%","12%"],"answer":3,"explanation":"At 6%, 75% interest takes 12.5 years; 150% in 12.5 years needs 12%. Scaling the rate by 2.5/1.75 (8.57%) compares amounts instead of interests.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"साधारण ब्याज की किस दर से कोई धनराशि उतने ही समय में स्वयं की 2.5 गुनी हो जाएगी, जितने समय में वह 6% वार्षिक दर पर स्वयं की 1.75 गुनी हो जाती है?","optionsHi":["8.57%","15%","9%","12%"],"explanationHi":"6% पर 75% ब्याज में 12.5 वर्ष लगते हैं; 12.5 वर्ष में 150% के लिए 12% चाहिए। दर को 2.5/1.75 से गुणा करने (8.57%) में मिश्रधनों की तुलना की गई है, ब्याजों की नहीं।","subtopic":"amount-and-doubling"},
  {"id":"quant-simple-interest-167","question":"The banker's discount on a bill due 8 months hence is ₹682 at 15% per annum simple interest. What is the true discount?","options":["₹682","₹620","₹600","₹640"],"answer":1,"explanation":"BD = face value × rt/100 = A × 10% = 682, so A = 6,820. TD = A × 10%/(1 + 10%) = 6,820/11 = ₹620 (present worth ₹6,200). 682 is the BD itself.","difficulty":"very-hard","questionHi":"15% वार्षिक साधारण ब्याज की दर से 8 महीने बाद देय एक बिल पर बैंकर की छूट ₹682 है। सच्ची छूट कितनी है?","optionsHi":["₹682","₹620","₹600","₹640"],"explanationHi":"BD = अंकित मूल्य × rt/100 = A × 10% = 682, अतः A = 6,820। TD = A × 10%/(1 + 10%) = 6,820/11 = ₹620 (वर्तमान मूल्य ₹6,200)। 682 स्वयं BD है।","subtopic":"present-worth-discount","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-168","question":"The true discount on a sum due 3 years hence at 5% per annum simple interest is ₹180. What is the sum due?","options":["₹1,200","₹1,380","₹1,500","₹1,350"],"answer":1,"explanation":"TD = A × rt/(100 + rt) = A × 15/115, so A = 180 × 115/15 = ₹1,380. The present worth is 1,380 − 180 = ₹1,200, which is not the sum due.","difficulty":"moderate","questionHi":"5% वार्षिक साधारण ब्याज की दर से 3 वर्ष बाद देय एक राशि पर सच्ची छूट ₹180 है। देय राशि कितनी है?","optionsHi":["₹1,200","₹1,380","₹1,500","₹1,350"],"explanationHi":"TD = A × rt/(100 + rt) = A × 15/115, अतः A = 180 × 115/15 = ₹1,380। वर्तमान मूल्य 1,380 − 180 = ₹1,200 है, जो देय राशि नहीं है।","subtopic":"present-worth-discount","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-169","question":"The banker's discount and the true discount on a bill due after a certain time are ₹336 and ₹300. What is the face value of the bill?","options":["₹2,500","₹3,000","₹2,836","₹2,800"],"answer":3,"explanation":"BD − TD = TD²/PW, so 36 = 90,000/PW and PW = ₹2,500. Face value = PW + TD = 2,500 + 300 = ₹2,800; 2,500 is only the present worth.","difficulty":"very-hard","questionHi":"एक बिल पर, जो कुछ समय बाद देय है, बैंकर की छूट ₹336 और सच्ची छूट ₹300 है। बिल का अंकित मूल्य कितना है?","optionsHi":["₹2,500","₹3,000","₹2,836","₹2,800"],"explanationHi":"BD − TD = TD²/PW, अतः 36 = 90,000/PW और PW = ₹2,500। अंकित मूल्य = PW + TD = 2,500 + 300 = ₹2,800; 2,500 केवल वर्तमान मूल्य है।","subtopic":"present-worth-discount","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-170","question":"The banker's discount on a bill is to the true discount as 11 : 10. If the rate of simple interest is 8% per annum, what is the period of the bill?","options":["1 year 3 months","1 year 6 months","1 year 8 months","10 months"],"answer":0,"explanation":"BD/TD = 1 + rt/100 = 11/10, so rt = 10 and t = 10/8 = 1.25 years = 1 year 3 months.","difficulty":"very-hard","questionHi":"एक बिल पर बैंकर की छूट और सच्ची छूट का अनुपात 11 : 10 है। यदि साधारण ब्याज की दर 8% वार्षिक है, तो बिल की अवधि क्या है?","optionsHi":["1 वर्ष 3 महीने","1 वर्ष 6 महीने","1 वर्ष 8 महीने","10 महीने"],"explanationHi":"BD/TD = 1 + rt/100 = 11/10, अतः rt = 10 और t = 10/8 = 1.25 वर्ष = 1 वर्ष 3 महीने।","subtopic":"present-worth-discount","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-171","question":"A sum of ₹2,415 is due 2 years hence. If money earns simple interest at 5% for the first year and 10% for the second year, what is its present worth?","options":["₹2,000","₹2,200","₹2,100","₹2,250"],"answer":2,"explanation":"The total rate over the two years is 5% + 10% = 15%, so PW = 2,415/1.15 = ₹2,100. Using one rate of 10% for both years would give about ₹2,012.50.","difficulty":"very-hard","questionHi":"₹2,415 की एक राशि 2 वर्ष बाद देय है। यदि धन पर साधारण ब्याज पहले वर्ष 5% और दूसरे वर्ष 10% की दर से मिलता है, तो इसका वर्तमान मूल्य कितना है?","optionsHi":["₹2,000","₹2,200","₹2,100","₹2,250"],"explanationHi":"दो वर्षों की कुल दर 5% + 10% = 15% है, अतः वर्तमान मूल्य = 2,415/1.15 = ₹2,100। दोनों वर्षों के लिए 10% लेने पर लगभग ₹2,012.50 आता, जो गलत है।","subtopic":"present-worth-discount","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-172","question":"A debtor owes ₹13,000 due after 3 years. The creditor can invest money elsewhere at 10% simple interest. What is the least cash payment he should accept today in full settlement?","options":["₹9,100","₹9,750","₹10,000","₹10,400"],"answer":2,"explanation":"The least acceptable cash is the present worth: 13,000/(1 + 0.1 × 3) = 13,000/1.3 = ₹10,000. Taking 30% off 13,000 gives the trap ₹9,100.","difficulty":"moderate","questionHi":"एक कर्जदार पर ₹13,000 का ऋण है जो 3 वर्ष बाद देय है। लेनदार अन्यत्र 10% साधारण ब्याज पर धन लगा सकता है। पूर्ण निपटान के लिए उसे आज कम से कम कितना नकद स्वीकार करना चाहिए?","optionsHi":["₹9,100","₹9,750","₹10,000","₹10,400"],"explanationHi":"स्वीकार्य न्यूनतम नकद राशि वर्तमान मूल्य है: 13,000/(1 + 0.1 × 3) = 13,000/1.3 = ₹10,000। 13,000 में से 30% घटाने पर गलत ₹9,100 आता है।","subtopic":"present-worth-discount","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-173","question":"The true discount on a bill is 1/6 of its face value. The banker's discount is what fraction of the face value?","options":["1/5","1/6","1/4","1/7"],"answer":0,"explanation":"TD/A = rt/(100 + rt) = 1/6 gives rt = 20. BD = A × rt/100 = A × 20/100 = A/5. The BD is always larger than the TD, so 1/6 cannot be right.","difficulty":"very-hard","questionHi":"एक बिल पर सच्ची छूट उसके अंकित मूल्य की 1/6 है। बैंकर की छूट अंकित मूल्य की कितने भाग के बराबर है?","optionsHi":["1/5","1/6","1/4","1/7"],"explanationHi":"TD/A = rt/(100 + rt) = 1/6 से rt = 20। BD = A × rt/100 = A × 20/100 = A/5। BD हमेशा TD से बड़ी होती है, इसलिए 1/6 सही नहीं हो सकता।","subtopic":"present-worth-discount","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-174","question":"A man borrows ₹12,000 at 9% per annum simple interest. He lends ₹8,000 of it at 12% and the rest at 15%. What is his net gain in 4 years?","options":["₹480","₹1,560","₹1,440","₹1,920"],"answer":3,"explanation":"Yearly interest paid = 1,080; received = 960 + 600 = 1,560. The yearly gain is ₹480, so in 4 years it is ₹1,920. ₹480 is only one year's gain.","difficulty":"very-hard","questionHi":"एक व्यक्ति 9% वार्षिक साधारण ब्याज पर ₹12,000 उधार लेता है। वह उसमें से ₹8,000 को 12% पर और शेष को 15% पर उधार दे देता है। 4 वर्ष में उसका कुल लाभ कितना है?","optionsHi":["₹480","₹1,560","₹1,440","₹1,920"],"explanationHi":"वार्षिक ब्याज चुकाया = 1,080; प्राप्त = 960 + 600 = 1,560। वार्षिक लाभ ₹480 है, अतः 4 वर्ष में ₹1,920। ₹480 केवल एक वर्ष का लाभ है।","subtopic":"lending-borrowing","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-175","question":"B borrows ₹12,500 from A at 6% per annum simple interest and lends it to C at a certain rate. In 3 years B gains ₹1,125. At what rate did B lend to C?","options":["3%","9%","8%","10%"],"answer":1,"explanation":"Gain per year = 1,125/3 = ₹375, which is 3% of 12,500, so the lending rate is 6% + 3% = 9%. The 3% is only the margin.","difficulty":"moderate","questionHi":"B, A से 6% वार्षिक साधारण ब्याज पर ₹12,500 उधार लेता है और उसे C को एक निश्चित दर पर उधार देता है। 3 वर्ष में B को ₹1,125 का लाभ होता है। B ने C को किस दर पर उधार दिया?","optionsHi":["3%","9%","8%","10%"],"explanationHi":"प्रति वर्ष लाभ = 1,125/3 = ₹375, जो 12,500 का 3% है, अतः उधार देने की दर 6% + 3% = 9%। 3% केवल अंतर है।","subtopic":"lending-borrowing","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-176","question":"A person borrows ₹18,000 at 7.5% per annum simple interest and lends part of it at 10% and the rest at 9%. His net gain in 3 years is ₹1,260. How much did he lend at 10%?","options":["₹12,000","₹15,000","₹3,000","₹6,000"],"answer":1,"explanation":"Yearly gain = 1,260/3 = 420. Lending everything at 9% would gain (9 − 7.5)% of 18,000 = 270, so the extra 150 comes from the 1% extra on the 10% part: 150/0.01 = ₹15,000.","difficulty":"very-hard","questionHi":"एक व्यक्ति 7.5% वार्षिक साधारण ब्याज पर ₹18,000 उधार लेता है और उसका एक भाग 10% पर तथा शेष 9% पर उधार दे देता है। 3 वर्ष में उसका कुल लाभ ₹1,260 है। उसने 10% पर कितना उधार दिया?","optionsHi":["₹12,000","₹15,000","₹3,000","₹6,000"],"explanationHi":"वार्षिक लाभ = 1,260/3 = 420। सब कुछ 9% पर देने पर लाभ 18,000 का (9 − 7.5)% = 270 होता, अतः शेष 150 लाभ 10% वाले भाग पर अतिरिक्त 1% से आता है: 150/0.01 = ₹15,000।","subtopic":"lending-borrowing","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-177","question":"A bank pays 6% per annum simple interest to depositors and lends 80% of the deposits at 10% per annum, keeping the rest idle. What is its yearly profit on deposits of ₹10 lakh?","options":["₹40,000","₹8,000","₹24,000","₹20,000"],"answer":3,"explanation":"Income = 10% of ₹8 lakh = ₹80,000; interest paid = 6% of ₹10 lakh = ₹60,000. Profit = ₹20,000. Taking 10% − 6% on the full deposit would wrongly give ₹40,000.","difficulty":"hard","questionHi":"एक बैंक जमाकर्ताओं को 6% वार्षिक साधारण ब्याज देता है और जमा राशि का 80% भाग 10% वार्षिक की दर से उधार देता है, शेष खाली रखता है। ₹10 लाख की जमा राशि पर उसका वार्षिक लाभ कितना है?","optionsHi":["₹40,000","₹8,000","₹24,000","₹20,000"],"explanationHi":"आय = ₹8 लाख का 10% = ₹80,000; चुकाया गया ब्याज = ₹10 लाख का 6% = ₹60,000। लाभ = ₹20,000। पूरी जमा राशि पर 10% − 6% लेने पर गलत ₹40,000 आता है।","subtopic":"lending-borrowing","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-178","question":"A man borrows ₹8,000 at 12% per annum simple interest and lends it at 15% per annum. In how many years will his net gain be ₹1,440?","options":["6 years","4 years","5 years","8 years"],"answer":0,"explanation":"Gain per year = 3% of 8,000 = ₹240, so the time is 1,440/240 = 6 years.","difficulty":"moderate","questionHi":"एक व्यक्ति 12% वार्षिक साधारण ब्याज पर ₹8,000 उधार लेता है और उसे 15% वार्षिक की दर पर उधार दे देता है। कितने वर्षों में उसका कुल लाभ ₹1,440 होगा?","optionsHi":["6 वर्ष","4 वर्ष","5 वर्ष","8 वर्ष"],"explanationHi":"प्रति वर्ष लाभ = 8,000 का 3% = ₹240, अतः समय = 1,440/240 = 6 वर्ष।","subtopic":"lending-borrowing","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-179","question":"Sunita borrows ₹24,000 at 10% per annum simple interest and repays after 3 years. She lends the same sum at 14% but only for the first 2 years, and the money then lies idle. What is the net result of the whole dealing?","options":["Gain of ₹480","Gain of ₹960","Loss of ₹480","Loss of ₹960"],"answer":2,"explanation":"Interest paid = 24,000 × 10% × 3 = ₹7,200; interest earned = 24,000 × 14% × 2 = ₹6,720. Net = 6,720 − 7,200 = a loss of ₹480. The 4% margin gain of ₹960 per year applies only while both run.","difficulty":"very-hard","questionHi":"सुनीता 10% वार्षिक साधारण ब्याज पर ₹24,000 उधार लेती है और 3 वर्ष बाद चुकाती है। वह यही राशि 14% पर केवल पहले 2 वर्ष के लिए उधार देती है और उसके बाद धन खाली पड़ा रहता है। पूरे लेन-देन का शुद्ध परिणाम क्या है?","optionsHi":["₹480 का लाभ","₹960 का लाभ","₹480 की हानि","₹960 की हानि"],"explanationHi":"चुकाया गया ब्याज = 24,000 × 10% × 3 = ₹7,200; प्राप्त ब्याज = 24,000 × 14% × 2 = ₹6,720। शुद्ध परिणाम = 6,720 − 7,200 = ₹480 की हानि। 4% अंतर से ₹960 प्रति वर्ष का लाभ केवल तभी मिलता है जब दोनों चल रहे हों।","subtopic":"lending-borrowing","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-180","question":"A man borrows money at 9% per annum simple interest and lends it at r% per annum. His yearly gain equals 1/6 of the interest he pays yearly. What is r?","options":["11%","10%","10.5%","12%"],"answer":2,"explanation":"Gain = (r − 9)% of the sum = 1/6 of 9% = 1.5%, so r − 9 = 1.5 and r = 10.5%.","difficulty":"hard","questionHi":"एक व्यक्ति 9% वार्षिक साधारण ब्याज पर धन उधार लेता है और उसे r% वार्षिक पर उधार देता है। उसका वार्षिक लाभ उसके द्वारा चुकाए गए वार्षिक ब्याज का 1/6 है। r का मान क्या है?","optionsHi":["11%","10%","10.5%","12%"],"explanationHi":"लाभ = राशि का (r − 9)% = 9% का 1/6 = 1.5%, अतः r − 9 = 1.5 और r = 10.5%।","subtopic":"lending-borrowing","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-181","question":"A loan of ₹6,300 at 5% per annum simple interest is to be repaid in 3 equal annual instalments, the first paid at the end of the first year. What is each instalment?","options":["₹2,300","₹2,100","₹2,415","₹2,200"],"answer":0,"explanation":"Loan with interest after 3 years = 6,300 × 1.15 = 7,245. Instalments earn interest for 2, 1 and 0 years: x(1.10 + 1.05 + 1) = 3.15x = 7,245, so x = ₹2,300. 2,415 is 7,245 ÷ 3, ignoring interest on instalments.","difficulty":"very-hard","questionHi":"5% वार्षिक साधारण ब्याज पर लिया गया ₹6,300 का ऋण 3 समान वार्षिक किस्तों में चुकाना है, जिसकी पहली किस्त पहले वर्ष के अंत में दी जाती है। प्रत्येक किस्त कितनी है?","optionsHi":["₹2,300","₹2,100","₹2,415","₹2,200"],"explanationHi":"3 वर्ष बाद ब्याज सहित ऋण = 6,300 × 1.15 = 7,245। किस्तों पर क्रमशः 2, 1 और 0 वर्ष का ब्याज लगता है: x(1.10 + 1.05 + 1) = 3.15x = 7,245, अतः x = ₹2,300। 2,415 = 7,245 ÷ 3 है, जिसमें किस्तों पर ब्याज छोड़ दिया गया है।","subtopic":"instalments","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-182","question":"A loan at 10% per annum simple interest is cleared by three year-end instalments of ₹3,300, ₹3,600 and ₹3,900 paid at the end of the first, second and third years. What was the loan?","options":["₹10,800","₹9,600","₹9,300","₹9,000"],"answer":3,"explanation":"Each instalment is discounted by its own time: 3,300/1.1 + 3,600/1.2 + 3,900/1.3 = 3,000 + 3,000 + 3,000 = ₹9,000. The sum of instalments, 10,800, includes the interest.","difficulty":"very-hard","questionHi":"10% वार्षिक साधारण ब्याज पर लिया गया एक ऋण तीन वर्षांत किस्तों ₹3,300, ₹3,600 और ₹3,900 से चुकाया जाता है, जो क्रमशः पहले, दूसरे और तीसरे वर्ष के अंत में दी जाती हैं। ऋण कितना था?","optionsHi":["₹10,800","₹9,600","₹9,300","₹9,000"],"explanationHi":"प्रत्येक किस्त को उसके अपने समय के अनुसार घटाएँ: 3,300/1.1 + 3,600/1.2 + 3,900/1.3 = 3,000 + 3,000 + 3,000 = ₹9,000। किस्तों का योग 10,800 है, जिसमें ब्याज शामिल है।","subtopic":"instalments","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-183","question":"A debt of ₹2,520 due after 2 years is to be discharged in two equal annual instalments, the first at the end of the first year. If the rate is 10% per annum simple interest, what is each instalment?","options":["₹1,260","₹1,200","₹1,050","₹1,150"],"answer":1,"explanation":"The first instalment earns 10% for one more year: 1.1x + x = 2,520, so 2.1x = 2,520 and x = ₹1,200. Simply halving 2,520 gives the trap ₹1,260.","difficulty":"hard","questionHi":"2 वर्ष बाद देय ₹2,520 के ऋण को दो समान वार्षिक किस्तों में चुकाना है, जिसकी पहली किस्त पहले वर्ष के अंत में दी जाती है। यदि दर 10% वार्षिक साधारण ब्याज है, तो प्रत्येक किस्त कितनी है?","optionsHi":["₹1,260","₹1,200","₹1,050","₹1,150"],"explanationHi":"पहली किस्त पर एक वर्ष और 10% ब्याज मिलता है: 1.1x + x = 2,520, अतः 2.1x = 2,520 और x = ₹1,200। 2,520 को केवल आधा करने पर गलत ₹1,260 आता है।","subtopic":"instalments","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-184","question":"A person deposits ₹500 at the beginning of every month for 12 months in a recurring deposit paying 6% per annum simple interest. What is the maturity amount?","options":["₹6,165","₹6,195","₹6,360","₹6,180"],"answer":1,"explanation":"Deposits stay for 12, 11, …, 1 months: total 78 deposit-months. Interest = 500 × 78 × (6/1200) = ₹195, so the maturity is 6,000 + 195 = ₹6,195. Using 6 months on average gives ₹6,180.","difficulty":"hard","questionHi":"एक व्यक्ति आवर्ती जमा योजना में, जो 6% वार्षिक साधारण ब्याज देती है, 12 महीने तक हर महीने के आरंभ में ₹500 जमा करता है। परिपक्वता राशि कितनी है?","optionsHi":["₹6,165","₹6,195","₹6,360","₹6,180"],"explanationHi":"जमा राशियाँ क्रमशः 12, 11, …, 1 महीने रहती हैं: कुल 78 जमा-महीने। ब्याज = 500 × 78 × (6/1200) = ₹195, अतः परिपक्वता राशि 6,000 + 195 = ₹6,195। औसतन 6 महीने लेने पर ₹6,180 आता है।","subtopic":"instalments","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-185","question":"A recurring deposit with equal monthly deposits (made at the start of each month) runs for 15 months at 8% per annum simple interest and earns total interest of ₹1,600. What is the monthly deposit?","options":["₹2,500","₹1,800","₹2,400","₹2,000"],"answer":3,"explanation":"Deposit-months = 15 × 16/2 = 120. Interest = d × 120 × (8/1200) = 0.8d = 1,600, so d = ₹2,000.","difficulty":"hard","questionHi":"एक आवर्ती जमा योजना में समान मासिक जमा (प्रत्येक महीने के आरंभ में) 15 महीने तक 8% वार्षिक साधारण ब्याज पर की जाती है और कुल ब्याज ₹1,600 मिलता है। मासिक जमा राशि कितनी है?","optionsHi":["₹2,500","₹1,800","₹2,400","₹2,000"],"explanationHi":"जमा-महीने = 15 × 16/2 = 120। ब्याज = d × 120 × (8/1200) = 0.8d = 1,600, अतः d = ₹2,000।","subtopic":"instalments","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-186","question":"A loan of ₹8,000 at 10% per annum simple interest is repaid in two year-end instalments (end of year 1 and end of year 2) in the ratio 11 : 12. What is the larger instalment?","options":["₹4,800","₹4,400","₹4,200","₹5,280"],"answer":0,"explanation":"With instalments 11k and 12k: 11k/1.1 + 12k/1.2 = 10k + 10k = 20k = 8,000, so k = 400 and the larger instalment is 12k = ₹4,800.","difficulty":"very-hard","questionHi":"10% वार्षिक साधारण ब्याज पर लिया गया ₹8,000 का ऋण दो वार्षिक किस्तों (पहले वर्ष के अंत और दूसरे वर्ष के अंत) में 11 : 12 के अनुपात में चुकाया जाता है। बड़ी किस्त कितनी है?","optionsHi":["₹4,800","₹4,400","₹4,200","₹5,280"],"explanationHi":"किस्तें 11k और 12k लें: 11k/1.1 + 12k/1.2 = 10k + 10k = 20k = 8,000, अतः k = 400 और बड़ी किस्त 12k = ₹4,800।","subtopic":"instalments","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-187","question":"₹7,300 is divided into three parts and lent at 4% for 1 year, 5% for 2 years and 6% for 3 years, so that the interest from each part is the same. What is the largest part?","options":["₹2,500","₹3,650","₹4,500","₹1,800"],"answer":2,"explanation":"Equal interest means part × rate × time is equal, so parts ∝ 1/4 : 1/10 : 1/18 = 45 : 18 : 10 (73 parts). One part = 7,300/73 = 100, so the largest is ₹4,500.","difficulty":"very-hard","questionHi":"₹7,300 को तीन भागों में बाँटकर 4% पर 1 वर्ष, 5% पर 2 वर्ष और 6% पर 3 वर्ष के लिए उधार दिया जाता है, ताकि प्रत्येक भाग से मिलने वाला ब्याज समान हो। सबसे बड़ा भाग कितना है?","optionsHi":["₹2,500","₹3,650","₹4,500","₹1,800"],"explanationHi":"ब्याज समान होने का अर्थ है भाग × दर × समय समान, अतः भाग ∝ 1/4 : 1/10 : 1/18 = 45 : 18 : 10 (कुल 73 भाग)। एक भाग = 7,300/73 = 100, इसलिए सबसे बड़ा भाग ₹4,500।","subtopic":"divided-sums","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-188","question":"₹8,400 is divided into two parts, lent at 6% and 9% per annum simple interest. The interest on the first part for 4 years equals the interest on the second part for 2 years. What is the first part?","options":["₹4,800","₹4,200","₹3,600","₹3,200"],"answer":2,"explanation":"P₁ × 6 × 4 = P₂ × 9 × 2 gives P₁ : P₂ = 18 : 24 = 3 : 4. The first part is 3/7 of 8,400 = ₹3,600; ₹4,800 is the second part.","difficulty":"hard","questionHi":"₹8,400 को दो भागों में बाँटकर 6% और 9% वार्षिक साधारण ब्याज पर उधार दिया जाता है। पहले भाग पर 4 वर्ष का ब्याज दूसरे भाग पर 2 वर्ष के ब्याज के बराबर है। पहला भाग कितना है?","optionsHi":["₹4,800","₹4,200","₹3,600","₹3,200"],"explanationHi":"P₁ × 6 × 4 = P₂ × 9 × 2 से P₁ : P₂ = 18 : 24 = 3 : 4। पहला भाग 8,400 का 3/7 = ₹3,600 है; ₹4,800 दूसरा भाग है।","subtopic":"divided-sums","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-189","question":"₹4,700 is divided into two parts. One part is lent at 10% simple interest for 2 years and the other at 5% simple interest for 3 years, and the two amounts obtained are equal. What is the part lent at 10%?","options":["₹2,300","₹2,400","₹2,350","₹2,200"],"answer":0,"explanation":"1.2x = 1.15(4,700 − x) gives 2.35x = 5,405, so x = ₹2,300. Check: 2,300 × 1.2 = 2,760 = 2,400 × 1.15. ₹2,400 is the other part.","difficulty":"very-hard","questionHi":"₹4,700 को दो भागों में बाँटा जाता है। एक भाग 10% साधारण ब्याज पर 2 वर्ष के लिए और दूसरा 5% साधारण ब्याज पर 3 वर्ष के लिए उधार दिया जाता है और दोनों से प्राप्त मिश्रधन बराबर है। 10% पर दिया गया भाग कितना है?","optionsHi":["₹2,300","₹2,400","₹2,350","₹2,200"],"explanationHi":"1.2x = 1.15(4,700 − x) से 2.35x = 5,405, अतः x = ₹2,300। जाँच: 2,300 × 1.2 = 2,760 = 2,400 × 1.15। ₹2,400 दूसरा भाग है।","subtopic":"divided-sums","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-190","question":"₹36,000 is divided into two parts lent at 8% and 10% per annum simple interest. The yearly interest on the second part exceeds that on the first by ₹540. What is the part lent at 10%?","options":["₹17,000","₹18,000","₹20,000","₹19,000"],"answer":3,"explanation":"Let the 8% part be x: 0.10(36,000 − x) − 0.08x = 540 gives 3,600 − 0.18x = 540, so x = 17,000. The 10% part is 36,000 − 17,000 = ₹19,000.","difficulty":"hard","questionHi":"₹36,000 को दो भागों में बाँटकर 8% और 10% वार्षिक साधारण ब्याज पर उधार दिया जाता है। दूसरे भाग का वार्षिक ब्याज पहले भाग के वार्षिक ब्याज से ₹540 अधिक है। 10% पर दिया गया भाग कितना है?","optionsHi":["₹17,000","₹18,000","₹20,000","₹19,000"],"explanationHi":"8% वाला भाग x लें: 0.10(36,000 − x) − 0.08x = 540 से 3,600 − 0.18x = 540, अतः x = 17,000। 10% वाला भाग 36,000 − 17,000 = ₹19,000।","subtopic":"divided-sums","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-191","question":"A sum is divided in the ratio 2 : 3 and the two parts are lent at 5% and 8% per annum simple interest. For what ratio of times (first : second) will the two parts earn equal interest?","options":["5 : 12","12 : 5","6 : 5","4 : 3"],"answer":1,"explanation":"Equal interest: 2 × 5 × t₁ = 3 × 8 × t₂, so t₁ : t₂ = 24 : 10 = 12 : 5. The reverse 5 : 12 would favour the larger, higher-rate part.","difficulty":"hard","questionHi":"एक राशि को 2 : 3 के अनुपात में बाँटकर दोनों भागों को 5% और 8% वार्षिक साधारण ब्याज पर उधार दिया जाता है। समयों के किस अनुपात (पहला : दूसरा) पर दोनों भागों से समान ब्याज मिलेगा?","optionsHi":["5 : 12","12 : 5","6 : 5","4 : 3"],"explanationHi":"ब्याज समान होने पर 2 × 5 × t₁ = 3 × 8 × t₂, अतः t₁ : t₂ = 24 : 10 = 12 : 5। उलटा अनुपात 5 : 12 बड़े और ऊँची दर वाले भाग के पक्ष में होगा, जो गलत है।","subtopic":"divided-sums","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-192","question":"₹11,400 is divided into two parts, the first lent at 6% for 3 years and the second at 5% for 4 years, so that the interest on both parts is equal. What is the total interest earned?","options":["₹1,080","₹2,160","₹2,280","₹2,052"],"answer":1,"explanation":"Equal interest: 18x = 20(11,400 − x) gives x = 6,000 and the other part is 5,400. Each earns 6,000 × 0.18 = ₹1,080, so the total is ₹2,160 (₹1,080 is one part's interest).","difficulty":"hard","questionHi":"₹11,400 को दो भागों में बाँटा जाता है; पहला भाग 6% पर 3 वर्ष के लिए और दूसरा 5% पर 4 वर्ष के लिए उधार दिया जाता है, ताकि दोनों भागों पर ब्याज बराबर हो। कुल ब्याज कितना मिला?","optionsHi":["₹1,080","₹2,160","₹2,280","₹2,052"],"explanationHi":"ब्याज बराबर होने पर 18x = 20(11,400 − x) से x = 6,000 और दूसरा भाग 5,400। प्रत्येक पर 6,000 × 0.18 = ₹1,080 ब्याज मिलता है, अतः कुल ब्याज ₹2,160 (₹1,080 केवल एक भाग का ब्याज है)।","subtopic":"divided-sums","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-193","question":"The simple interest on a sum at 10% per annum for 2 years is less by ₹640 than what it would be at 12% per annum for 3 years. What is the sum?","options":["₹3,200","₹8,000","₹5,000","₹4,000"],"answer":3,"explanation":"Interest rises from 20% to 36% of the sum, an increase of 16%. So 0.16P = 640 and P = ₹4,000. Using only the 2-point rate rise (0.08P = 640) gives the trap ₹8,000.","difficulty":"hard","questionHi":"किसी धनराशि पर 10% वार्षिक की दर से 2 वर्ष का साधारण ब्याज, 12% वार्षिक की दर से 3 वर्ष के ब्याज से ₹640 कम है। वह धनराशि कितनी है?","optionsHi":["₹3,200","₹8,000","₹5,000","₹4,000"],"explanationHi":"ब्याज राशि के 20% से बढ़कर 36% हो जाता है, यानी 16% की वृद्धि। अतः 0.16P = 640 और P = ₹4,000। केवल दर में 2 अंक की वृद्धि लेने (0.08P = 640) पर गलत ₹8,000 आता है।","subtopic":"changing-rates","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-194","question":"At simple interest a sum becomes 1.6 times itself in 6 years. At a rate 2 percentage points higher, in how many years will the same sum become 2.2 times itself?","options":["10 years","12 years","8 years","11 years"],"answer":0,"explanation":"Interest is 0.6 of the sum in 6 years, so the rate is 10%. At 12%, the time to earn 1.2 times the sum is 1.2/0.12 = 10 years.","difficulty":"very-hard","questionHi":"साधारण ब्याज पर कोई धनराशि 6 वर्ष में स्वयं की 1.6 गुनी हो जाती है। दर 2 प्रतिशत अंक अधिक होने पर वही धनराशि कितने वर्ष में स्वयं की 2.2 गुनी हो जाएगी?","optionsHi":["10 वर्ष","12 वर्ष","8 वर्ष","11 वर्ष"],"explanationHi":"6 वर्ष में ब्याज राशि का 0.6 गुना है, अतः दर 10% है। 12% पर राशि का 1.2 गुना ब्याज कमाने में 1.2/0.12 = 10 वर्ष लगते हैं।","subtopic":"changing-rates","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-195","question":"A sum amounts to ₹2,400 in 2 years and ₹2,800 in 4 years at simple interest. What will the same sum amount to in 5 years if the rate of interest is 3 percentage points higher?","options":["₹3,000","₹3,150","₹3,300","₹3,600"],"answer":2,"explanation":"Interest per year = (2,800 − 2,400)/2 = 200, so the sum is 2,400 − 400 = ₹2,000 and the rate is 10%. At 13% for 5 years, amount = 2,000 × 1.65 = ₹3,300. ₹3,000 uses the old rate.","difficulty":"very-hard","questionHi":"साधारण ब्याज पर कोई धनराशि 2 वर्ष में ₹2,400 और 4 वर्ष में ₹2,800 हो जाती है। यदि ब्याज की दर 3 प्रतिशत अंक अधिक हो, तो वही धनराशि 5 वर्ष में कितनी हो जाएगी?","optionsHi":["₹3,000","₹3,150","₹3,300","₹3,600"],"explanationHi":"प्रति वर्ष ब्याज = (2,800 − 2,400)/2 = 200, अतः मूलधन 2,400 − 400 = ₹2,000 और दर 10%। 13% पर 5 वर्ष में मिश्रधन = 2,000 × 1.65 = ₹3,300। ₹3,000 पुरानी दर से आता है।","subtopic":"changing-rates","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-196","question":"₹6,000 is lent at 5% per annum simple interest for 2 years. Then the whole amount is lent at 8% per annum simple interest for 3 years. What is the total interest earned over the 5 years?","options":["₹1,584","₹2,040","₹2,184","₹2,280"],"answer":2,"explanation":"First stage: 6,000 × 0.10 = 600, amount ₹6,600. Second stage: 6,600 × 0.24 = 1,584. Total interest = 600 + 1,584 = ₹2,184. Lending only the principal again gives 2,040.","difficulty":"very-hard","questionHi":"₹6,000 को 5% वार्षिक साधारण ब्याज पर 2 वर्ष के लिए उधार दिया जाता है। फिर पूरा मिश्रधन 8% वार्षिक साधारण ब्याज पर 3 वर्ष के लिए उधार दिया जाता है। 5 वर्षों में कुल ब्याज कितना मिला?","optionsHi":["₹1,584","₹2,040","₹2,184","₹2,280"],"explanationHi":"पहला चरण: 6,000 × 0.10 = 600, मिश्रधन ₹6,600। दूसरा चरण: 6,600 × 0.24 = 1,584। कुल ब्याज = 600 + 1,584 = ₹2,184। केवल मूलधन को दोबारा उधार देने पर 2,040 आता है।","subtopic":"changing-rates","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-197","question":"A sum is lent at 4% per annum for the first 2 years, 6% per annum for the next 3 years and 10% per annum beyond that, all at simple interest. If the interest after 8 years is ₹2,800, what is the sum?","options":["₹5,000","₹4,000","₹7,000","₹6,250"],"answer":0,"explanation":"Total rate over 8 years = 4(2) + 6(3) + 10(3) = 8 + 18 + 30 = 56%. So P = 2,800/0.56 = ₹5,000.","difficulty":"hard","questionHi":"एक धनराशि पहले 2 वर्ष 4% वार्षिक, अगले 3 वर्ष 6% वार्षिक और उसके बाद 10% वार्षिक की दर से, सब साधारण ब्याज पर, उधार दी जाती है। यदि 8 वर्ष बाद ब्याज ₹2,800 है, तो धनराशि कितनी है?","optionsHi":["₹5,000","₹4,000","₹7,000","₹6,250"],"explanationHi":"8 वर्षों में कुल दर = 4(2) + 6(3) + 10(3) = 8 + 18 + 30 = 56%। अतः P = 2,800/0.56 = ₹5,000।","subtopic":"changing-rates","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-198","question":"The principal is increased by 20%, the time is reduced by 1/6 and the rate is increased by 10%. What is the change in the simple interest?","options":["13⅓% increase","No change","6⅔% decrease","10% increase"],"answer":3,"explanation":"SI ∝ P × R × T, so the factor is 1.2 × 1.1 × (5/6) = 1.1, a 10% increase. Adding the changes (+20 + 10 − 16⅔) gives the wrong 13⅓%.","difficulty":"moderate","questionHi":"मूलधन में 20% की वृद्धि की जाती है, समय में 1/6 की कमी की जाती है और दर में 10% की वृद्धि की जाती है। साधारण ब्याज में क्या परिवर्तन होता है?","optionsHi":["13⅓% की वृद्धि","कोई परिवर्तन नहीं","6⅔% की कमी","10% की वृद्धि"],"explanationHi":"SI ∝ P × R × T, अतः गुणक 1.2 × 1.1 × (5/6) = 1.1, यानी 10% की वृद्धि। परिवर्तनों को जोड़ने (+20 + 10 − 16⅔) पर गलत 13⅓% आता है।","subtopic":"changing-rates","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-199","question":"A sum amounts to ₹7,200 in 4 years and ₹8,400 in 6 years at simple interest. In how many years will it amount to ₹12,000?","options":["10 years","12 years","14 years","16 years"],"answer":1,"explanation":"Interest per year = (8,400 − 7,200)/2 = 600, so the sum is 7,200 − 4 × 600 = ₹4,800. To reach 12,000 the interest needed is 7,200, which takes 7,200/600 = 12 years.","difficulty":"hard","questionHi":"साधारण ब्याज पर कोई धनराशि 4 वर्ष में ₹7,200 और 6 वर्ष में ₹8,400 हो जाती है। कितने वर्षों में यह ₹12,000 हो जाएगी?","optionsHi":["10 वर्ष","12 वर्ष","14 वर्ष","16 वर्ष"],"explanationHi":"प्रति वर्ष ब्याज = (8,400 − 7,200)/2 = 600, अतः मूलधन 7,200 − 4 × 600 = ₹4,800। ₹12,000 तक पहुँचने के लिए 7,200 ब्याज चाहिए, जिसमें 7,200/600 = 12 वर्ष लगते हैं।","subtopic":"amount-and-doubling","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-200","question":"At simple interest a sum becomes 1.5 times itself in 4 years. In how many years will it become 3.75 times itself?","options":["20 years","22 years","24 years","18 years"],"answer":1,"explanation":"Interest is 0.5 of the sum in 4 years, i.e. 0.125 of the sum per year. To become 3.75 times, the interest needed is 2.75 times the sum, which takes 2.75/0.125 = 22 years. Dividing 3.75 by 0.125 gives the wrong 30.","difficulty":"very-hard","questionHi":"साधारण ब्याज पर कोई धनराशि 4 वर्ष में स्वयं की 1.5 गुनी हो जाती है। कितने वर्षों में वह स्वयं की 3.75 गुनी हो जाएगी?","optionsHi":["20 वर्ष","22 वर्ष","24 वर्ष","18 वर्ष"],"explanationHi":"4 वर्ष में ब्याज राशि का 0.5 गुना है, यानी प्रति वर्ष 0.125 गुना। 3.75 गुनी होने के लिए ब्याज राशि का 2.75 गुना चाहिए, जिसमें 2.75/0.125 = 22 वर्ष लगते हैं। 3.75 को 0.125 से भाग देने पर गलत 30 आता है।","subtopic":"amount-and-doubling","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-201","question":"At simple interest, ₹9,600 amounts to ₹11,520 in 2 years 6 months. In how many years in all will it amount to ₹13,440?","options":["4 years 6 months","6 years","7 years 6 months","5 years"],"answer":3,"explanation":"Interest of ₹1,920 in 2.5 years is ₹768 per year. Total interest needed is 13,440 − 9,600 = 3,840, which takes 3,840/768 = 5 years in all. (2.5 more years would also be a trap.)","difficulty":"moderate","questionHi":"साधारण ब्याज पर ₹9,600 की राशि 2 वर्ष 6 महीने में ₹11,520 हो जाती है। कुल कितने वर्षों में यह ₹13,440 हो जाएगी?","optionsHi":["4 वर्ष 6 महीने","6 वर्ष","7 वर्ष 6 महीने","5 वर्ष"],"explanationHi":"2.5 वर्ष में ₹1,920 ब्याज, यानी प्रति वर्ष ₹768। कुल ब्याज 13,440 − 9,600 = 3,840 चाहिए, जिसमें कुल 3,840/768 = 5 वर्ष लगते हैं।","subtopic":"amount-and-doubling","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-202","question":"At simple interest, sum A doubles in 10 years and sum B becomes 2.5 times itself in 10 years. What is the ratio of the rate of interest on A to that on B?","options":["2 : 3","3 : 2","4 : 5","1 : 2"],"answer":0,"explanation":"A earns 100% of itself in 10 years, a rate of 10%. B earns 150% in 10 years, a rate of 15%. So the ratio is 10 : 15 = 2 : 3. Comparing 2 and 2.5 directly gives the wrong 4 : 5.","difficulty":"moderate","questionHi":"साधारण ब्याज पर राशि A 10 वर्ष में दोगुनी हो जाती है और राशि B 10 वर्ष में स्वयं की 2.5 गुनी हो जाती है। A और B पर ब्याज दर का अनुपात क्या है?","optionsHi":["2 : 3","3 : 2","4 : 5","1 : 2"],"explanationHi":"A, 10 वर्ष में अपने बराबर (100%) ब्याज कमाती है, यानी दर 10%। B, 10 वर्ष में 150% कमाती है, यानी दर 15%। अतः अनुपात 10 : 15 = 2 : 3। 2 और 2.5 की सीधी तुलना करने पर गलत 4 : 5 आता है।","subtopic":"amount-and-doubling","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-203","question":"At 8% per annum simple interest, ₹4,500 will amount to ₹5,490 in:","options":["2 years 6 months","3 years","2 years 9 months","2 years 3 months"],"answer":2,"explanation":"Interest = 5,490 − 4,500 = 990 and the yearly interest is 4,500 × 0.08 = 360, so t = 990/360 = 2.75 years = 2 years 9 months.","difficulty":"hard","questionHi":"8% वार्षिक साधारण ब्याज पर ₹4,500 की राशि कितने समय में ₹5,490 हो जाएगी?","optionsHi":["2 वर्ष 6 महीने","3 वर्ष","2 वर्ष 9 महीने","2 वर्ष 3 महीने"],"explanationHi":"ब्याज = 5,490 − 4,500 = 990 और वार्षिक ब्याज 4,500 × 0.08 = 360 है, अतः t = 990/360 = 2.75 वर्ष = 2 वर्ष 9 महीने।","subtopic":"amount-and-doubling","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-204","question":"What is the simple interest on ₹9,125 for 73 days at 6% per annum, taking a year as 365 days?","options":["₹1,095","₹10.95","₹109.50","₹112.50"],"answer":2,"explanation":"73 days = 73/365 = 1/5 year. SI = 9,125 × 6% × 1/5 = 9,125 × 0.012 = ₹109.50. Treating 73 days as 73 months or years inflates the answer.","difficulty":"moderate","questionHi":"₹9,125 पर 6% वार्षिक की दर से 73 दिन का साधारण ब्याज कितना होगा? (1 वर्ष = 365 दिन लें)","optionsHi":["₹1,095","₹10.95","₹109.50","₹112.50"],"explanationHi":"73 दिन = 73/365 = 1/5 वर्ष। SI = 9,125 × 6% × 1/5 = 9,125 × 0.012 = ₹109.50। 73 दिन को 73 महीने या वर्ष मान लेने पर उत्तर बहुत बढ़ जाता है।","subtopic":"basic-formula","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-205","question":"The simple interest on a sum for 3 years at 8% per annum exceeds its simple interest for 4 years at 5% per annum by ₹480. What is the sum?","options":["₹12,000","₹8,000","₹10,000","₹15,000"],"answer":0,"explanation":"Interest is 24% of the sum in the first case and 20% in the second, so 4% of the sum = 480 and the sum is ₹12,000.","difficulty":"hard","questionHi":"किसी धनराशि पर 8% वार्षिक की दर से 3 वर्ष का साधारण ब्याज, उसी धनराशि पर 5% वार्षिक की दर से 4 वर्ष के साधारण ब्याज से ₹480 अधिक है। धनराशि कितनी है?","optionsHi":["₹12,000","₹8,000","₹10,000","₹15,000"],"explanationHi":"पहली स्थिति में ब्याज राशि का 24% और दूसरी में 20% है, अतः राशि का 4% = 480 और राशि ₹12,000 है।","subtopic":"basic-formula","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-206","question":"At 8% per annum simple interest, the interest earned in the 4th and 5th years together is ₹960. What will the sum amount to after 6 years?","options":["₹8,000","₹7,440","₹9,360","₹8,880"],"answer":3,"explanation":"Each year earns the same interest, so two years earn 16% of the sum = 960 and the sum is ₹6,000. After 6 years, amount = 6,000 × 1.48 = ₹8,880.","difficulty":"hard","questionHi":"8% वार्षिक साधारण ब्याज पर 4थे और 5वें वर्ष में कुल मिलाकर ₹960 का ब्याज प्राप्त होता है। 6 वर्ष बाद यह राशि कितनी हो जाएगी?","optionsHi":["₹8,000","₹7,440","₹9,360","₹8,880"],"explanationHi":"प्रत्येक वर्ष समान ब्याज मिलता है, अतः दो वर्षों में राशि का 16% = 960 और राशि ₹6,000 है। 6 वर्ष बाद मिश्रधन = 6,000 × 1.48 = ₹8,880।","subtopic":"basic-formula","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-207","question":"The simple interest on ₹5,000 for 3 years at r% per annum is ₹600. What is the simple interest on ₹8,000 for 2 years at 2r% per annum?","options":["₹640","₹1,280","₹960","₹1,920"],"answer":1,"explanation":"5,000 × r × 3/100 = 600 gives r = 4. Then 2r = 8% and SI = 8,000 × 8 × 2/100 = ₹1,280.","difficulty":"hard","questionHi":"₹5,000 पर r% वार्षिक की दर से 3 वर्ष का साधारण ब्याज ₹600 है। ₹8,000 पर 2r% वार्षिक की दर से 2 वर्ष का साधारण ब्याज कितना होगा?","optionsHi":["₹640","₹1,280","₹960","₹1,920"],"explanationHi":"5,000 × r × 3/100 = 600 से r = 4। तब 2r = 8% और SI = 8,000 × 8 × 2/100 = ₹1,280।","subtopic":"basic-formula","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-simple-interest-208","question":"The simple interest on ₹8,000 for 2 years 6 months at a certain rate equals the simple interest on ₹5,000 at 1.5 times that rate for a certain time. What is that time?","options":["3 years 4 months","2 years 8 months","2 years 4 months","4 years"],"answer":1,"explanation":"Equal interest: 8,000 × r × 2.5 = 5,000 × 1.5r × t, so t = 20,000/7,500 = 8/3 years = 2 years 8 months.","difficulty":"hard","questionHi":"₹8,000 पर एक निश्चित दर से 2 वर्ष 6 महीने का साधारण ब्याज, ₹5,000 पर उस दर की 1.5 गुनी दर से एक निश्चित समय के साधारण ब्याज के बराबर है। वह समय क्या है?","optionsHi":["3 वर्ष 4 महीने","2 वर्ष 8 महीने","2 वर्ष 4 महीने","4 वर्ष"],"explanationHi":"ब्याज बराबर होने पर 8,000 × r × 2.5 = 5,000 × 1.5r × t, अतः t = 20,000/7,500 = 8/3 वर्ष = 2 वर्ष 8 महीने।","subtopic":"basic-formula","source":"SSC CGL Tier 2 · IBPS PO Mains"},
];

export default questions;
